INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2026-v0-081', 'bd1049f6673fe09b27627f170e59bc6af8d9f4ac', 2026, 0, 81, false, false, NULL, NULL, 'El carcinoma adenoide quístico:', '[{"position": 1, "text": "Es el tumor maligno más frecuente de las glándulas salivares."}, {"position": 2, "text": "Nunca afecta a las glándulas salivares menores a nivel del paladar."}, {"position": 3, "text": "Puede asociarse con parálisis facial debido a su neurotropismo."}, {"position": 4, "text": "Se debe tratar con radioterapia como primera opción terapéutica."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-082', 'd4f4fdde6db222bf36d03da2e64ddf32c2848fc2', 2026, 0, 82, false, false, NULL, NULL, 'Respecto a la embolia y la trombosis en las extremidades inferiores, indica la correcta:', '[{"position": 1, "text": "La trombosis arterial se da frecuentemente en pacientes con arritmia cardiaca."}, {"position": 2, "text": "Los pacientes con una embolia arterial refieren de forma habitual clínica de claudicación previa."}, {"position": 3, "text": "La embolia se trata habitualmente mediante anticoagulación."}, {"position": 4, "text": "En la angiografía de un paciente con trombosis arterial se objetiva mayor desarrollo de circulación colateral."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-083', '3ddedd608536416731e7e45331ae03ce405d6399', 2026, 0, 83, false, false, NULL, NULL, 'En un paciente con estenosis de válvula aórtica, ¿Cuál te parece el tratamiento más adecuado?:', '[{"position": 1, "text": "Recambio valvular en pacientes asintomáticos sin disfunción ventricular."}, {"position": 2, "text": "Recambio valvular en pacientes sintomáticos."}, {"position": 3, "text": "Reparación valvular en pacientes sintomáticos."}, {"position": 4, "text": "Valvuloplastia en estenosis aórtica grave y pacientes con bajo riesgo de reemplazo valvular."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-084', 'ce24e6273d88f960c330375d08bf948c69781c86', 2026, 0, 84, false, false, NULL, NULL, 'El síndrome de Stauffer es un síndrome paraneoplásico característico de (elija la correcta):', '[{"position": 1, "text": "Cáncer de riñón."}, {"position": 2, "text": "Cáncer de próstata."}, {"position": 3, "text": "Cáncer de testículo."}, {"position": 4, "text": "Cáncer vesical."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-085', '866998cb43df7df3bd06cf9f57a1550a28f1fac8', 2026, 0, 85, false, false, NULL, NULL, 'Varón de 57 años, sin comorbilidades asociadas. Presenta PSA 15 ng/ml y tacto rectal pétreo. La biopsia prostática revela adenocarcinoma de próstata Gleason 9 y el estudio de extensión muestra afectación ósea con más de 8 metástasis a nivel de esqueleto axial y metástasis hepáticas. Indique el tratamiento de elección:', '[{"position": 1, "text": "Prostatectomía radical con linfadenectomía extendida y resección de las metástasis."}, {"position": 2, "text": "Radioterapia pélvica y radioterapia estereoatáxica de las metástasis."}, {"position": 3, "text": "Braquiterapia de alta tasa prostática."}, {"position": 4, "text": "Antiandrógenos inicialmente junto a análogos de LHRH y enzalutamida (nuevos antiandrógenos) y docetaxel."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-086', 'fece4c41356726727a8aac5816c0bdd0ca649b79', 2026, 0, 86, false, false, NULL, NULL, 'Indique la afirmación correcta sobre la cistectomía radical:', '[{"position": 1, "text": "Es una cirugía que incluye la exéresis de vejiga, próstata (en el varón) y ganglios ilioobturatrices."}, {"position": 2, "text": "La morbimortalidad del procedimiento es muy baja comparada con procedimientos endoscópicos."}, {"position": 3, "text": "La derivación ureteral a piel o a intestino se realiza a los 5 días una vez el paciente se recupera del tiempo de exéresis."}, {"position": 4, "text": "Es el tratamiento de elección del cáncer de vejiga no musculo invasivo de alto grado."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-087', 'e78c5039cbb1fa77af5d20daf95ffb95873b6857', 2026, 0, 87, false, false, NULL, NULL, 'Paciente mujer de 61 años con Diabetes Mellitus II, colesterol elevado y con diagnóstico de vejiga hiperactiva desde 2021 por EUD (Estudio Urodinámico) sin más datos de interés. En tratamiento con Anticolinérgicos a dosis máximas desde 2022. En el último control en 2023 se le añade doble terapia anticolinérgicos + Agonista Beta 3. La paciente acude a la consulta y refiere no haber tenido mejoría en la sintomatología, ni con las medidas de uroterapia ni con los anticolinérgicos ni con la doble terapia de la última consulta. ¿Cuál es nuestro plan ahora?:', '[{"position": 1, "text": "Retirar los anticolinérgicos y añadir Agonistas Beta 3 a dosis máximas."}, {"position": 2, "text": "Inyección de toxina botulínica intradetrusor."}, {"position": 3, "text": "Cateterismos intermitentes."}, {"position": 4, "text": "Enterocistoplastia de aumento."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-088', '188c3483770b047fd422440dfe748a5bf64dc784', 2026, 0, 88, false, false, NULL, NULL, 'Mujer fumadora de 68 años, trabajadora de industria de caucho. Presenta polaquiuria, disuria y hematuria. Presenta urocultivo y ecografía sin alteraciones. Indique la afirmación correcta:', '[{"position": 1, "text": "Dada la ausencia de patología tumoral en la ecografía es probable que presente vejiga hiperactiva por lo que se solicitará estudio urodinámico."}, {"position": 2, "text": "Ha de realizarse cistoscopia y citologías ante riesgo de carcinoma in situ vesical."}, {"position": 3, "text": "Lo más probable es que presente una pequeña litiasis vesical que expulsará espontáneamente dada la longitud y anchura de la uretra femenina."}, {"position": 4, "text": "La disuria descarta que la paciente presente patología tumoral."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-089', 'adba12db577e53612ef33a22da4330bc2fbecce4', 2026, 0, 89, false, false, NULL, NULL, 'Joven de 33 años corredor habitual. Refiere dolor en cara externa de rodilla sobre todo en actividad deportiva, pero también al subir y bajar escaleras. El dolor se acentúa a la palpación del Epicóndilo Externo. ¿Cuál es la sospecha diagnóstica?:', '[{"position": 1, "text": "Síndrome del Osgood-Schlatter."}, {"position": 2, "text": "Síndrome de la Cintilla Ilio-Tibial."}, {"position": 3, "text": "Enfermedad de Sever."}, {"position": 4, "text": "Trocanteritis."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-090', '98803242b9a9ba48c4f24fecef8ebb3ea9c9c68a', 2026, 0, 90, false, false, NULL, NULL, '¿Cuál de las siguientes es una red-flag durante la anamnesis y exploración física de una lumbalgia?:', '[{"position": 1, "text": "Dolor lumbar de patrón mecánico."}, {"position": 2, "text": "Dolor a la palpación de espinosas."}, {"position": 3, "text": "Antecedentes personales de proceso neoplásico."}, {"position": 4, "text": "Paciente de 45 años."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-091', 'ccf64e6a57db5f6dc633a89750d043cb2730801e', 2026, 0, 91, false, false, NULL, NULL, '¿Cuál de las siguientes lesiones traumáticas precisa, para evitar complicaciones locales, un tratamiento más precoz?:', '[{"position": 1, "text": "Luxación traumática posterior de la cadera."}, {"position": 2, "text": "Fractura desplazada del cuello femoral del anciano."}, {"position": 3, "text": "Fractura trocantérica del anciano."}, {"position": 4, "text": "Fractura de cotilo."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-092', 'c7ceb11fd3c815cbeaed834b63610cf250aafa69', 2026, 0, 92, false, false, NULL, NULL, 'La fractura de Monteggia consiste en:', '[{"position": 1, "text": "Fractura de cabeza radial con rotura de la membrana intraósea."}, {"position": 2, "text": "Fractura de cabeza radial con luxación de articulación radio-cubital distal."}, {"position": 3, "text": "Fractura de cubito proximal con luxación de la cabeza de radio."}, {"position": 4, "text": "Fractura de radio distal con luxación de articulación radio-cubital distal."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-093', '999aaed6c44cbc83ca9c9ece7a9c18e2f1196e2e', 2026, 0, 93, false, false, NULL, NULL, 'En relación a las indicaciones de cirugía bariátrica, señale la correcta.', '[{"position": 1, "text": "El IMC es la mejor medida de correlación entre exceso de peso y gravedad de la enfermedad."}, {"position": 2, "text": "El IMC es una medida útil, pero que no se utiliza para la indicación de cirugía bariátrica."}, {"position": 3, "text": "El punto de corte del IMC es de 55, independientemente de las enfermedades asociadas."}, {"position": 4, "text": "Paciente con IMC por debajo de 35 y enfermedades metabólicas poco controladas se pueden beneficiar de la cirugía bariátrica."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-094', 'ce04eec30c8ea8e1cbde2c0ef504fdef0e0f3415', 2026, 0, 94, false, false, NULL, NULL, 'La cirugía de elección en un paciente con un brote severo de colitis ulcerosa que desarrolla un megacolon tóxico es:', '[{"position": 1, "text": "Proctocolectomía total + reservorio ileoanal+ ileostomía lateral."}, {"position": 2, "text": "Proctocolectomía total + ileostomía terminal."}, {"position": 3, "text": "Colectomía total + ileostomía terminal."}, {"position": 4, "text": "Colectomía total + anastomosis ileorrectal."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-095', 'e51649549a8f3b5cf64418cf76896666ea46cd16', 2026, 0, 95, false, false, NULL, NULL, 'La complicación más frecuente y grave de la duodenopancreatectomía cefálica es:', '[{"position": 1, "text": "Hemorragia."}, {"position": 2, "text": "Absceso intrabdominal."}, {"position": 3, "text": "Fístula pancreática."}, {"position": 4, "text": "Infección herida."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-096', 'd375d1bf48001b2892f768ee6be1058a226628b3', 2026, 0, 96, false, false, NULL, NULL, 'La estrategia de control de daños pretende evitar:', '[{"position": 1, "text": "Hipertermia, acidosis y coagulopatía."}, {"position": 2, "text": "Acidosis, hipotermia y coagulopatía."}, {"position": 3, "text": "Hipotermia, alcalosis y coagulopatía."}, {"position": 4, "text": "Hipertermia, alcalosis y coagulopatía."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-097', '5c5f74822307aa11087ae7730216ef7fb97af3af', 2026, 0, 97, false, false, NULL, NULL, 'Indica la afirmación FALSA en relación con la neoplasia mucinosa papilar intraductal (NPIM) del páncreas:', '[{"position": 1, "text": "Se localiza en cabeza y cuerpo, pero el 10% es multifocal (skiplesions)."}, {"position": 2, "text": "Se realiza una pancreatectomia total, ya que maligniza y es multifocal."}, {"position": 3, "text": "Existen tres tipos (I: ducto principal; II: rama secundaria III: mixto)."}, {"position": 4, "text": "En el tipo I durante la CPRE (Colangiopancreatografía retrógrada endoscópica) se produce salida de moco de la papila."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-098', '102ecb32359c55b6683e73babc8cd575927743d9', 2026, 0, 98, false, false, NULL, NULL, 'Varón de 83 años que acude a Urgencias Generales por cuadro de dolor a nivel inguinal izquierdo de 2 horas de evolución, con tumoración blanda y móvil asociada a la exploración. Se modifica con las maniobras de Valsalva y desaparece con el decúbito. Elija la respuesta CORRECTA:', '[{"position": 1, "text": "El paciente presenta una hernia inguinal reductible a la exploración."}, {"position": 2, "text": "El paciente presenta una hernia inguinal incoercible a la exploración."}, {"position": 3, "text": "El paciente presenta una hernia inguinal con pérdida de derecho a domicilio en la exploración."}, {"position": 4, "text": "El paciente presenta una hernia inguinal estrangulada a la exploración."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-099', '83fa6f68e490a366d922d6accf9067d1c7c7582c', 2026, 0, 99, false, false, NULL, NULL, 'Entre los principios oncológicos en el tratamiento del cáncer de colon se encuentran todas las siguientes afirmaciones, EXCEPTO:', '[{"position": 1, "text": "Hay que realizar una resección intestinal con márgenes quirúrgicos amplios."}, {"position": 2, "text": "No hace falta hacer linfadenectomía."}, {"position": 3, "text": "Realizar resecciones en bloque si existe sospecha de infiltración de órganos vecinos."}, {"position": 4, "text": "En ocasiones se da tratamiento neoadyuvante con quimioterapia previa a la cirugía."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-100', '74c87da4ca8e4c375ecbaf2995d51a2770735e63', 2026, 0, 100, false, false, NULL, NULL, '¿Cuál de las siguientes afirmaciones es correcta en relación al divertículo faringoesofágico de Zenker?:', '[{"position": 1, "text": "Se trata de un divertículo por tracción."}, {"position": 2, "text": "Es más frecuente en pacientes jóvenes."}, {"position": 3, "text": "Entre sus síntomas se encuentran: disfagia, regurgitación y halitosis."}, {"position": 4, "text": "La localización especifica en la parte posterior de la faringe se denomina triángulo de Farabeuf."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-101', '6a45d2d7f2d0b1b9e7a29e5d748fae8c2dd748f4', 2026, 0, 101, false, false, NULL, NULL, 'En un paciente con rinorrea acuosa unilateral y sospecha de fístula de líquido cefalorraquídeo, ¿cuál de las siguientes es una proteína que se considera marcador de líquido cefalorraquídeo?:', '[{"position": 1, "text": "Albúmina."}, {"position": 2, "text": "Prealbúmina."}, {"position": 3, "text": "Beta 2 transferrina."}, {"position": 4, "text": "Mielina."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-102', '86029ffa4601f09f6571e2bb42ab1f0ff0a3ced6', 2026, 0, 102, false, false, NULL, NULL, 'Entre los siguientes tumores benignos de senos paranasales señale cuál de ellos se asocia con malignización:', '[{"position": 1, "text": "Papiloma invertido."}, {"position": 2, "text": "Mucocele."}, {"position": 3, "text": "Schwannoma."}, {"position": 4, "text": "Osteoma."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-103', '0deff7e28e29efe030a32523acd96db21a26289c', 2026, 0, 103, false, false, NULL, NULL, '¿Cuál de las siguientes afirmaciones sobre la otitis media secretoria es CIERTA?:', '[{"position": 1, "text": "Es más frecuente en verano."}, {"position": 2, "text": "El tratamiento de elección es quirúrgico."}, {"position": 3, "text": "En la mayoría de los casos, la evolución natural es hacia la curación espontánea."}, {"position": 4, "text": "Los antihistamínicos son útiles para su resolución."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-104', '97b5b712771bc54c1c0ab27ee301f685d5015e2a', 2026, 0, 104, false, false, NULL, NULL, 'En Neonatología ingresa desde paritorio un neonato grande para la edad gestacional con hemangioma facial, macroglosia y onfalocele, que desarrolla posteriormente crisis de hipoglucemia. ¿Cuál de las siguientes afirmaciones es FALSA?:', '[{"position": 1, "text": "Se plantea el diagnóstico de Síndrome de Beckwith-Wiedemann."}, {"position": 2, "text": "La gestación por técnicas de reproducción asistida y/o detección ecográfica prenatal de polihidramnios puede estar entre sus antecedentes."}, {"position": 3, "text": "La causa más frecuente de este síndrome es la teratogénica."}, {"position": 4, "text": "No suele conllevar discapacidad intelectual, salvo complicaciones específicas asociadas como hipoxia o hipoglucemias no tratadas, entre otras."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-105', '19292df339c885e5e9efacb188d30b2aa17fc9a4', 2026, 0, 105, false, false, NULL, NULL, 'Una mujer de 37 años acude a consulta con su hijo de 14 años con discapacidad intelectual moderada-grave, sin otros hallazgos fenotípicos y conductuales significativos. Previamente le habían realizado al niño un Array-CGH y un estudio molecular de X Frágil, en los que no se detectó ninguna alteración. La señora desea planificar otra gestación y solicita asesoramiento genético previo. ¿Cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Dado que en los estudios genéticos de su hijo no se detectó ninguna alteración, no se sospecha causa genética subyacente y el riesgo de recurrencia de la discapacidad intelectual en su descendencia sería mínimo."}, {"position": 2, "text": "Con la información disponible se podría indicar un diagnóstico genético preimplantacional y/o prenatal específico para sus futuros embarazos."}, {"position": 3, "text": "Sería conveniente evaluar de nuevo al hijo y considerar previamente la realización de un estudio de secuenciación masiva, tipo exoma clínico."}, {"position": 4, "text": "Se le aconsejaría, dado el alto riesgo de recurrencia, que no planifique más embarazos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-106', '7413b21b35283312e326decbe39779c881dfa7ee', 2026, 0, 106, false, false, NULL, NULL, 'En un paciente diagnosticado de glaucoma de tensión normal, ¿Cuál de las siguientes características clínicas descartaría este diagnóstico?:', '[{"position": 1, "text": "Presión intraocular < 21 mmHg."}, {"position": 2, "text": "Angulo de drenaje cerrado en la gonioscopia."}, {"position": 3, "text": "Excavación papilar glaucomatosa."}, {"position": 4, "text": "Hipotensión sistémica nocturna."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-107', '9cc63295116b1c2498a002720df099728ee218b7', 2026, 0, 107, false, false, NULL, NULL, '¿Qué hallazgo en el fondo del ojo sugiere más frecuentemente la existencia de una metástasis coroidea?:', '[{"position": 1, "text": "Masa Pigmentada."}, {"position": 2, "text": "Drusas blandas."}, {"position": 3, "text": "Lesión amarillenta subretiniana."}, {"position": 4, "text": "Neovasos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-108', '557c3add855bb4340bf5d4b6a174372d2e87212e', 2026, 0, 108, false, false, NULL, NULL, 'Nos avisan del mostrador por un paciente de nuestro cupo que refiere dificultad para respirar. El paciente pasa rápidamente a la sala de tratamientos donde enfermería realiza una primera evaluación con toma de constantes mientras nosotros vamos llegando. A la exploración se objetivan sibilantes, tos, habla conservada, frecuencia Cardíaca 96 lpm, presión Arterial 123/78, sin uso de musculatura accesoria, frecuencia Respiratoria 18 resp/min y saturación O2 96%. ¿Cuál sería la actuación más correcta?:', '[{"position": 1, "text": "Estamos ante una crisis de asma leve, agonistas Beta -2 de acción corta con cámara entre 2 y 4 inhalaciones cada 20 minutos en la primera hora hasta mejoría. Si mejoría alta con prednisonavia oral 5-7 días y glucocorticoide inhalado más LABA, un plan de acción por escrito y revisión en consulta."}, {"position": 2, "text": "Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Tras mejoría alta con glucocorticoide inhalado más LABA, prednisonavia oral 5-7 días, un plan de acción por escrito y revisión en consulta."}, {"position": 3, "text": "Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Tras mejoría alta con amoxicilina 500 cada 12 horas pauta corta de 5 dias, glucocorticoide inhalado más LABA, prednisonavia oral 5-7 días, un plan de acción por escrito y revisión en consulta."}, {"position": 4, "text": "Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Y traslado al hospital con ambulancia para tratamiento."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-109', '1fcabc5501bf90ecdb385164b99bf8241c460334', 2026, 0, 109, false, false, NULL, NULL, 'El envejecimiento poblacional es uno de los grandes desafíos de nuestra sociedad. En la consulta del médico de familia debemos usar herramientas para intentar mejorar la calidad de vida de nuestros mayores. Debemos adaptarnos a esta realidad, ofreciendo una atención integral, centrada en la persona y orientada a la prevención, la autonomía y la calidad de vida de dichos pacientes. Si hablamos de atención al anciano en Atención Primaria, elige la respuesta INCORRECTA:', '[{"position": 1, "text": "La prescripción en cascada ocurre cuando se prescribe un fármaco para tratar síntomas originados por otro fármaco pensando que tiene una condición clínica nueva y no pensando en una reacción adversa o secundaria del fármaco inicial."}, {"position": 2, "text": "El deterioro funcional y el aumento del riesgo de enfermedad podría considerarse algo normal con el paso de los años, pero la vejes es diversa y sus cambios están influidos por factores genéticos, ambientales o socioeconómicos."}, {"position": 3, "text": "Entre las pruebas para la detección de la fragilidad está la escala de Frail que evalúa cinco dominios: fatiga, resistencia, mide la incapacidad para bajar escaleras, la deambulación y el aumento de peso."}, {"position": 4, "text": "En la consulta podemos detectar la fragilidad con múltiples pruebas y test, entre ellos podemos realizar el test de la marcha o el de test de la silla (timed up-and-go)."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-110', '1d2d41502f83851df53b716c93e197b48c6d5faa', 2026, 0, 110, false, false, NULL, NULL, 'En el cálculo del riesgo cardiovascular, si usamos el SCORE 2 para la zona de Europa bajo riesgo/España, nos hacen falta todas las siguientes variables, señala la verdadera:', '[{"position": 1, "text": "Edad, sexo, tabaco, presión arterial sistólica, colesterol total y colesterol LDL."}, {"position": 2, "text": "Edad, sexo, tabaco, presión arterial sistólica, colesterol total y lipoproteína A."}, {"position": 3, "text": "Edad, sexo, tabaco, presión arterial sistólica, colesterol total y colesterol HDL."}, {"position": 4, "text": "Edad, sexo, tabaco, presión arterial sistólica, colesterol total, lipoproteína A, triglicéridos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-111', '9c77efdf8aa8ca203dc3902ef1ba9c0e96adce19', 2026, 0, 111, false, false, NULL, NULL, 'Acude David, paciente de 21 años sin cita, a tu consulta. En su anamnesis refiere tos y odinofagia de 48 horas de evolución. En la exploración presenta exudado amigdalar, eritema en pilares posteriores faríngeos, temperatura de 38,3º C y adenopatía laterocervical derecha dolorosa. No es alérgico a ninguna medicación. Está preocupado por el tratamiento que le vas a recetar porque le cuesta mucho ‘tragar las pastillas’, señale la respuesta correcta:', '[{"position": 1, "text": "Ante la presencia de cuatro criterios de Centor, realizar test rápido de Estreptococo e iniciar tratamiento con Amoxicilina."}, {"position": 2, "text": "Ante la presencia de tres criterios de Centor, realizar test rápido de Estreptococo y si es positivo iniciar tratamiento con Amoxicilina."}, {"position": 3, "text": "Presenta un cuadro típico de faringitis, no es necesario test rápido de Estreptococo y se debería iniciar tratamiento con Amoxicilina."}, {"position": 4, "text": "Ante la presencia de dos criterios de Centor realizar test rápido de Estreptococo y si es positivo iniciar tratamiento con Azitromicina 500 mg/24 h durante tres días."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-112', '2d7b7f2691e1d54c8a50b87b2eb7d27e93961124', 2026, 0, 112, false, false, NULL, NULL, 'En el tratamiento de la Diabetes, sobre los beneficios y complicaciones de los fármacos, ¿Cuál de las siguientes afirmaciones es INCORRECTA?:', '[{"position": 1, "text": "La metformina es el fármaco más usado, puede disminuir los niveles de vitamina B 12 y hay que vigilar el filtrado glomerular, si desciende por debajo de 30 ml/min hay que suspenderla."}, {"position": 2, "text": "Los iSGLT2 bajan peso y minimizan la progresión de la Enfermedad Renal Crónica y la Albuminuria."}, {"position": 3, "text": "Los iDPP4 pueden disminuir la glicada entre 0,6-0,9 %, tienen un efecto neutro sobre el peso pero son mal toleradas y se desaconsejan en los pacientes mayores."}, {"position": 4, "text": "La tirzepatida (agonista dual GIP + aGLP1) ha demostrado bajadas de peso importante y beneficio en la esteatosis hepática asociada a disfunción metabólica (MASH)."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-113', '618d2b24873bc28c10f35e797dfd690714f6bd1a', 2026, 0, 113, false, false, NULL, NULL, 'Acude Antonia acompañada de su hijo al Centro de Salud, solicitando ayuda para pedir la ley de dependencia. ¿Cuál de las siguientes escalas básicas para valorar el área cognitiva y sus actividades básicas de la vida diaria debería realizarle su médico de familia?:', '[{"position": 1, "text": "Test de Zarit y Apgar familiar."}, {"position": 2, "text": "Escala de Goldberg y Rosemberg."}, {"position": 3, "text": "Escala de Barthel y test de Pfeiffer."}, {"position": 4, "text": "Escala de Norton y escala de Gijón."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-114', '9f1ea60d137fd08d69766ae12db59d64b3f01ed1', 2026, 0, 114, false, false, NULL, NULL, 'A tu consulta de Atención Primaria acude Fidel acompañado de su inseparable botellita de agua y su paquete de tabaco en el bolsillo de la camisa. Es un paciente conocido con EPOC. Está preocupado por su tratamiento. Su vecina Paqui le ha dicho “los corticoides son muy malos” por lo que ha decidido suspender su tratamiento inhalado. El paciente está con triple terapia, ha tenido un ingreso en el último año por reagudización de ENFERMEDAD PULMONAR OBSTRUCTIVA CRÓNICA, presenta una disnea mMRC 2 en la escala de disnea modificada y en sus analíticas presenta una eosinofilia media mayor de 300/mm3. ¿Qué deberíamos proponer a Fidel?:', '[{"position": 1, "text": "Es un paciente categoría GOLD E de la guía Global Initiative for Chronic Obstructive Lung Disease y no necesita corticoides inhalados. Explicamos al paciente su enfermedad y el porqué de su tratamiento."}, {"position": 2, "text": "Es un paciente riesgo alto, no agudizador eosinofílico. Explicamos enfermedad y el porqué de su tratamiento y retiramos corticoide inhalado."}, {"position": 3, "text": "Es un paciente riesgo alto, retiramos corticoide inhalado y ponemos doble broncodilatación. Explicamos al paciente su enfermedad y el porqué de su tratamiento."}, {"position": 4, "text": "Es un paciente riesgo alto agudizador eosinofílico, debe mantener triple terapia, explicamos al paciente su enfermedad y el porqué de su tratamiento."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-115', '6bc55a74d8d75048eb5f54da8b0483476733f733', 2026, 0, 115, false, false, NULL, NULL, 'Acude a urgencias un paciente que comenzó con dolor torácico hace 10 minutos estando comiendo en un restaurante cerca del hospital. El electrocardiograma muestra una elevación del segmento ST de 2 mm en derivaciones precordiales desde V1 a V4 ¿Cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Realizaremos una analítica de sangre con determinación de troponinas para determinar si es un infarto y así activar un cateterismo urgente."}, {"position": 2, "text": "Administraremos dosis de carga de aspirina lo antes posible."}, {"position": 3, "text": "El cateterismo ha de realizarse de forma urgente en menos de 2 horas siendo la vía femoral la primera opción por ser la más rápida."}, {"position": 4, "text": "Sospecharemos una lesión coronaria trombótica oclusiva en la arteria circunfleja."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-116', '0e1d5332bb272fcc41d9045d1e32c2e74abc6012', 2026, 0, 116, false, false, NULL, NULL, '¿En cuál de los siguientes escenarios NO ESTÁ INDICADO el implante de un DAI (desfibrilador automático implantable) ?:', '[{"position": 1, "text": "Paciente con síndrome de Brugada y síncopes de repetición sin pródromos y recuperación rápida."}, {"position": 2, "text": "Paciente con miocardiopatía hipertrófica y puntuación de score de riesgo de muerte súbita Hypertrophic Cardiomyopathy – Sudden Cardiac Death (HCM-SCD) de 7%."}, {"position": 3, "text": "Paciente con miocardiopatía dilatada isquémica con infarto de todo el territorio anterior hace 3 meses, disnea de moderados esfuerzos a pesar del tratamiento médico y Fracción de Eyección del Ventrículo Izquierdo (FEVI) 30%."}, {"position": 4, "text": "Paciente ingresado seis días con infarto agudo de miocardio revascularizado con stent en el ingreso y FEVI del 35% antes del alta."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-117', '2d5d3be6caa8961da4c7803d544972a851f905d0', 2026, 0, 117, false, false, NULL, NULL, '¿Cuál de las siguientes afirmaciones es FALSA en relación con los anticoagulantes orales de acción directa (ACODs)?:', '[{"position": 1, "text": "Existen algunos ensayos clínicos que avalan su uso en pacientes en hemodiálisis."}, {"position": 2, "text": "Tienen menos riesgo de hemorragia intracraneal que los antagonistas de la vitamina K."}, {"position": 3, "text": "Pueden administrarse en pacientes con valvulopatías y portadores de todo tipo de prótesis cardíacas."}, {"position": 4, "text": "Son igual o más eficaces que los antagonistas de la vitamina K para prevenir ictus isquémicos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-118', 'f39341ff7255694dfb4228c5e979066319abc755', 2026, 0, 118, false, false, NULL, NULL, 'Respecto a la estenosis aórtica severa, ¿cuál de las siguientes afirmaciones es FALSA?:', '[{"position": 1, "text": "Si en la auscultación existe un desdoblamiento normal del segundo ruido cardiaco, descartaremos una estenosis aórtica severa con bastante probabilidad."}, {"position": 2, "text": "En pacientes más jóvenes, la etiología más frecuente de la misma es la válvula unicúspide."}, {"position": 3, "text": "Si es sintomática y el paciente tiene más de 70 años se recomienda una prótesis percutánea tipo Transcatheter Aortic Valve Implantation (TAVI)."}, {"position": 4, "text": "La estenosis aórtica severa de bajo flujo y bajo gradiente el TAC cardíaco con valoración del calcio valvular es de utilidad."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-119', 'c4e8d02070cf137fa00379ce2f040e3cd3e5de0a', 2026, 0, 119, false, false, NULL, NULL, '¿Cuál de los siguientes síncopes NO ingresaría en cardiología para completar estudio?:', '[{"position": 1, "text": "Varón de 45 años con tres episodios de síncope precedido de cortejo vegetativo y recuperación lenta en el último año."}, {"position": 2, "text": "Varón de 75 años con fracción de eyección del ventrículo izquierdo del 40%."}, {"position": 3, "text": "Varón de 75 años con ECG con bloqueo completo de rama izquierda del haz de His."}, {"position": 4, "text": "Mujer de 37 años con síncope en reposo precedido de palpitaciones."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-120', '90e201e5cd7d8a3563aa7965aa89dd4eb98aac45', 2026, 0, 120, false, false, NULL, NULL, 'En lo que respecta al diagnóstico de la estenosis aórtica, ¿qué afirmación es FALSA?:', '[{"position": 1, "text": "La ergometría con intercambio de gases es una prueba que ha de realizarse a todos los pacientes con síntomas."}, {"position": 2, "text": "La ecocardiografía transesofágica puede ser útil si existen dudas de la severidad."}, {"position": 3, "text": "El TAC cardíaco es una prueba indispensable previa al implante de una prótesis biológica aórtica percutánea tipo Transcatheter Aortic Valve Implantation (TAVI)."}, {"position": 4, "text": "En pacientes con estenosis aórtica de bajo flujo y bajo gradiente con función ventricular izquierda deprimida, la ecocardiografía de estrés con dobutamina estaría indicada."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-121', '01dc5e3d217fea211b3a29fff5bdd441ca5be119', 2026, 0, 121, false, false, NULL, NULL, 'Varón de 56 años fumador sin otros factores de riesgo cardiovascular que acude a urgencias por dolor torácico opresivo desde hace 4 horas con un electrocardiograma inicial que muestra elevación del segmento ST en derivaciones II, II y aVF de 2 mm. A su llegada además se objetiva en la exploración física: tensión arterial 80/40 mmHg, frecuencia cardíaca 40 lpm e ingurgitación de la vena yugular, saturación de O2 basal del 95%. Auscultación cardíaca sin soplos destacables ni edemas. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Infarto agudo de miocardio con elevación del segmento ST inferior."}, {"position": 2, "text": "Infarto agudo de miocardio con elevación del segmento ST inferior con rotura del músculo papilar posterior-medial."}, {"position": 3, "text": "Infarto agudo de miocardio con elevación del segmento ST inferior y de ventrículo derecho."}, {"position": 4, "text": "Infarto con elevación del segmento ST inferior con rotura del septo interventricular."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-122', '61400661638b2217144e64ecda2e1ee92d104cf8', 2026, 0, 122, false, false, NULL, NULL, 'Respecto a la contracción global y segmentaria del ventrículo izquierdo, señale la respuesta CORRECTA:', '[{"position": 1, "text": "Ante un paciente que ingresa por insuficiencia cardiaca y vemos en el estudio ecocardiográfico que presenta una miocardiopatía dilatada con disfunción ventricular y un aneurisma apical (con la pared adelgazada e hiperecogénica), debemos pensar en un infarto agudo de la descendente anterior (DA) y activar código infarto para un cateterismo urgente."}, {"position": 2, "text": "El diagnóstico de la miocardiopatía por estrés (Tako-Tsubo) es posible a partir del electrocardiograma y la ecocardiografía (discinesia/hipocinesia severa de todos los segmentos apicales del ventrículo izquierdo con contractilidad preservada de los segmentos basales)."}, {"position": 3, "text": "Los trombos intraventriculares los veremos con más frecuencia adheridos a los segmentos del ventrículo izquierdo que mejor contracción presentan."}, {"position": 4, "text": "En la miocardiopatía arritmogénica no veremos afectada ni en la ecocardiografía ni en la resonancia cardíaca la contractilidad segmentaría del ventrículo izquierdo."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-123', '74b905c7ad666ef6d5c97c136088afdb4586d243', 2026, 0, 123, false, false, NULL, NULL, '¿Cuál de estos signos o síntomas NO sugiere taponamiento en presencia de derrame pericárdico severo sin otra patología?:', '[{"position": 1, "text": "Hipotensión arterial refractaria a fluidoterapia intensiva."}, {"position": 2, "text": "Variación de velocidades de llenado mitral y tricúspide menor del 25% con la inspiración."}, {"position": 3, "text": "Colapso de aurícula derecha y ventrículo derecho en diástole."}, {"position": 4, "text": "Situación de parada cardiorrespiratoria con actividad eléctrica sin pulso."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-124', '06589465a6c089001a66788e3f7e7d71c6131e16', 2026, 0, 124, false, false, NULL, NULL, 'Respecto a la miocardiopatía hipertrófica, ¿cuál es la respuesta CORRECTA?:', '[{"position": 1, "text": "Para hacer un diagnóstico de miocardiopatía hipertrófica, no es necesario excluir otras causas cardiacas o sistémicas de sobrecarga del ventrículo izquierdo (hipertensión arterial, estenosis aórtica, enfermedades infiltrativas, etc..)."}, {"position": 2, "text": "La obstrucción a nivel del tracto de salida del ventrículo izquierdo es típica, pero también la podemos encontrar en pacientes con hipertrofia por otro motivo, en el contexto de algún factor desencadenante como deshidratación o estados hiperdinámicos."}, {"position": 3, "text": "El patrón de realce con gadolinio en la resonancia cardíaca típicamente es en anillo subendocárdico."}, {"position": 4, "text": "La insuficiencia mitral que vemos característicamente en la miocardiopatía hipertrófica obstructiva suele ser central por dilatación del anillo."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-125', 'be4ce741e4d5716633048e2e7205a6da907a70d6', 2026, 0, 125, false, false, NULL, NULL, 'Mujer de 84 años con enfermedad de Alzheimer en fase terminal, institucionalizada desde hace tres años, dependiente para todas las actividades básicas y sin lenguaje comprensible. En los últimos seis meses ha requerido tres ingresos por neumonía por aspiración. Tras la última alta, ya en la residencia no acepta alimentos ni líquidos, mantiene la boca cerrada y rechaza la alimentación incluso con ayuda. Su hija, muy angustiada, pide “que se le ponga algo para alimentarla, aunque sea por una sonda”. ¿Cuál es la actuación más adecuada en esta situación?:', '[{"position": 1, "text": "Colocar una gastrostomía para asegurar el aporte nutricional y explicarle a la hija que debe vigilar que su madre no se la retire."}, {"position": 2, "text": "Iniciar nutrición parenteral periférica y tranquilizar a la hija diciéndole que así su madre “seguirá recibiendo alimento, aunque no coma”."}, {"position": 3, "text": "Explicar a la hija que la falta de apetito y deglución son parte del proceso natural y ofrecer cuidados centrados en aliviar el malestar y proporcionar confort."}, {"position": 4, "text": "Intentar alimentación con espesantes y suplementos hipercalóricos durante unos días, animando a la hija a insistir en que su madre abra la boca y no tosa."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-126', '6568883053dd3481d97cfcd34a1461ebb335b19f', 2026, 0, 126, false, false, NULL, NULL, 'Señale cuál de los siguientes se considera un “Hallmark” o marca del envejecimiento de tipo primario:', '[{"position": 1, "text": "Desregulación en la señalización de nutrientes."}, {"position": 2, "text": "Acortamiento de los telómeros."}, {"position": 3, "text": "Disfunción mitocondrial."}, {"position": 4, "text": "Agotamiento de células madre."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-127', '02400795a52ef61dffee9d5723cd3b19fac39300', 2026, 0, 127, false, false, NULL, NULL, 'El Índice de Barthel de un paciente que presenta incontinencia urinaria ocasional, y supervisión física para deambular y subir escaleras, pero es independiente para el resto de las actividades básicas de la vida diaria, es:', '[{"position": 1, "text": "65"}, {"position": 2, "text": "75"}, {"position": 3, "text": "85"}, {"position": 4, "text": "95"}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-128', 'fc7cdb84374300d8fa12035f8943cfa4e76388fb', 2026, 0, 128, false, false, NULL, NULL, 'Un paciente de 68 años con adenocarcinoma de páncreas metastásico en situación de últimos días de vida presenta en las últimas 24 horas agitación, desorientación y alucinaciones visuales. Recibe morfina subcutánea en perfusión continua, dexametasona y midazolam a demanda. En la exploración presenta ictericia y asterixis, sin fiebre ni signos de focalidad neurológica. Los análisis muestran bilirrubina 9 mg/dL, transaminasas x4 y amonio elevado. ¿Cuál de las siguientes medidas farmacológicas es más adecuada en este contexto?:', '[{"position": 1, "text": "Aumentar la dosis de dexametasona y añadir midazolam."}, {"position": 2, "text": "Administrar haloperidol y valorar ajustar fármacos potencialmente implicados (como corticoides y morfina)"}, {"position": 3, "text": "Iniciar lactulosa y rifaximina para tratar una posible encefalopatía hepática."}, {"position": 4, "text": "Sustituir la morfina por buprenorfina sublingual para reducir efectos neurotóxicos."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-129', '5cfc281ed63caa8e3611c4a418895c2ab5284fc4', 2026, 0, 129, false, false, NULL, NULL, 'Un paciente con carcinoma de pulmón avanzado recibe morfina oral de liberación prolongada, 120 mg cada 12 horas, con medicación extra frecuente, de hasta 3 ó 4 veces al día. A pesar de ello, refiere dolor persistente (EVA 7/10). En los últimos días ha presentado mioclonías, sueños vívidos y leve confusión intermitente, sin fiebre ni datos de progresión tumoral. La función renal muestra un filtrado glomerular estimado de 40 mL/min/1,73m². ¿Cuál de las siguientes estrategias es la más adecuada para optimizar el control del dolor y mejorar la sintomatología?:', '[{"position": 1, "text": "Aumentar la dosis de morfina un 25–50 % y asociar benzodiacepinas para controlar las mioclonías."}, {"position": 2, "text": "Reducir la dosis de morfina a la mitad y añadir un coadyuvante no opioide (AINE)."}, {"position": 3, "text": "Rotar a fentanilo transdérmico calculando la dosis equianalgésica y reduciéndola un 30–50 % por tolerancia cruzada incompleta."}, {"position": 4, "text": "Suspender el opioide oral y sustituirlo por buprenorfina sublingual a dosis bajas."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-130', '1791340769c2a44635e15d221ace5867f75d8f34', 2026, 0, 130, false, false, NULL, NULL, 'Un hombre de 81 años, independiente para las actividades básicas, con hipertensión y diabetes bien controladas, es diagnosticado de adenocarcinoma de próstata oligometastásico, con un PSA de 42 ng/mL y una única lesión ósea asintomática en el sacro. Su estado funcional (ECOG 1) es bueno, aunque presenta fragilidad leve y polifarmacia. El equipo médico debate distintas estrategias terapéuticas (tratamiento hormonal, radioterapia dirigida o vigilancia). Antes de decidir la mejor opción terapéutica, ¿qué aspectos deben considerarse de forma prioritaria en este paciente?:', '[{"position": 1, "text": "El nivel de PSA y el número de lesiones metastásicas detectadas."}, {"position": 2, "text": "La posibilidad de aplicar el tratamiento más agresivo disponible, dado que hay enfermedad metastásica."}, {"position": 3, "text": "Comorbilidades, el estado funcional y la expectativa de vida."}, {"position": 4, "text": "La edad cronológica del paciente como criterio principal para limitar el tratamiento."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2026-v0-131', 'c4108cfa48d7c2f57498ed27fa2a1ae81d90355f', 2026, 0, 131, false, false, NULL, NULL, '¿Cuál es la técnica de elección para la determinación de la expresión de PDL1 en muestra tumoral?:', '[{"position": 1, "text": "Secuenciación masiva."}, {"position": 2, "text": "Inmunohistoquímica."}, {"position": 3, "text": "Western blot."}, {"position": 4, "text": "Hibridación in situ (FISH)."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-132', '2fbc2a6e8737d9b7c36a35a0dcfd71f3c1fe2f62', 2026, 0, 132, false, false, NULL, NULL, 'Varón de 63 años con carcinoma de próstata resistente a la castración con metástasis ganglionares y óseas múltiples. Actualmente, se encuentra en tratamiento con Enzalutamida. Acude a consulta por dolor lumbar de reciente aparición, aunque refiere no haber tomado analgesia. Reconoce episodios de incontinencia urinaria. A la exploración se detecta un ligero déficit motor en extremidad inferior izquierda (3/5). ¿Cuál sería la mejor actitud a seguir con este paciente?:', '[{"position": 1, "text": "Realización de resonancia magnética urgente."}, {"position": 2, "text": "Administración de dexametasona 10 mg."}, {"position": 3, "text": "Administración de AINEs y reevaluación en 48 horas."}, {"position": 4, "text": "Realización de radiografía simple de columna."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-133', '32a3277938b3408b9385c59d9a2ba0690e3d141a', 2026, 0, 133, false, false, NULL, NULL, 'Paciente varón de 63 años con antecedentes de miastenia gravis. Ha sido diagnosticado recientemente de melanoma estadio IV con extensa carga de enfermedad con afectación hepática múltiple, pulmonar bilateral y adenopatías generalizadas. Se realiza una determinación de BRAF por inmunohistoquímica siendo positiva para V600E. ¿Cuál sería el tratamiento más razonable teniendo en cuenta el riesgo beneficio?:', '[{"position": 1, "text": "Pembrolizumab."}, {"position": 2, "text": "Nivolumab."}, {"position": 3, "text": "Dabrafenib-Trametinib."}, {"position": 4, "text": "Nivolumab-Ipilimumab."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-134', 'a6cdffe1a530b4038e4cf113e287c0241d3a3e1e', 2026, 0, 134, false, false, NULL, NULL, 'Paciente de 92 años que acude a la consulta de Atención Primaria y se le realiza una evaluación de fragilidad según los criterios de Linda P. Fried. Objetivamos los siguientes resultados: Pérdida de peso de 2kg el año previo, fuerza prensora normal para su IMC, no refiere baja resistencia o agotamiento, presenta lentitud de la marcha y un nivel normal de actividad física. ¿Cuál sería su nivel de fragilidad?:', '[{"position": 1, "text": "Robusto."}, {"position": 2, "text": "Pre-frágil."}, {"position": 3, "text": "Frágil."}, {"position": 4, "text": "Discapacitado."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-135', 'c0203b6cf04b48f21f34388243ebe86ddc420596', 2026, 0, 135, false, false, NULL, NULL, 'Acude a urgencias un varón de 25 años con una uveítis anterior izquierda. En su historial clínico únicamente destaca que ha tenido úlceras orales dolorosas con cierta frecuencia en los últimos dos años. Refiere la aparición de una pápula eritematosa alrededor del sitio de punción de la vacuna antigripal, que recibió recientemente. ¿Cuál es el diagnóstico más probable?:', '[{"position": 1, "text": "Sarcoidosis."}, {"position": 2, "text": "Sífilis."}, {"position": 3, "text": "Enfermedad de Behçet."}, {"position": 4, "text": "Enfermedad de Crohn."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-136', '0cbf4affa5be6ef8d6807fabfe2b951a57bf58f0', 2026, 0, 136, false, false, NULL, NULL, 'Acude a su consulta un varón de 70 años con rigidez matutina y dolor a la movilización de cintura escapular y pélvica bilateral, desde hace tres meses, sin afectación de otras articulaciones periféricas. En la analítica destacan una leve anemia normocítica normocrómica y una velocidad de sedimentación glomerular de 85 mm en la primera hora. El factor reumatoide y los anticuerpos antipeptídicos citrulinados son negativos. ¿Cuál es su diagnóstico?:', '[{"position": 1, "text": "Artritis reumatoide seronegativa."}, {"position": 2, "text": "Polimialgia reumática."}, {"position": 3, "text": "Artritis indiferenciada."}, {"position": 4, "text": "Artrosis."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-137', 'b10908307f16955823e990b45470566154e375d3', 2026, 0, 137, false, false, NULL, NULL, 'En un paciente ingresado por un shock hipovolémico, con oliguria ¿cuál de los siguientes hallazgos sugiere el desarrollo de necrosis tubular aguda?:', '[{"position": 1, "text": "Sodio urinario < 20 mEq/L."}, {"position": 2, "text": "Excreción fraccional de sodio <1%."}, {"position": 3, "text": "Cociente creatinina urinaria/creatinina plasmática mayor de 40."}, {"position": 4, "text": "Osmolalidad urinaria menor de 350 mOsmoles/Kg."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-138', 'f51235bb1330d94a0311ab7ea0678193a4a9958e', 2026, 0, 138, false, false, NULL, NULL, 'Varón de 80 años con gonartrosis. Acude a estudio preoperatorio previo a prótesis de rodilla derecha. Su hemograma es normal. Los tests de coagulación muestran INR:1, tiempo de cefalina-caolín 47´´ (valor normal 27-37). La agregación plaquetaria con ristocetina está ligeramente alterada, pero es normal con colágeno y ADP. El paciente no refiere ninguna clínica hemorrágica. ¿Cuál es la causa de esta alteración en las pruebas de coagulación?:', '[{"position": 1, "text": "Heterocigosis para hemofilia A."}, {"position": 2, "text": "Enfermedad de von Willebrand tipo I."}, {"position": 3, "text": "Anticoagulante lúpico."}, {"position": 4, "text": "Síndrome de Bernard-Soulier."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-139', '89ef4c22aaca4fb64daab37305405c0af53c0515', 2026, 0, 139, false, true, NULL, NULL, 'Mujer de 55 años diagnosticada de lupus eritematoso sistémico. Consulta por astenia en los últimos tres meses. En la analítica destacan eritrocitos: 3x10¹²/L, Hemoglobina: 9,1 g/dL, volumen corpuscular medio: 81 fL, reticulocitos: 250x10⁹/L, leucocitos: 7.2x10⁹/L, plaquetas: 230x10⁹/L. Sideremia: 25 mcg/dL, saturación de transferrina: 19%. Ferritina: 400 ng/mL ¿Qué tipo de anemia tiene esta paciente?:', '[{"position": 1, "text": "Anemia inflamatoria crónica."}, {"position": 2, "text": "Anemia ferropénica."}, {"position": 3, "text": "Anemia hemolítica."}, {"position": 4, "text": "Talasemia menor."}]'::jsonb, 4, NULL, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-140', 'b293a54daa5e2a17a8ba91e53f18ee1aabd9d0ef', 2026, 0, 140, false, false, NULL, NULL, 'Varón de 55 años que tuvo un síndrome coronario agudo hace un año. Acude a consulta de su médico de atención primaria para hacer una revisión, encontrándose asintomático. Su presión arterial es de 135/85 mmHg, sus niveles de colesterolLDL son de 100 mg/dL. En relación con la prevención secundaria de la cardiopatía isquémica, ¿es necesario hacer algún ajuste terapéutico?:', '[{"position": 1, "text": "Hay que optimizar el tratamiento antihipertensivo porque los niveles de presión arterial están por encima de los niveles objetivo."}, {"position": 2, "text": "Hay que optimizar el tratamiento hipolipemiante porque los niveles de colesterolLDL están por encima de los niveles objetivo."}, {"position": 3, "text": "Tanto los niveles de presión arterial como los niveles de colesterol-LDL se encuentran dentro del rango objetivo."}, {"position": 4, "text": "Hay que optimizar el tratamiento de la presión arterial y el tratamiento hipolipemiante."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-141', '84945467624a13d3b0bc531b66bcd9a6fb7b2d04', 2026, 0, 141, false, false, NULL, NULL, 'Acude al servicio de urgencias una mujer de 67 años con astenia, náuseas y cefalea. Tiene antecedentes de hipertensión arterial actualmente en tratamiento con enalaprilhidroclorotiazida (20/12.5mg) y diabetes mellitus tipo 2 en tratamiento con metformina. Su tensión arterial es de 138/88 mmHg y su frecuencia cardíaca 80 latidos por minuto. La exploración física es normal, se encuentra bien hidratada y no tiene edemas. En la analítica realizada en urgencias encontramos: sodio 122 mEq/L, potasio: 4.3mEq/L, creatinina 0.8mg/dL. La osmolalidad plasmática es 257mOsm/kg y el sodio urinario 45 mEq/L. Hace un mes estuvo en la consulta de su médico de familia, quien le cambió el tratamiento antihipertensivo y le hizo una analítica general que fue normal. ¿Cuál es su diagnóstico?:', '[{"position": 1, "text": "Hiponatremia inducida por tiazidas."}, {"position": 2, "text": "Insuficiencia suprarrenal."}, {"position": 3, "text": "Potomanía."}, {"position": 4, "text": "Pseudohiponatremia por hiperglucemia."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-142', '26fc908672ec9b01672e3cae358a77832a8dbf2d', 2026, 0, 142, false, true, NULL, NULL, 'Valora en la consulta a una paciente de 56 años por un cuadro de unos 10 días de febrícula, bocio de pequeño tamaño, levemente doloroso a la presión y que muestra un aumento de la vascularización tiroidea en la ecografía. Está ansiosa, levemente sudorosa. Su frecuencia cardíaca es de 100 latidos por minuto y su presión arterial de 145/75 mmHg ¿Cuál de las siguientes combinaciones de hallazgos complementarios esperaría según su sospecha diagnóstica?:', '[{"position": 1, "text": "TSH baja, T4 libre elevada, anticuerpos estimulantes del tiroides negativos e hipocaptación de iodo en la gammagrafía tiroidea."}, {"position": 2, "text": "TSH baja, T4 libre elevada, anticuerpos estimulantes del tiroides positivos e hipercaptación de iodo en la gammagrafía tiroidea."}, {"position": 3, "text": "TSH elevada, T4 libre elevada, anticuerpos estimulantes del tiroides negativos e hipercaptación de iodo en la gammagrafía tiroidea."}, {"position": 4, "text": "TSH baja, T4 libre elevada, anticuerpos estimulantes del tiroides positivos e hipocaptación de iodo en la gammagrafía tiroidea."}]'::jsonb, 4, NULL, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-143', '64990015e4a60492d853b838804858fff27e6f84', 2026, 0, 143, false, false, NULL, NULL, 'Un paciente de 39 años que presenta emisión recidivante de orina rojiza, episodios repetidos de dolor abdominal de etiología no diagnosticada, acude a urgencias con un nuevo episodio de dolor abdominal intenso. En los estudios realizados en urgencias se objetiva una trombosis venosa mesentérica. ¿Cuál es el diagnóstico de sospecha que considera más probable?:', '[{"position": 1, "text": "Hemoglobinuria paroxística nocturna."}, {"position": 2, "text": "Síndrome antifosfolípido."}, {"position": 3, "text": "Coproporfiria eritropoyética."}, {"position": 4, "text": "Fiebre mediterránea familiar."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-144', 'd2e73f576d07f08fdd288b2fee9cac7bb8f70948', 2026, 0, 144, false, false, NULL, NULL, 'Un paciente de 56 años ha perdido 10kg en el último año coincidiendo con un notable aumento de las deposiciones que son pastosas, amarillas y flotantes. Presenta dolor epigástrico-mesogástrico postprandial que limita la ingesta. Hace 4 años recibió tratamiento erradicador de Helicobacter Pylori por úlcera duodenal recidivante. ¿Cuál de las siguientes exploraciones en heces le parece más útil en el primer estudio para orientar el diagnóstico?:', '[{"position": 1, "text": "Estudio coproparasitario."}, {"position": 2, "text": "Aclaramiento fecal de alfa-1-antitripsina."}, {"position": 3, "text": "Determinación de antígeno de Helicobacter Pylori en heces."}, {"position": 4, "text": "Cuantificación de elastasa fecal."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-145', '60bc412f19692e3a8249c9f41ef024e082c76f23', 2026, 0, 145, false, false, NULL, NULL, 'Según el Real decreto 888/2022, ¿a partir de qué grado se reconoce oficialmente la condición de persona con discapacidad en España (anteriormente llamada “minusvalía”) ?:', '[{"position": 1, "text": "25%."}, {"position": 2, "text": "30%."}, {"position": 3, "text": "33%."}, {"position": 4, "text": "45%."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-146', '284277a2fd3d5776f98c7eea0bdbd9af2ef1fd01', 2026, 0, 146, false, false, NULL, NULL, 'En la prescripción de ayudas para la marcha, es importante conocer qué músculos intervienen para potenciarlos en caso de que puedan estar deficitarios. ¿Cuál de los siguientes músculos NO es prioritario en el control de la marcha asistida?:', '[{"position": 1, "text": "Flexores de dedos."}, {"position": 2, "text": "Extensores de muñecas."}, {"position": 3, "text": "Pronador redondo."}, {"position": 4, "text": "Tríceps braquial."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-147', 'f83a30f20515af5f51b7e4810c5fddad9e82dd64', 2026, 0, 147, false, false, NULL, NULL, 'Mujer de 72 años, con antecedentes personales de enfermedad pulmonar obstructiva crónica y artrosis. Toma antiinflamatorio no esteroideo clásico diario y ácido acetilsalicílico a baja dosis. Acude a urgencias por presentar melenas. En la endoscopia de urgencias se objetiva una úlcera gástrica Forrest III en curvatura menor, con biopsias negativas para malignidad y Helicobacter pylori negativo. Conducta más adecuada a medio plazo:', '[{"position": 1, "text": "Reiniciar antiinflamatorio no esteroideo y ácido acetilsalicílico igual, con inhibidor de la bomba de protones 2 semanas."}, {"position": 2, "text": "Mantener inhibidor de la bomba de protones a dosis plenas, reevaluar la necesidad de antiinflamatorio no esteroideo y realizar endoscopia de control para confirmar cicatrización."}, {"position": 3, "text": "Cambiar inhibidor de la bomba de protones por antih2."}, {"position": 4, "text": "Cambiar antiinflamatorio no esteroideo por paracetamol e inhibidor de la bomba de protones a demanda."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-148', '4f5fc0f5c66bc52c173bbca6dbbe496daf39edc6', 2026, 0, 148, false, false, NULL, NULL, 'Paciente varón de 58 años, con historia de más de 15 años de pirosis y regurgitación, tratada de forma intermitente con inhibidores de la bomba de protones. No fumador, índice de masa corporal de 35 kg/m². Consulta por empeoramiento de los síntomas. Se realiza gastroscopia en la que se objetiva un segmento de mucosa columnar de 5 cm por encima de la unión esófago-gástrica (C3M5), sin lesiones nodulares. Se toman biopsias con el resultado siguiente: metaplasia intestinal con displasia de bajo grado en dos cilindros. La revisión por un patólogo experto en esófago de Barrett confirma la presencia de displasia de bajo grado verdadera. Según las recomendaciones actuales de manejo del Barrett con displasia confirmada, la actitud MÁS adecuada es:', '[{"position": 1, "text": "Mantener inhibidor de la bomba de protones a demanda y repetir endoscopia de control a los 3 años."}, {"position": 2, "text": "Repetir endoscopia en 12 meses sin otras medidas, dado que es displasia de bajo grado."}, {"position": 3, "text": "Ofrecer ablación por radiofrecuencia mediante endoscopia en centro experto, manteniendo inhibidor de la bomba de protones."}, {"position": 4, "text": "Indicar esofaguectomía subtotal profiláctica por el riesgo acumulado de carcinoma."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-149', '87d2d396722f787464a985d41af571f907961427', 2026, 0, 149, false, false, NULL, NULL, 'Paciente de 52 años, con pirosis y dolor retroesternal. Se le realiza una endoscopia alta en la que se observa esofagitis erosiva grado C de Los Ángeles. ¿Cuál de las siguientes afirmaciones es CORRECTA?:', '[{"position": 1, "text": "Un ciclo corto de 2 semanas de inhibidor de la bomba de protones sería suficiente para asegurar la curación mucosa esofágica."}, {"position": 2, "text": "Debe plantearse tratamiento de mantenimiento con inhibidor de la bomba de protones a largo plazo."}, {"position": 3, "text": "Una vez curada la esofagitis, no existe riesgo aumentado de Barrett."}, {"position": 4, "text": "El tratamiento de elección son los anti-h2 nocturnos como monoterapia."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-150', 'c50453df8f2921318cee7ff5ea3e288552cf85e1', 2026, 0, 150, false, false, NULL, NULL, 'Respecto a la diferenciación entre colitis ulcerosa y colitis de Crohn, señale la opción MÁS correcta:', '[{"position": 1, "text": "La afectación parcheada y el recto respetado obligan siempre a diagnosticar Crohn."}, {"position": 2, "text": "La presencia de granulomas no caseificantes en biopsia colónica es fuertemente sugestiva de Crohn."}, {"position": 3, "text": "La afectación continua desde el recto hasta el ciego es típica de Crohn colónica pura."}, {"position": 4, "text": "La afectación del íleon terminal nunca aparece en la colitis ulcerosa."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-151', '68fced9949d6227f9773a1cbf4343cad1c17cb89', 2026, 0, 151, false, false, NULL, NULL, 'Paciente con 23 años, quiere saber si es celíaco, porque su madre lo es. Pregunta sobre el estudio genético. Respecto al papel del estudio genético HLA-DQ2/DQ8 en enfermedad celíaca, señale la opción CORRECTA:', '[{"position": 1, "text": "Es una prueba diagnóstica confirmatoria cuando es positiva."}, {"position": 2, "text": "Un resultado negativo para HLA-DQ2 y HLA-DQ8 hace muy improbable el diagnóstico de enfermedad celíaca."}, {"position": 3, "text": "Solo es útil en el cribado poblacional general."}, {"position": 4, "text": "Debe solicitarse de rutina en todos los pacientes con serología positiva."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-152', '347c62194c71425482e17af95b481cc4a65a4369', 2026, 0, 152, false, false, NULL, NULL, 'Paciente con pancreatitis aguda grave por litiasis biliar, necrosis extensa estéril del cuerpo y cola. A las 3 semanas, fiebre, dolor persistente, PCR elevada. En el TAC de abdomen con contraste se observa una colección encapsulada con niveles líquidoaire y necrosis pancreática. ¿Cuál es la conducta MÁS adecuada?:', '[{"position": 1, "text": "Laparotomía urgente con necrosectomía abierta."}, {"position": 2, "text": "Mantener tratamiento conservador, la presencia de gas no sugiere infección."}, {"position": 3, "text": "Abordaje escalonado: drenaje mínimamente invasivo (endoscópico/percutáneo) guiado y necrosectomía diferida si es necesario."}, {"position": 4, "text": "Esclerosis percutánea con alcohol absoluto."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-153', 'f88be467ad00f1f0e9ebf92b2ae52f3f33e8a4f9', 2026, 0, 153, false, false, NULL, NULL, 'En relación con el cribado de cáncer colorrectal en el síndrome de Lynch (MLH1/MSH2), señale la opción CORRECTA:', '[{"position": 1, "text": "El paciente debe hacerse colonoscopias cada 10 años desde los 50 años."}, {"position": 2, "text": "El paciente debe hacerse colonoscopias cada 5 años desde los 40 años o 10 años antes del caso más joven."}, {"position": 3, "text": "El paciente debe hacerse colonoscopias cada 1-2 años desde los 20-25 años o 25 años antes del caso más joven en la familia."}, {"position": 4, "text": "El paciente debe hacerse colonoscopias solo si test de sangre oculta en heces es positivo."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-154', '0066953f589b8a5ed46cf9d5591ddfab87cdb469', 2026, 0, 154, false, false, NULL, NULL, 'Mujer de 55 años con diarrea acuosa crónica, no sanguinolenta, de meses de evolución, con colonoscopia macroscópicamente normal. Las biopsias colónicas muestran infiltrado inflamatorio de la lámina propia con banda colágena subepitelial engrosada >10 μm. El diagnóstico MÁS probable es:', '[{"position": 1, "text": "Colitis ulcerosa izquierda."}, {"position": 2, "text": "Enfermedad de Crohn colónica."}, {"position": 3, "text": "Colitis microscópica linfocítica."}, {"position": 4, "text": "Colitis microscópica colágena."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-155', 'f2d70031491b442486bd253548d143865b050f94', 2026, 0, 155, false, false, NULL, NULL, 'Paciente de 32 años con colitis ulcerosa extensa de 10 años de evolución, en remisión clínica y endoscópica, sin displasia en colonoscopias previas. ¿Cree que debe realizarse colonoscopias de revisión para la vigilancia endoscópica del cáncer colorrectal?:', '[{"position": 1, "text": "No precisa vigilancia hasta los 20 años de evolución."}, {"position": 2, "text": "Debe realizarse colonoscopia con cromoendoscopia dirigida cada 3-5 años."}, {"position": 3, "text": "Solo es necesario control si presenta antecedentes familiares de CCR."}, {"position": 4, "text": "La biopsia aleatoria en todos los segmentos ha sustituido completamente a la cromoendoscopia."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-156', 'ebc5c3a607b5d02346226b22b1cb36a8d61cb05f', 2026, 0, 156, false, false, NULL, NULL, '¿Cómo se define actualmente la hipertensión pulmonar?:', '[{"position": 1, "text": "Presión media en arteria pulmonar en reposo medida por cateterismo cardíaco > 20 mmHg."}, {"position": 2, "text": "Presión media en arteria pulmonar en reposo medida por cateterismo cardíaco > 25 mmHg."}, {"position": 3, "text": "Presión sistólica en arteria pulmonar en reposo medida por ecocardiografía > 25 mmHg."}, {"position": 4, "text": "Presión sistólica en arteria pulmonar en reposo medida por cateterismo cardíaco > 20 mmHg."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-157', 'c99157257417f7a42e1678b26a304b5e39300134', 2026, 0, 157, false, false, NULL, NULL, '¿En qué casos debe priorizarse la indicación de tratamiento con CPAP para la apnea obstructiva del sueño (AOS)?:', '[{"position": 1, "text": "Pacientes con índice de apneas-hipopneas (IAH) ≥ 5 eventos/hora sin síntomas ni comorbilidades."}, {"position": 2, "text": "Todo paciente con AOS independientemente de la clínica o las comorbilidades."}, {"position": 3, "text": "Pacientes con IAH ≥ 30 eventos/hora asintomáticos."}, {"position": 4, "text": "Pacientes con IAH ≥ 15 eventos/hora y somnolencia diurna (Epworth> 10 puntos)."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-158', 'fc68581ca4c78315249ba1d95569eee9c756c0e7', 2026, 0, 158, false, false, NULL, NULL, 'En el Síndrome de Distrés Respiratorio Agudo (SDRA), ¿cuál de las siguientes opciones es el hallazgo fisiopatológico característico?:', '[{"position": 1, "text": "Aumento del espacio muerto anatómico sin alteración del intercambio gaseoso."}, {"position": 2, "text": "Hipoxemia con PaO₂/FiO₂ ≤ 300 asociada a shunt intrapulmonar y disminución de la distensibilidad."}, {"position": 3, "text": "Hipercapnia leve con aumento de la compliance pulmonar."}, {"position": 4, "text": "Aumento de la presión alveolar de CO₂ con distensibilidad normal."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-159', '6d868d93dba004d1e0e9e57ab934e57c9503f909', 2026, 0, 159, false, false, NULL, NULL, 'Un paciente con bronquitis crónica tabáquica ha desarrollado hipertensión pulmonar crónica secundaria. ¿Cuál es el mecanismo fisiopatológico principal que produce la hipertensión arterial pulmonar en esta situación?:', '[{"position": 1, "text": "Microtromboembolismo pulmonar crónico múltiple por disfunción endotelial hipóxica."}, {"position": 2, "text": "Remodelado vascular por disfunción endotelial primaria."}, {"position": 3, "text": "Vasoconstricción hipóxica crónica."}, {"position": 4, "text": "Disfunción ventricular izquierda y aumento retrógrado de la presión."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-160', '0a83baedbea9fd4dd8a7c0b33db48ea99d539e2d', 2026, 0, 160, false, false, NULL, NULL, 'En el contexto de la Fibrosis Quística (FQ), ¿qué función principal tiene la proteína CFTR en el epitelio de las vías respiratorias?:', '[{"position": 1, "text": "Actúa como un canal que transporta cloro y regula la hidratación de las secreciones."}, {"position": 2, "text": "Transporta glucosa al interior de las células epiteliales para obtener energía."}, {"position": 3, "text": "Es una enzima que degrada el moco espeso acumulado en los bronquios."}, {"position": 4, "text": "Estimula la contracción de los cilios para expulsar las secreciones bronquiales."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-161', 'ec09f7386f71488be454d244efde4a100fd52de8', 2026, 0, 161, false, true, NULL, NULL, 'Mujer de 73 años, exbebedora importante, con cuadros de palpitaciones ocasionales no estudiados, intervenida hace 2 años de una neoplasia de mama izquierda, con resección completa y vaciamiento ganglionar que acude a consulta para estudio por una tos seca de 3 meses de evolución que va aumentando progresivamente. El cuadro se acompaña de sensación disneica con los esfuerzos. En la radiografía simple del tórax se aprecia un derrame pleural izquierdo. Se realiza una toracocentesis diagnóstica y nos da un líquido ligeramente hemático con la siguiente bioquímica: pH 7,34, proteínas 6,8 gr/dl (en plasma 8 gr/dl), glucosa 73 mg/dl (plasma 70 mg/dl). ¿Cuál es la causa más probable del derrame pleural?:', '[{"position": 1, "text": "Insuficiencia cardíaca de novo."}, {"position": 2, "text": "Cirrosis hepática."}, {"position": 3, "text": "Metástasis pleural de la neoplasia de mama."}, {"position": 4, "text": "Síndrome nefrótico La citrulina se condensa con glutamato para formar argininosuccinato en el citosol."}]'::jsonb, 4, NULL, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-162', 'd983199f8023ec461d1551deef863e6c95debb20', 2026, 0, 162, false, false, NULL, NULL, '¿En cuál de las siguientes situaciones se debe realizar prioritariamente un estudio etiológico completo en un paciente con neumonía adquirida en la comunidad (NAC)?:', '[{"position": 1, "text": "En pacientes con NAC grave, hospitalizados o que no responden al tratamiento empírico."}, {"position": 2, "text": "En pacientes jóvenes sin comorbilidades para evitar el uso de antibióticos de amplio espectro."}, {"position": 3, "text": "En todos los pacientes con diagnóstico de NAC para guiar el tratamiento inicial."}, {"position": 4, "text": "Únicamente en pacientes con factores de riesgo epidemiológico, como viajes recientes."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-163', 'a3f4644676eaf24cb30e8a16dd48a7c6de4bbd11', 2026, 0, 163, false, false, NULL, NULL, '¿En cuál de las siguientes enfermedades el lavado broncoalveolar NO tiene un papel relevante para el diagnóstico?:', '[{"position": 1, "text": "Histiocitosis de células de Langerhans pulmonar."}, {"position": 2, "text": "Neumonía eosinofílica crónica."}, {"position": 3, "text": "Neumonía intersticial usual idiopática."}, {"position": 4, "text": "Sarcoidosis."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-164', '0f2670c497b82592bfb759ff6e9ada3063bca6b7', 2026, 0, 164, false, false, NULL, NULL, '¿Cuál de los siguientes hallazgos en el líquido cefalorraquídeo (LCR) hace cuestionar el diagnóstico de esclerosis múltiple?:', '[{"position": 1, "text": "Presencia de bandas oligoclonales."}, {"position": 2, "text": "Pleocitosis leve linfocitaria."}, {"position": 3, "text": "Hiperproteinorraquia>100 mg/dl."}, {"position": 4, "text": "Índice IgG elevado."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-165', 'fe6902f5a8da6f4a0d57f6f5d852c4a5a01278d4', 2026, 0, 165, false, false, NULL, NULL, '¿Cuál es la tríada clínica característica de la hidrocefalia normotensiva del adulto?:', '[{"position": 1, "text": "Trastorno de la marcha, incontinencia urinaria y deterioro cognitivo."}, {"position": 2, "text": "Cefalea, vómitos y rigidez de nuca."}, {"position": 3, "text": "Diplopía, papiledema y tinnitus pulsátil."}, {"position": 4, "text": "Vómitos, bradicardia y alteración del nivel de conciencia."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-166', '6a2db19f1019e8de81a9b1a3e6f3c93a6acb5a1c', 2026, 0, 166, false, false, NULL, NULL, 'En relación con la narcolepsia tipo 1, ¿cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Se asocia a deficiencia de hipocretina (orexina) en el líquido cefalorraquídeo."}, {"position": 2, "text": "No cursa con cataplejía ni alteraciones del sueño REM."}, {"position": 3, "text": "Es más frecuente en mujeres y se asocia a exceso de serotonina."}, {"position": 4, "text": "No se relaciona con ningún alelo HLA específico."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-167', 'fdd43215ac0a454cb99b5761aa002b8873cf20c2', 2026, 0, 167, false, false, NULL, NULL, 'Respecto al diagnóstico diferencial de las crisis epilépticas, ¿cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Los síncopes neuromediados tienen una fase tónica prolongada."}, {"position": 2, "text": "En las crisis psicógenas el electroencefalograma (EEG) muestra siempre descargas epileptiformes."}, {"position": 3, "text": "La amnesia global transitoria cursa con pérdida de conciencia prolongada."}, {"position": 4, "text": "Los síncopes presentan recuperación rápida sin confusión proscritica."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-168', 'bfee5c994c63ad520763123500689d26b10bd7cd', 2026, 0, 168, false, false, NULL, NULL, '¿Cuál de las siguientes características es típica de la cefalea tensional?:', '[{"position": 1, "text": "Dolor pulsátil bilateral con fotofobia."}, {"position": 2, "text": "Dolor pulsátil unilateral."}, {"position": 3, "text": "Dolor opresivo bilateral."}, {"position": 4, "text": "Dolor que empeora con el ejercicio físico."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-169', '1a1210a093fa42fc53ab2e4bfe10203d955c9e97', 2026, 0, 169, false, false, NULL, NULL, '¿Cuál de los siguientes hallazgos apoya el diagnóstico de enfermedad de Parkinson según los criterios de la Movement Disorder Society (MDS)?:', '[{"position": 1, "text": "Ausencia de respuesta al tratamiento con levodopa."}, {"position": 2, "text": "Pérdida de olfato."}, {"position": 3, "text": "Caídas recurrentes en los primeros años."}, {"position": 4, "text": "Disfunción cerebelosa precoz."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-170', '34996177a3cc1c5a1d87da3c78fff1f443dc87ea', 2026, 0, 170, false, false, NULL, NULL, 'En la exploración del tono muscular, ¿qué caracteriza a la hipertonía espástica?:', '[{"position": 1, "text": "Aumento de la resistencia constante durante todo el movimiento."}, {"position": 2, "text": "Aumento de la resistencia dependiente de la velocidad del movimiento."}, {"position": 3, "text": "Disminución del tono con ausencia de resistencia."}, {"position": 4, "text": "Resistencia irregular con fenómeno de rueda dentada."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-171', '7a611a2865cba98b0bd746bb9fc15ef158d31d6f', 2026, 0, 171, false, false, NULL, NULL, 'Una mujer de 53 años es diagnosticada de vólvulo de intestino medio e isquemia intestinal. Se realiza laparotomía para liberar la obstrucción intestinal. ¿Cuál de las siguientes estructuras se usa como punto de referencia anatómico para determinar la posición de la unión duodenoyeyunal?:', '[{"position": 1, "text": "Ligamento de Treitz."}, {"position": 2, "text": "Arteria mesentérica superior."}, {"position": 3, "text": "Arteria mesentérica inferior."}, {"position": 4, "text": "Ligamento frenocólico"}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-172', 'eb716d73d9deb15f39c7adcf73d76c4cec86af9b', 2026, 0, 172, false, false, NULL, NULL, 'Recién nacido a término con macrosomía, macroglosia, onfalocele e hipoglucemias persistentes por hiperinsulinismo. Ecografía normal excepto visceromegalia. ¿Qué alteración molecular explica mejor este fenotipo clásico?:', '[{"position": 1, "text": "Pérdida de metilación en IC2 (KCNQ1OT1) paterna."}, {"position": 2, "text": "Ganancia de metilación en IC1 (H19/IGF2) materna."}, {"position": 3, "text": "Mutación pérdida de sentido paterna en CDKN1C."}, {"position": 4, "text": "Deleción de IGF2 en alelo paterno."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-173', '195613487ed68d8f714ec83df48ab1434a543ede', 2026, 0, 173, false, false, NULL, NULL, 'Respecto a los aminoácidos que participan en el ciclo de la urea, señale la opción correcta:', '[{"position": 1, "text": "La citrulina se condensa con glutamato para formar arginino succinato en el citosol."}, {"position": 2, "text": "La ornitina aporta directamente el segundo nitrógeno que se elimina como urea."}, {"position": 3, "text": "La asparagina dona el primer nitrógeno a la carbamoil fosfato sintasa de la mitocondria."}, {"position": 4, "text": "El aspartato aporta el segundo nitrógeno de la urea al condensarse con citrulina para formar arginino succinato."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-174', 'bb37d494a15d15fd87b4e628390a190910e750c9', 2026, 0, 174, false, false, NULL, NULL, 'Lactante varón de 10 meses llevado a urgencias por fiebre y dificultad respiratoria. Presenta otitis medias recurrentes desde los 6 meses y un episodio previo de neumonía bacteriana. La madre refiere que “nunca tuvo amígdalas grandes”. En el hemograma destaca leucocitosis neutrofílica. Inmunoglobulinas IgG, IgA e IgM muy disminuidas. La citometría de flujo muestra linfocitos T dentro de rango de normalidad y linfocitos B CD19+ prácticamente ausentes. ¿Cuál es la alteración genética más probable?:', '[{"position": 1, "text": "Mutación en RAG1."}, {"position": 2, "text": "Deleción 22q11.2."}, {"position": 3, "text": "Mutación en BTK."}, {"position": 4, "text": "Deficiencia de ADA."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-175', '2bb06a6d10b814f93b3dad3750a82862d286cec7', 2026, 0, 175, false, false, NULL, NULL, 'En relación con el síndrome de liberación de citocinas relacionado con la terapia con células CAR-T (linfocitos T modificados para expresar un CAR o chimeric antigen receptor) contra el antígeno CD-19 para el tratamiento de linfomas agresivos, señale la opción verdadera:', '[{"position": 1, "text": "Se considera una complicación tardía que suele presentarse a las 2-3 semanas de recibir el tratamiento."}, {"position": 2, "text": "Se produce por un incremento suprafisiológico de algunas citosinas tales como la interleucina 6 (IL-6) e interleucina 1 (IL-1)."}, {"position": 3, "text": "Las manifestaciones clínicas características incluyen fiebre e hipertensión."}, {"position": 4, "text": "El tozilizumab se utiliza de forma excepcional para su tratamiento."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-176', 'c19bc61e675e93399323f1a9a7da414c264a1e08', 2026, 0, 176, false, false, NULL, NULL, 'Un varón de 11 meses de edad presenta irritabilidad y llanto al movilizar la extremidad inferior derecha. En la exploración física destaca una tumefacción de la rodilla derecha, que se muestra caliente y enrojecida. En el estudio básico de coagulación se observa: tiempo de protrombina (TP) de 11 segundos (rango: 9-15 segundos) y un tiempo de tromboplastina parcial activada (TTPA) de 80 segundos (rango: 20-40 segundos). Se solicita una prueba de mezclas que corrige la alteración de la coagulación. ¿Qué opción diagnóstica NO se ajusta a las alteraciones analíticas observadas?:', '[{"position": 1, "text": "Déficit de factor VII."}, {"position": 2, "text": "Déficit de factor VIII."}, {"position": 3, "text": "Déficit de factor IX."}, {"position": 4, "text": "Enfermedad de von Willebrand tipo 3."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-177', '136e69678c9d0d7b8de6e321740cfa0f867361ac', 2026, 0, 177, false, false, NULL, NULL, 'La exanguinotransfusión es un procedimiento terapéutico que se utiliza de forma característica en el tratamiento de:', '[{"position": 1, "text": "Púrpura trombótica trombocitopénica (PTT) inmunomediada."}, {"position": 2, "text": "Síndrome de Guillain-Barré."}, {"position": 3, "text": "Rechazo humoral agudo en trasplante renal."}, {"position": 4, "text": "Enfermedad hemolítica del recién nacido."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-178', '1657b9c8276a81c444111370dce07b0a89fc567e', 2026, 0, 178, false, false, NULL, NULL, 'Una mujer de 70 años consulta por astenia. Presenta una hemoglobina de 8.1 g/dl, VCM de 72 fl (rango: 84-100 fl) y CHCM de 25 g/dl (rango: 31.5-34.5 g/dl). En el hemograma, tiene una cifra de plaquetas de 530.000/mcrl. En la bioquímica, la LDH, la bilirrubina y la función renal son normales. Revisando sus analíticas previas, años atrás normales, observamos que las alteraciones han ido desarrollándose de forma progresiva en el último año. ¿Cuál es el diagnóstico más probable y qué prueba/s solicitaría para continuar el estudio de esta paciente?:', '[{"position": 1, "text": "Trombocitemia esencial. Estudio de médula ósea."}, {"position": 2, "text": "Betatalasemia intermedia. Electroforesis de hemoglobinas y estudio genético."}, {"position": 3, "text": "Esferocitosis hereditaria. Prueba de unión con esosina-5’-maleimida (EMA)."}, {"position": 4, "text": "Anemia ferropénica. Ferritina sérica y estudios digestivos."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-179', '3b737068485a6e10b1078b79564ab16912a3f87d', 2026, 0, 179, false, false, NULL, NULL, 'Hombre de 60 años con antecedentes personales de fumador de 30 paq/año, hipertensión arterial, dislipemia, hígado graso. Tratamiento con enalapril, simvastatina y 100 mg de ácido acetilsalicílico por ictus hace 5 años. Tiene una artritis psoriásica a tratamiento con metotrexato a dosis de 25 mg/semana a pesar de lo cual presenta mal control de la actividad y precisa cambio de tratamiento. ¿Cuál considera que NO es la mejor opción de tratamiento?:', '[{"position": 1, "text": "Biológico con mecanismo de acción antiTNF (Factor de Necrosis Tumoral)."}, {"position": 2, "text": "Sintético con diana específica inhibidor de JAK."}, {"position": 3, "text": "Biológico con mecanismo de acción antiIL17."}, {"position": 4, "text": "Biológico con mecanismo de acción antiIL12/23."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-180', '5c42530c3545dec47924e36a41e0748a99fcbf5a', 2026, 0, 180, false, false, NULL, NULL, 'Varón de 58 años, sin antecedentes personales ni toma de fármacos que tras un control anual de empresa es diagnosticado de carcinoma renal por lo que se inicia tratamiento con Pembrolizumab (anti PD1). Acude a S de Reumatología por un cuadro de poliartritis, predominantemente rizomiélica, de 2 meses de evolución con marcada elevación de reactantes de fase aguda. El análisis de orina, el hemograma y la bioquímica son normales. El factor reumatoide y los anti péptido cíclico citrulinado son negativos. Los ANA positivos a títulos de 1/80 patrón homogéneo ¿Cuál de los siguientes diagnósticos sería el más probable?:', '[{"position": 1, "text": "Vasculitis secundaria al carcinoma."}, {"position": 2, "text": "Síndrome paraneoplásico."}, {"position": 3, "text": "Enfermedad reumática secundaria al Pembrolizumab."}, {"position": 4, "text": "Lupus eritematoso sistémico."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('mir2026-v0-181', '8a6ca6aedc111861d521511430c05ae0b20d9af0', 2026, 0, 181, false, false, NULL, NULL, 'Paciente de 55 años que acude por cuadro de monoartritis aguda autolimitada de primera metatarsofalángica. Refiere episodios repetidos en los últimos 3 años que trató con analgésicos. Aporta analítica con uricemia de 11 mg/dl. Resto de estudios normales. ¿Cuál sería el tratamiento más indicado para el paciente?:', '[{"position": 1, "text": "Colchicina y antiinflamatorios durante la crisis y luego suspender ambos."}, {"position": 2, "text": "Colchicina y antiinflamatorios y cuando esté asintomático suspender antiinflamatorios y añadir alopurinol."}, {"position": 3, "text": "Alopurinol y antiinflamatorios durante la crisis y después suspender ambos."}, {"position": 4, "text": "Colchicina y antiinflamatorios durante la crisis y después suspender antiinflamatorios y mantener colchicina."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-182', '49e3b58583fcd17fd80849ccd96780a0c3e92e1c', 2026, 0, 182, false, false, NULL, NULL, '¿Cuál de las siguientes afirmaciones sobre los anticuerpos antinucleares es correcta?:', '[{"position": 1, "text": "Los pacientes con lupus inducido por fármacos suelen tener anticuerpos antihistonas y anti-DNA de doble cadena positivos."}, {"position": 2, "text": "Los anticuerpos anti-DNA de cadena única son específicos del lupus eritematoso sistémico."}, {"position": 3, "text": "El título de anticuerpos anti-DNA de doble cadena suele guardar correlación con la actividad de la glomérulo nefritis lúpica."}, {"position": 4, "text": "La positividad de anticuerpos anti-Sm orienta hacia el diagnostico de lupus inducido por fármacos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-183', '0b0eada2e9a80fc719027917f2e2acf1193fbc43', 2026, 0, 183, false, false, NULL, NULL, 'Una mujer de 50 años acude a consulta por dolor lumbar inflamatorio. La exploración denota limitación de la movilidad lumbar y tumefacción global del segundo y tercero dedo de pie derecho y cuarto dedo de pie izquierdo. No tiene lesiones cutáneas. La analítica demuestra elevación de reactantes de fase aguda. El Factor reumatoide (FR) y los anticuerpos contra péptido cíclico citrulinado (ACPA) son negativos. Los anticuerpos antinucleares (ANA) y el HLAB27 también son negativos. Los estudios de imagen de ambos pies evidencian la presencia de erosión junto a neoformación ósea yuxta-articular. ¿Cuál sería su diagnóstico?:', '[{"position": 1, "text": "Artritis reumatoide."}, {"position": 2, "text": "Enfermedad mixta del tejido conectivo."}, {"position": 3, "text": "Sarcoidosis."}, {"position": 4, "text": "Artritis psoriásica."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-184', '114669163868eb968c8d24298d1502336916f4f0', 2026, 0, 184, false, false, NULL, NULL, '¿Cuál de estas afirmaciones es correcta sobre las vasculitis pulmonares?:', '[{"position": 1, "text": "La granulomatosis eosinofílica con poliangitis (GEPA) tiene autoanticuerpos ANCA anti-PR3 elevados en el 80% de los casos."}, {"position": 2, "text": "La enfermedad anti-membrana basal glomerular comienza siempre con afectación pulmonar seguida en ocasiones de una afectación renal leve."}, {"position": 3, "text": "Poliangitis microscópica cursa como una forma de asma grave con escasa participación renal."}, {"position": 4, "text": "La granulomatosis con poliangitis (GPA) afecta frecuentemente a la vía aérea superior."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-185', '5423b629e745dd5cede18bb657b6ea9537cf4c6d', 2026, 0, 185, false, false, NULL, NULL, 'Un paciente de 62 años acude para seguimiento tras un hallazgo incidental de una masa suprarrenal de 2.5 cm identificada en una ecografía realizada por dolor abdominal inespecífico. Está asintomático y sin antecedentes de cáncer. Según las guías actuales, ¿qué técnica de imagen sería la más indicada para caracterizar inicialmente el incidentaloma adrenal?:', '[{"position": 1, "text": "Resonancia magnética con secuencias en fase y fuera de fase."}, {"position": 2, "text": "Tomografía computarizada (TC) sin contraste."}, {"position": 3, "text": "PET-TC con fluorodesoxiglucosa (FDG)."}, {"position": 4, "text": "Tomografía computarizada (TC) con contraste."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-186', 'e48bd9b09252d437f7cb6f9ff0f7d0dbba1bb425', 2026, 0, 186, false, false, NULL, NULL, '¿Cuál de las siguientes afirmaciones es correcta al comparar el tratamiento farmacológico y el tratamiento quirúrgico de la obesidad según las guías clínicas actuales?:', '[{"position": 1, "text": "El tratamiento farmacológico logra una pérdida de peso superior al tratamiento quirúrgico en pacientes con obesidad grave."}, {"position": 2, "text": "La cirugía bariátrica está indicada únicamente en pacientes con obesidad grado I sin comorbilidades."}, {"position": 3, "text": "El tratamiento farmacológico es más eficaz que la cirugía para mejorar la diabetes tipo 2 en pacientes con obesidad."}, {"position": 4, "text": "La cirugía bariátrica logra mayores reducciones de peso y mejoría de comorbilidades que el tratamiento farmacológico en obesidad grave."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-187', 'fe47af1b7731c024edaa88b730003be617c570e5', 2026, 0, 187, false, false, NULL, NULL, 'Paciente de 58 años con diagnóstico de diabetes tipo 2, HbA1c de 8,2 %, IMC de 33 kg/m2, antecedentes de infarto agudo de miocardio y Filtrado glomerular estudiado de 52 ml/min/1.73m², que actualmente recibe tratamiento con metformina. ¿Cuál sería el medicamento más apropiado para añadir a su terapia?:', '[{"position": 1, "text": "Insulina basal."}, {"position": 2, "text": "Pioglitazona."}, {"position": 3, "text": "Inhibidor de DPP-4 (sitagliptina)."}, {"position": 4, "text": "Inhibidor de SGLT2 (empaglifozina)."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-188', '035e8cd4d36530ea4edd31c018ae7dfc50912da8', 2026, 0, 188, false, false, NULL, NULL, '¿Cuál es el rango de glucosa definido como Tiempo en Rango (TIR) durante el embarazo según el perfil glucémico ambulatorio (AGP)?:', '[{"position": 1, "text": "70-180 mg/dL."}, {"position": 2, "text": "70-140 mg/dL."}, {"position": 3, "text": "63-140 mg/dL."}, {"position": 4, "text": "60-130 mg/dL."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-189', '163defebb160ef983510b908932558b15a5314c4', 2026, 0, 189, false, false, NULL, NULL, 'Un hombre de 35 años con diabetes mellitus tipo 1 (DM1) acude a su consulta. Refiere que, por su cuenta, ha solicitado una analítica a su hijo de 8 años, completamente asintomático. El resultado muestra anticuerpos anti-GAD y anti-tirosina fosfatasa (anti-IA2) positivos, con una glucemia basal de 88 mg/dL y una HbA1c de 5.2%. El padre, muy preocupado, le pregunta qué actitud se debe tomar a continuación. Según las recomendaciones actuales, ¿cuál sería la conducta más apropiada?:', '[{"position": 1, "text": "Tranquilizar a la familia, ya que al estar el niño asintomático y con glucemias normales, solo requiere una vigilancia pasiva."}, {"position": 2, "text": "Iniciar tratamiento con metformina para intentar preservar la función de la célula beta."}, {"position": 3, "text": "Clasificar al niño como estadio 1 de DM1 y derivarlo a una unidad de endocrinología pediátrica para seguimiento y posible inclusión en ensayos clínicos de prevención."}, {"position": 4, "text": "Repetir la determinación de glucosa cada año, ya que el desarrollo de la enfermedad es improbable antes de la pubertad."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-190', '616134af4cd6fb86134fcfd347ce4b12d4a49aef', 2026, 0, 190, false, false, NULL, NULL, '¿Cuál de estas patologías NO es causa de hipopotasemia?:', '[{"position": 1, "text": "Hipomagnesemia."}, {"position": 2, "text": "Hipoaldosteronismo."}, {"position": 3, "text": "Vómitos."}, {"position": 4, "text": "Síndrome de Bartter."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-191', 'ea661a44870aef484dc3c72b0dc84fc706dec907', 2026, 0, 191, false, false, NULL, NULL, 'La enfermedad que más frecuentemente conduce a los programas de diálisis y trasplante en España es:', '[{"position": 1, "text": "Pielonefritis crónica."}, {"position": 2, "text": "Nefroesclerosis."}, {"position": 3, "text": "Poliquistosis hepato-renal."}, {"position": 4, "text": "Enfermedad renal diabética."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-192', '85f374fafe45e2dce2ddd238b87caecb1e32293f', 2026, 0, 192, false, false, NULL, NULL, '¿Cuál es el mejor marcador bioquímico de función renal en la práctica clínica habitual?:', '[{"position": 1, "text": "La Urea plasmática."}, {"position": 2, "text": "La Creatinina plasmática."}, {"position": 3, "text": "El Potasio sérico."}, {"position": 4, "text": "El filtrado glomerular estimado."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-193', 'f151c0593bfa0ef3bcbcb73d708cc34a9b48f7c0', 2026, 0, 193, false, false, NULL, NULL, 'Son características de la preclampsia:', '[{"position": 1, "text": "Hipertensión arterial, microhematuria y edemas en la última parte del embarazo."}, {"position": 2, "text": "Hipertensión arterial, microhematuria y edemas en el primer trimestre del embarazo."}, {"position": 3, "text": "Hipertensión arterial, proteinuria y edemas en la segunda mitad del embarazo."}, {"position": 4, "text": "Hipertensión arterial, proteinuria y edemas en el primer trimestre del embarazo."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-194', 'febeb32a50563e1213013484a2363866a2e843a8', 2026, 0, 194, false, false, NULL, NULL, 'Un paciente de 62 años con diabetes mellitus tipo 2, en tratamiento con metformina, enalapril a dosis máximas toleradas y 10 mg diarios de empagliflozina, mantiene un buen control tensional (130/78 mmHg) y una HbA1c de 6.3 %. A pesar de ello, persiste una albuminuria con un cociente albúmina/creatinina de 160 mg/g. Su tasa de filtrado glomerular es de 65 ml/min/1.73m² y su potasio sérico es de 4.4 mEq/L. ¿Cuál sería la siguiente medida terapéutica más adecuada para reducir la progresión de su enfermedad renal diabética?:', '[{"position": 1, "text": "Sustituir el enalapril por un antagonista de los receptores de angiotensina II (ARA II)."}, {"position": 2, "text": "Añadir un agonista del receptor de GLP-1."}, {"position": 3, "text": "Añadir finerenona (antagonista no esteroideo del receptor mineralcorticoide)."}, {"position": 4, "text": "Aumentar la dosis de empaglifocina."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-195', '8d19c3b624e4e8f644fc4ac06fdbf9822a42f212', 2026, 0, 195, false, false, NULL, NULL, 'La policía encuentra en la calle, inconsciente e inmóvil, a altas horas de la madrugada a un indigente que presente múltiples hematomas y fetor etílico. En el hospital se detecta urea de 200 mg/dl, creatinina de 6 mg/dl, ácido úrico de 10 mg/dl y CPK de 9000 U/L. El diagnóstico probable es:', '[{"position": 1, "text": "Necrosis tubular aguda alcohólica."}, {"position": 2, "text": "Fracaso renal agudo por urato."}, {"position": 3, "text": "Fracaso renal agudo prerrenal por deshidratación."}, {"position": 4, "text": "Fracaso renal agudo por rabdomiolisis."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-196', '803ee441d89496c720326dfa4aa58d7c02340f61', 2026, 0, 196, false, false, NULL, NULL, 'Paciente de 23 años, que es llevado a un servicio de urgencias hospitalario por haber sido encontrado en calle con bajo nivel de conciencia. A su llegada el paciente responde a estímulos dolorosos intensos, tiene una frecuencia cardiaca de 40 latidos por minuto, unas cifras de presión arterial de 90/60 mmHg, sin fiebre y unas pupilas puntiformes. Ante la sospecha de una intoxicación, ¿cuál de los siguientes antídotos estaría más indicado?:', '[{"position": 1, "text": "Naloxona."}, {"position": 2, "text": "Flumazenilo."}, {"position": 3, "text": "Atropina."}, {"position": 4, "text": "Pralidoxima."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-197', 'e1017fea4d9d1ebd63455f32e0ceb241899f1244', 2026, 0, 197, false, false, NULL, NULL, 'Paciente de 88 años con antecedentes de Hipertensión Arterial, Diabetes Mellitus y Cardiopatía Isquémica Crónica que acude a urgencias por disnea de aparición súbita, con ortopnea, disnea paroxística nocturna y edemas en miembros inferiores hasta raíz de muslo. En el triage de urgencias tiene unas cifras de presión arterial de 190/70, una frecuencia cardiaca de 123 latidos por minuto y una saturación capilar de oxígeno del 89%. ¿Cuál de las siguientes medidas terapéuticas NO está indicada de inicio en el manejo de este paciente?:', '[{"position": 1, "text": "Oxigenoterapia."}, {"position": 2, "text": "Nitroglicerina intravenosa."}, {"position": 3, "text": "Morfina intravenosa."}, {"position": 4, "text": "Diuréticos intravenosos."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-198', '741fd6700deb1f3893918f9f9ed3ece1ebb2bacf', 2026, 0, 198, false, false, NULL, NULL, 'Paciente de 18 años, politraumatizado grave tras caída de un patinete. En el manejo inicial, dentro de la evaluación primaria y soporte vital ¿Cuál es la primera acción que debemos realizar?:', '[{"position": 1, "text": "Cohibir la hemorragia externa, exanguinante o masiva."}, {"position": 2, "text": "Asegurar la permeabilidad de la vía aérea."}, {"position": 3, "text": "Asegurar una correcta ventilación/oxigenación."}, {"position": 4, "text": "Identificar y tratar el shock."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-199', '7acaace482c9f4dcaed15d31e27ac4a7f9c9b7aa', 2026, 0, 199, false, false, NULL, NULL, 'Paciente de 76 años, sin comorbilidad conocida que sufre una caída causal desde una escalera sufriendo un traumatismo craneal y cervical. Atendido inicialmente por un familiar, que le coloca en posición lateral de seguridad mientras espera la llegada de las asistencias sanitarias. A la llegada del personal del SAMU el paciente se encuentra inconsciente. ¿Cuál de las siguientes afirmaciones es FALSA sobre el manejo de la vía aérea?:', '[{"position": 1, "text": "La apertura de la vía aérea mediante tracción mandibular es la maniobra de elección."}, {"position": 2, "text": "Lo prioritario es colocar un collarín cervical rígido."}, {"position": 3, "text": "La apertura de la vía aérea es prioritaria en un paciente con un traumatismo."}, {"position": 4, "text": "Una vez abierta la vía aérea, es recomendable usar un dispositivo orofaríngeo."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-200', '4cf85a8ce669491d0cbac649ec122a020c48ef27', 2026, 0, 200, false, false, NULL, NULL, 'En relación con la violencia de género, señale la afirmación correcta:', '[{"position": 1, "text": "Se produce con mayor frecuencia en familias desestructuradas y con pocos recursos económicos."}, {"position": 2, "text": "Los agresores presentan con frecuencia trastornos psiquiátricos graves que explican la conducta violenta."}, {"position": 3, "text": "Las víctimas rara vez acuden a los servicios sanitarios por miedo a ser identificadas como víctimas."}, {"position": 4, "text": "El embarazo es un periodo de riesgo para el inicio o agravamiento de la violencia de género."}]'::jsonb, 4, 4, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-201', '86e51b21fd7226e20f94e2dba6ecac8ed2aef8ab', 2026, 0, 201, true, false, NULL, NULL, '¿Cuál de las siguientes opciones es el tratamiento de primera línea más eficaz para aliviar la congestión nasal y los síntomas oculares establecidos en la rinitis alérgica persistente y moderada?:', '[{"position": 1, "text": "Antihistamínicos orales de primera generación, como la difenhidramina, debido a su efecto rápido."}, {"position": 2, "text": "Descongestionantes nasales tópicos usados prolongadamente para un control sostenido de la congestión."}, {"position": 3, "text": "Corticosteroides intranasales de alta potencia, para aliviar síntomas nasales y oculares con menos efectos sistémicos."}, {"position": 4, "text": "Cromoglicato sódico por vía oral como único tratamiento en síntomas moderados persistentes."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-202', 'd0e3bf5344e83da597076250ccc222990854655e', 2026, 0, 202, true, false, NULL, NULL, 'Respecto a la Trombosis Venosa Profunda, señale lo correcto:', '[{"position": 1, "text": "Tras la sospecha clínica, el diagnóstico suele realizarse mediante ecografía doppler."}, {"position": 2, "text": "Los pacientes con factores de riesgo o trombosis venosas de repetición suelen precisar anticoagulación durante 12 meses."}, {"position": 3, "text": "Por norma general, la anticoagulación se suele mantener durante 3 semanas."}, {"position": 4, "text": "La tasa de recidiva es del 60%."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-203', 'daad30b787f041047f8f3dd645cceb1dbec34975', 2026, 0, 203, true, false, NULL, NULL, '¿Cuál de los siguientes microorganismos no es habitual en las infecciones del tracto urinario?:', '[{"position": 1, "text": "Clostridium perfringens."}, {"position": 2, "text": "Klebsiella pneumoniae."}, {"position": 3, "text": "Pseudomonas aeruginosa."}, {"position": 4, "text": "Staphylococcus saprophyticus."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-204', '319346e4a39e889e343dcb08d101318b2e66c6c8', 2026, 0, 204, true, false, NULL, NULL, '¿Qué hallazgo clínico es más característico de una ParsPlanitis?:', '[{"position": 1, "text": "Acumulo de material inflamatorio en el vitreo (vitritis)."}, {"position": 2, "text": "Periflebitis periférica."}, {"position": 3, "text": "Aparición de bancos o copos de nieve en la base del vítreo."}, {"position": 4, "text": "Edema de papila."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-205', '98721223da6eb1eac5dcfcc16cee68369be5ea89', 2026, 0, 205, true, false, NULL, NULL, 'La participación activa en Atención Primaria es un concepto clave dentro del modelo de salud comunitaria y centrada en la persona. Se refiere a la implicación real y continua de los pacientes, sus familias y la comunidad en las decisiones y acciones relacionadas con su salud, tanto a nivel individual como colectivo. ¿Cuál de las siguientes afirmaciones, refleja mejor el concepto de participación activa en la Atención Primaria?:', '[{"position": 1, "text": "Los profesionales de salud deben responder a las demandas explícitas de los pacientes cuando éstos acuden a consulta."}, {"position": 2, "text": "Los equipos de atención primaria deben ser proactivos, abordando tanto las necesidades expresadas por los pacientes como aquellas que no han sido verbalizadas."}, {"position": 3, "text": "Los pacientes son responsables de expresar todas sus necesidades para que el equipo de atención primaria pueda ofrecer la atención adecuada."}, {"position": 4, "text": "La participación activa se refiere exclusivamente a la implicación de la comunidad en las decisiones sobre políticas de salud."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-206', '11f7f616dfc0f731bdf8603bb69620204fcd10a7', 2026, 0, 206, true, false, NULL, NULL, 'Un hombre de 62 años es diagnosticado de adenocarcinoma de recto medio, confirmado por biopsia endoscópica. La tomografía computarizada toracoabdominopélvica no muestra metástasis a distancia. ¿Qué prueba de imagen es más adecuada para identificar la mejor opción terapéutica local en este paciente?:', '[{"position": 1, "text": "Tomografía computerizada de abdomen y pelvis con contraste intravenoso y angiografía (angio TAC)."}, {"position": 2, "text": "Tomografía por emisión de positrones de pelvis combinada con Tomografía computerizada (PET/TC)."}, {"position": 3, "text": "Resonancia magnética pélvica (RMN) con secuencias de alta resolución del mesorrecto, con o sin contraste."}, {"position": 4, "text": "Ecografía combinada abdomino-pélvica y endorrectal."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-207', '41e62a70215781b60c26cdfb774e7f445750e094', 2026, 0, 207, true, false, NULL, NULL, 'Una paciente de 87 años acude a la consulta de su médico de Atención Primaria en el contexto de una evaluación geriátrica. Al cuantificar el SPPB (Short Physical Performance Battery o Prueba corta de desempeño físico) observamos que en el test de equilibrio aguanta más de 10 segundos en cada una de las tres pruebas (con los pies juntos, en semitándem y tándem). Además, al medir la velocidad de la marcha tarda menos de 4,82 segundos en recorrer 4 metros y en el test de levantarse de la silla 5 veces tarda menos de 11,2 segundos. Calcule su resultado en el SPPB:', '[{"position": 1, "text": "12 puntos."}, {"position": 2, "text": "10 puntos."}, {"position": 3, "text": "8 puntos."}, {"position": 4, "text": "6 puntos."}]'::jsonb, 4, 1, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-208', '1a1cb34859da0553d8b6d7dc4f5a019e08508135', 2026, 0, 208, true, false, NULL, NULL, 'Mujer de 67 años diagnosticada de cirrosis hepática, con antecedentes de descompensaciones ascíticas en tratamiento con espironolactona y furosemida. Su familia la trae a urgencias por alteración del nivel de conciencia. La paciente se encuentra ligeramente desorientada en tiempo y espacio y somnolienta. Tiene asterixis franca. ¿Cuál de las siguientes medidas NO se encuentra indicada a su ingreso?:', '[{"position": 1, "text": "Paracentesis diagnóstica."}, {"position": 2, "text": "Medición de los niveles plasmáticos de amoniaco."}, {"position": 3, "text": "Administración de lactulosa por vía oral."}, {"position": 4, "text": "Antibioterapia de amplio espectro."}]'::jsonb, 4, NULL, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-209', '09af1100fa1dd40145ad27cbfae1702fe00bbe89', 2026, 0, 209, true, false, NULL, NULL, 'En el abordaje terapéutico de un paciente adulto con lesión medular y presencia de espasticidad generalizada en la exploración, ¿cuál de estos fármacos NO utilizaría como tratamiento?:', '[{"position": 1, "text": "Diazepam."}, {"position": 2, "text": "Lacosamida."}, {"position": 3, "text": "Tizanidina."}, {"position": 4, "text": "Baclofeno."}]'::jsonb, 4, 2, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('mir2026-v0-210', 'd5cfd51bb0a89176c6ffef3cd2b824b9a6421e71', 2026, 0, 210, true, false, NULL, NULL, 'En relación con el pseudotumor cerebri o hipertensión intracraneal idiopática (HII), ¿cuál de las siguientes afirmaciones es correcta?:', '[{"position": 1, "text": "Es más frecuente en hombres ancianos con índice de masa corporal (IMC) bajo."}, {"position": 2, "text": "Se caracteriza por aumento de la presión de apertura del LCR con composición anormal."}, {"position": 3, "text": "Afecta preferentemente a mujeres jóvenes obesas y puede causar pérdida visual."}, {"position": 4, "text": "El tratamiento inicial consiste en corticoides a dosis altas y restricción hídrica estricta."}]'::jsonb, 4, 3, 'definitiva', NULL, false, NULL, false, NULL, 'foundation29org/MIR_AI_F29 (MIT)', 'https://github.com/foundation29org/MIR_AI_F29'),
('casimedicos-c2c6b9f68df7', '062b413e0655a7deb2abefdf0de26b9fbc34f521', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 27 años en estudio en el Servicio de dermatología por presentar episodios de aftas bucales recidivantes. Es remitida a las consultas de Aparato Digestivo por objetivar en una analítica Hb 11,5 gr/dl Fe 38 AST 52 ALT 64 Ac antitrasglutaminasa IgA 177. La paciente sólo refiere presentar molestias abdominales difusas de forma ocasional. No refiere signos de hemorragia ni ictericia.. La exploración física es normal.', '¿Qué prueba de las que se mencionan a continuación considera que es la más adecuada para realizar el diagnóstico?', '[{"position": 1, "text": "Cápsula endoscópica."}, {"position": 2, "text": "Colonoscopia."}, {"position": 3, "text": "Serología para virus de la hepatitis b y c."}, {"position": 4, "text": "Biopsia intestinal."}, {"position": 5, "text": "Ecografía abdominal."}]'::jsonb, 5, 4, 'definitiva', 'En esta pregunta, dan un dato importante a la hora de sospechar un diagnóstico que son los Ac. Antitrasglutaminasa que tienen que llevarte a sospechar enf. Celiaca. El resto de síntomas entran perfectamente dentro del cuadro y aunque probablemente se hagan varias de las pruebas que pone, la respuesta que nos dará el diagnóstico es la 4 (biopsia intestinal).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7662778a63d8', '218e8b7b8b1eafb358a1086e364fc00c62df8d08', NULL, NULL, NULL, false, false, 'Endocrinología', 'Hombre de 24 años que refiere astenia progresiva desde al menos 6 meses, voz ronca, lentitud del habla, somnolencia e hinchazón de manos, pies y cara. Exploración: pulso a 52 latidos por minutos, cara abotargada y piel seca y pálida. Analítica: Ligera anemia, colesterol 385 mg/dL (normal <220), creatinina 1,3 mg/dL (normal: 0,5-1,1), proteinuria negativa, TSH 187μUI/mL (normal 0,35-5,5) y T4 Libre 0,2 ng/dL (normal 0,85-1,86).', '¿Qué estrategia le parece más adecuada?', '[{"position": 1, "text": "Realizar una ecografía tiroidea antes de iniciar el tratamiento."}, {"position": 2, "text": "Determinar la T3 libre y realizar una resonancia magnética hipofisaria."}, {"position": 3, "text": "Tratar con L-Triyodotironina y una estatina."}, {"position": 4, "text": "Tratar con L-Tiroxina y determinar anticuerpos antitiroideos."}, {"position": 5, "text": "Realizar una citología tiroidea, previa al tratamiento."}]'::jsonb, 5, 4, 'definitiva', 'Se trata de un hipotiroidismo primario severo. El tratamiento se realiza con tiroxina. Si no hay nódulo no está indicado ni eco ni PAAF.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4f12883fa83d', 'db3765af7da1b226f3d7a7151cf99d6d0a10b297', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una mujer de 55 años consulta por fatiga y poliuria de dos años de evolución. Los análisis revelan hipercalcemia, aumento de la PTH e incremento de los marcadores de recambio óseo. El estudio radiográfico muestra resorción subperióstica y osteoporosis. La gammagrafía con sestamibi pone de manifiesto un adenoma paratiroideo. Se efectúa paratiroidectomía con cirugía mínimamente invasiva. En el postoperatorio la enferma desarrolla hipocalcemia intensa y tetania, siendo la PTH inferior a 5 ng/l. La enferma responde bien al tratamiento inicial con calcio intravenoso y posteriormente con calcio y vitamina D orales.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Hipoparatiroidismo quirúrgico permanente."}, {"position": 2, "text": "Transfusión de sangre citratada."}, {"position": 3, "text": "Insuficiencia de vitamina D."}, {"position": 4, "text": "Síndrome del hueso hambriento."}, {"position": 5, "text": "Osteomalacia."}]'::jsonb, 5, 4, 'definitiva', 'Pregunta de dificultad muy alta, yo no me preocuparía por haberla fallado. Es fácil confundirse con la respuesta de hipoparatiroidismo. Es raro un hipoparatiroidismo postquirúrgico permanente tras una paratiroidectomia de un adenoma con cirugía mínimamente invasiva. Recordad además que para que sea permanente debe durar permanencer 6 meses tras la intervención.Os escribo un breve resumen del síndrome de hueso ambriento que he encontrado en un caso clínico de los anales de medicina interna [1]: "La fisiopatología del síndrome del hueso hambriento (SHH) está relacionada con un disbalance entre la formación y resorción ósea, que se asocia a hipocalcemia, hipofosfatemia e hipomagnesemia (1). Este síndrome se puede observar tras la cirugía de pacientes con hiperparatiroidismo (HPT) primario, así como en el HPT terciario de la insuficiencia renal crónica, y en menor medida tras tratamiento de procesos que cursan con exceso de hormonas tiroideas circulantes (2). En el HPT, existe un exceso de hormona paratiroidea (PTH) que estimula la actividad osteoclástica causando desmineralización de la matriz ósea y liberando calcio al torrente sanguíneo. Tras paratiroidectomia, los niveles séricos de PTH caen dramáticamente, por ello, la resorción ósea inducida por la PTH cesa, mientras que la actividad osteoblástica continúa dando como resultado un incremento en la captación ósea de calcio, fosfato y magnesio, apareciendo así el SHH (3)."', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f0ef3995d889', '22d60bd7922a13bdc0cf4b9cb9ee7884bc6020d8', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Un hombre presenta una deleción parcial en el gen de la distrofina (cromosoma Xp21) que le ocasiona la semiología propia de la distrofia muscular de Becker. Acude a la consulta de genética con su esposa, para valorar los riesgos de transmisión de la enfermedad.', '¿Qué información correcta será proporcionada en el transcurso del consejo genético?', '[{"position": 1, "text": "Según la herencia autosómica dominante, al mitad de sus hijos heredarán la enfermedad y sin distinción de sexos."}, {"position": 2, "text": "Sus hijas no heredarán la enfermedad, pero todos sus futuros hijos varones serán portadores y pueden transmitir la mutación al 50%."}, {"position": 3, "text": "Sus hijos varones no heredarán la enfermedad, pero todas sus futuras hijas serán portadoras y pueden transmitir la mutación al 50%."}, {"position": 4, "text": "No hay riesgo: la herencia de la enfermedad es del tipo mitocondrial, nunca transmitida por los varones."}, {"position": 5, "text": "Según la herencia autosómica recesiva, un 25% de sus hijos manifestarán la enfermedad en la infancia, sin distinción de sexos."}]'::jsonb, 5, 3, 'definitiva', 'Es el hombre quien presenta la enfermedad, que nos dicen que está ligada al cromosoma X, por lo que sólo quedan dos opciones: 2 y 3. La 2 no es porque los varones recibirán el cromosoma Y del padre y el X de la madre, que está sana, por lo que las hijas podrán portar la enfermedad (Opción correcta la 3).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5b383276e4e7', 'aa4a3ed380c19bac1f813448673c7bf1ce07a21b', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Una mujer de 32 años asintomática consulta para una revisión en salud ginecológica porque desea quedarse embarazada. En dicha revisión se le detecta un mioma uterino de 4cm en parte intramural y en parte subseroso situado en la cara anterior del útero y que no deforma la cavidad endometrial.', '¿Qué actitud recomendaría?', '[{"position": 1, "text": "Miomectomía por vía laparoscópica."}, {"position": 2, "text": "Miomectomía por vía laparotómica."}, {"position": 3, "text": "Embolización del mioma por cateterismo arterial."}, {"position": 4, "text": "Tratamiento con análogos de Gn-Rh durante tres meses antes de intentar el embarazo."}, {"position": 5, "text": "Intentar el embarazo sin ningún tratamiento previo."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es la 5. Un mioma asintomático de este tamaño que no deforma la cavidad endometrial no molesta de cara a un embarazo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-362d42a1fc95', 'e5376dba72a1ee402cc7a03dbe2550716cc9dcb6', NULL, NULL, NULL, false, false, 'Cirugía General', 'Una mujer de 76 años sin otros antecedentes que hipertensión arterial consulta por ictericia indolora y prurito con anorexia. Analíticamente destaca una bilirrubina de 12 mg/dl (con 9,5 de bilirrubina directa). La ecografía abdominal muestra dilatación de la vía biliar intra y extrahepática, junto con un nódulo único de 2 cm localizado periféricamente en la cara anterior del lóbulo izquierdo. La Tc confirma lo hallazgos, demostrando además la presencia de una masa en la cabeza del páncreas de 3,5 cm. La punción aspiración con aguja fina confirma el diagnóstico de adenocarcinoma.', 'Señale la mejor opción terapéutica:', '[{"position": 1, "text": "Quimio/radioterapia adyuvante, condicionando la cirugía radical a la respuesta inicial."}, {"position": 2, "text": "Drenaje externo percutáneo don carácter paliativo, con eventual conversión a drenaje interno en caso de intolerancia o complicaciones."}, {"position": 3, "text": "Derivación biliar quirúrgica, con o sin gastroyeyunostomía profiláctica en función de los hallazgos intraoperatorios."}, {"position": 4, "text": "Prótesis biliar metálica mediante colangiografía endoscópica retrógrada, con opción a quimioterapia paliativa."}, {"position": 5, "text": "Duodenopancreatectomía cefálica con ablación por radiofrecuencia o alcoholización de la lesión hepática."}]'::jsonb, 5, 4, 'definitiva', 'Creo que la respuesta correcta es la 4, aunque las dos lesiones son resecables el adenocarcinoma de páncreas con metástasis hepática sincrónicas no tiene indicación quirúrgica debido a que no prolonga la supervivencia y tiene una morbilidad elevada. La derivación quirúrgica tienen más complicaciones que colocar una prótesis metálica autoexpandible que tiene una permeabilidad media de 6 meses que es similar a la supervivencia mediana de un paciente con metástasis hepáticas de adenocarcinoma de páncreas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0bf6164aec0f', '71b776a40421e4c63306437e6f6a29fa01e7a290', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Paciente de 76 años, paridad 3-0-3-1, con menopausia a los 52 años. Relata que desde hace almenos 4-5 años presenta prurito vulvar de intensidad variable que ha sido tratado algunes veces con automedicación y otras por indicación de su medico generalista con Preparados tópicos (cremas y lavados). El prurito ha evolucionado así con intermitencias pero desde hace 3-4 meses nota además una pequeña tumoración en el labio mayor iquierdo de la vulva y de la que se producen pérdidas serohemáticas al roce desde hace algunos días; por ello consulta al ginecólogo. Al interrogatorio refiere disúria ocasional y el estado general es bueno.', '¿Cuál es el diagnóstico más probable en esta paciente?', '[{"position": 1, "text": "Herpes genital."}, {"position": 2, "text": "Enfermedad de Paget de la vulva."}, {"position": 3, "text": "Carúncula uretral."}, {"position": 4, "text": "Granuloma crónico de la vulva."}, {"position": 5, "text": "Carcinoma vulvar escamoso."}]'::jsonb, 5, 5, 'definitiva', 'La respuesta correcta es la 5. El carcinoma vulvar se caracteriza por prurito vulvar crónico resistente a múltiples tratamientos, aparición de tumoración o ulceración, disuria y tenesmo vesical, y tardíamente dolor y hemorragia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3879d735f33c', 'fae511f76115a3805704759688b659738ab8cbd0', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Ante una mujer de 59 años que consulta por secreción hemática por el pezón derecho (unilateral), espontánea y uniorificial sin nodularidad palpable.', '¿Cuál es el diagnostico más probable?', '[{"position": 1, "text": "Dado el carácter hemático de la secreción el diagnóstico más probable es el de carcinoma ductal infiltrante."}, {"position": 2, "text": "Papiloma intraductal."}, {"position": 3, "text": "Enfermedad de Paget del pezón."}, {"position": 4, "text": "Hiperprolactinemia tumoral."}, {"position": 5, "text": "La mamografía nos indicará el diagnóstico."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es la 2. Ante una telorrea hemática unilateral y uniorificial, la causa más frecuente es el papiloma intraductal (50%), seguida de la ectasia ductal y del carcinoma. Cuando se asocia a masa palpable, el 60% corresponden a un carcinoma. La enfermedad de Paget es de tipo eccematoso. En hiperprolactinemia la telorrea es bilateral y pluriorificial. La mamografía a menudo no muestra los papilomas, siendo más útiles la ecografia y la galactografía.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-385df6b6ba60', '008c609cc3c18a44594cda99b3e4e4cf74f91c49', NULL, NULL, NULL, false, false, 'Hematología', 'Mujer de 35 años sana que consulta por astenia. En el hemograma presenta anemia microcítica e hipocroma (hemoglobina de 7 gr/dl, volumen corpuscular medio de 68 fl, hemoglobina corpuscular media de 24 pg) con una amplitud de distribucion eritrocitaria elevada (ADE 20%), reticulocitos disminuidos (0.3%, 30000/l absolutos), contenido de hemoglobina disminuido en los reticulocitos (17 pg) y discreta trombocitosis (500000 plaquetas).', 'Con los datos del hemograma, ¿cuál sería su sospecha diagnóstica aún sin tener la bioquímica del paciente?', '[{"position": 1, "text": "Rasgo talasémico."}, {"position": 2, "text": "Anemia central, arregenerativa, por déficit de ácido fólico."}, {"position": 3, "text": "Anemia periférica, regenerativa, hemolítica."}, {"position": 4, "text": "Anemia periférica, regenerativa, por hemorragia activa aguda."}, {"position": 5, "text": "Anemia central, arregenerativa, por déficit de hierro."}]'::jsonb, 5, 5, 'definitiva', 'Con los datos que nos dan, lo primero que nos viene a la cabeza es que se trata de una anemia arregenerativa, ya que la médula ósea no ha respondido con una exaltación de la eritropoyesis; de ese modo eliminamos ya las opciones que nos hablan de anemia regenerativa. Lo siguiente que nos orienta hacia la causa es que es microcítica e hipocroma, lo cual es característico de la anemia por déficit de hierro, ya que el déficit de fólico da lugar a una anemia megaloblástica y la hemorragia activa no da microcitosis ni hipocromía, sino normocitosis y normocromía. Ya casi-casi nos inclinamos por la respuesta 5, anemia central arregenerativa por déficit de hierro…pero queda ahí la respuesta 1, «rasgo talasémico», que nos incomoda y hace dudar si no estaremos yendo a lo aparentemente fácil…hasta que recordamos que en la talasemia la ADE es normal. Definitivamente, esta chica en edad fértil tiene una anemia por déficit de hierro, algo bastante común. Quien tenga dudas puede consultar «Hematología. Manual básico razonado» de Jesús San Miguel.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-32f18f31459f', '12c1086628c41965753ad65dd4fa1b2f6ddd3515', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'A un joven asintotomático de 14 años cuyo padre acaba de ser diagnostica de TBC pulmonar se le realiza un Mantoux, con resultado negativo.', '¿Qué actitud es la adecuada?', '[{"position": 1, "text": "Tranquilizarle, ya que no tiene ningún riesgo."}, {"position": 2, "text": "Realizarle una radiografía de tórax."}, {"position": 3, "text": "Iniciar quimioprofilaxis y repetir la prueba cutánea a los 3 meses."}, {"position": 4, "text": "Repetir la prueba cutánea al mes."}, {"position": 5, "text": "Habría que realizar el estudio de esputo antes de iniciar quimioprofilaxis con Isoniazida durante 1 año."}]'::jsonb, 5, 3, 'definitiva', 'En los jóvenes que sean contactos, se iniciará quimioprofilaxis aunque el mantoux sea negativo y se repetirá a los 2-3 meses para decidir si se sigue tratando hasta completar 6 meses (si vira a positivo) o puede dejarla.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-13f3b6dfd482', '48d3d5c71a12208f55a1efd80f1d9df88440f3d8', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 17 años que acude a urgencias por un cuadro de fiebre elevada, dolor faríngeo y adenopatías cervicales. Previamente había sido diagnosticada de faringitis aguda y recibió tratamiento con amoxicilina, presentado posteriormente un exantema cutáneo maculoso generalizado. Se realiza analítica que presenta ligera leucocitosis con linfocitosis y presencia de linfocitos activados, ligera trombopenia y transaminasas levemente aumentadas.', '¿Cuál sería el diagnóstico más probable de este cuadro clínico?', '[{"position": 1, "text": "Es un cuadro típico de mononucleosis infecciosa."}, {"position": 2, "text": "Infección por virus varicela zóster."}, {"position": 3, "text": "Toxoplasmosis aguda."}, {"position": 4, "text": "Enfermedad de Lyme."}, {"position": 5, "text": "Infección por virus herpes 8."}]'::jsonb, 5, 1, 'definitiva', 'Desde luego sí que es un cuadro típico (VEB, CMV, VH6, Toxoplasma), de los que luego no veréis tan claramente en la puerta de urgencias cuando estéis de guardia. Ojo con la mala leche de la respuesta 3, pues una toxoplasmosis aguda puede comportarse así y además da un exantema macular, aunque el de esta chica es en relación con la toma de amoxicilina. Por cierto, añado un apunte, si en vez de una chica de 17 años tan clara fuera un/una joven con relaciones sexuales de riesgo, no olvidéis la primoinfección por VIH como causa de síndrome mononucleósico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-709e34d754b6', '723a6c2e30937559ac45e5037c3babad7eb56f93', NULL, NULL, NULL, false, false, 'Cirugía General', 'Diez días después de practicarle una hemitiroidectomía a un paciente con un nódulo tiroideo de 1,5 cm recibe el siguiente informe anatomopatológico: “patrón folicular muy celular sin invasión capsular y que infiltra vasos sanguíneos y nervios adyacentes”.', 'Señale la respuesta correcta:', '[{"position": 1, "text": "Como no existe invasión capsular no es necesaria más cirugía."}, {"position": 2, "text": "El patrón folicular es indicación de vaciamiento ganglionar cervical profiláctico."}, {"position": 3, "text": "Se trata de un carcinoma folicular y requiere completar la tiroidectomía."}, {"position": 4, "text": "El informe permite descartar con total seguridad un carcinoma papilar en el tiroides remanente."}, {"position": 5, "text": "La medición de calcitonina plasmática permitirá distinguir entre carcinoma papilar y folicular."}]'::jsonb, 5, 3, 'definitiva', 'Creo que la respuesta correcta es la 3 las respuestas 2,4 y 5 son claramente falsas. La duda se produce entre la 1 y la 2. El enunciado de la 1 es correcto en casos de carcinoma folicular sin invasión capsular puede en realizarse una tiroidectomía total. Pero si existen datos de mal pronóstico y la posibilidad de metástasis- como en este caso- lo mejor es completar la tiroidectomía y realizar un rastreo con Iodo radioactivo para descartar metástasis o tratarlas si están presentes.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1432f87c17bf', 'a5332b529cf9f640403f17af4f67f1bbc1395275', NULL, NULL, NULL, false, false, 'Medicina Preventiva y Epidemiología', 'Médico traumatólogo de 40 años que en una serología rutinaria se le detecta niveles de antiHBs de 30 UI/l. Refiere vacunación completa según pauta estándar frente a hepatitis B hace 4 años.', 'Sería recomendable:', '[{"position": 1, "text": "Reiniciar pauta vacunal (0-1-6 meses)."}, {"position": 2, "text": "Reiniciar pauta vacunal (0-1-2-12 meses)."}, {"position": 3, "text": "No revacunar."}, {"position": 4, "text": "Darle una dosis de recuerdo o booster."}, {"position": 5, "text": "Darle inmunoglobulina anti-hepatitis B y reiniciar pauta vacunal (0-1-2-12 meses)."}]'::jsonb, 5, 3, 'definitiva', 'Mientras los niveles serológicos de antiHBs estén por encima de 10 UI/l no es necesario revacunar.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f2cd816f1269', '84f3eea9ff6602165639237a36d4a6e96745f24c', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 17 años de edad que acude a urgencias por un cuadro agudo de fiebre elevada, dolor faríngeo y adenopatías cervicales. Previamente había sido diagnósticada de faringitis aguda y recibió tratamiento con amoxicilina, presentando posteriormente un exantema cutáneo maculoso generalizado. Se realiza analítica que presenta ligera leucocitosis y presencia de leucocitos activados, ligera trombopenia y transaminasas levemente aumentadas.', '¿Cuál sería el diagnóstico más probable de este cuadro clínico?', '[{"position": 1, "text": "Es un cuadro típico de mononucleosis infecciosa."}, {"position": 2, "text": "Infección por varicela zoster."}, {"position": 3, "text": "Toxoplasmosis aguda."}, {"position": 4, "text": "Enfermedad de Lyme."}, {"position": 5, "text": "Infección por herpes virus 8."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta correcta es la primera. Es un cuadro típico de mononucleosis infecciosa. Aunque puede darse un cuadro similar en una toxoplasmosis aguda, menos del 1% de las infecciones agudas por toxoplasma se presentan como mononucleosis. Característico de la mononucleosis infecciosa por Epstein-Barr es la aparición del exantema macular tras el tratamiento por amoxicilina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e404ff02dea9', 'e6c3617dabf231fa8b87fbc936d630875f088254', NULL, NULL, NULL, false, false, 'Nefrología', 'Una mujer de 58 años acude para una visita de seguimiento por diabetes mellitus e hipertensión. Se siente bien pero afirma que ha dejado de tomar el verapamilo por estreñimiento. Presenta intolerancia a los IECAs por tos. En la exploración, la tensión arterial es de 156/92 mm Hg. En la analítica incluyen una creatinina de 1.6 mg/dL, excreción de proteínas en orina de 24 horas de 1.5 g/día y un aclaramiento de la creatinina de 45 ml/min.', 'Sobre esta base, ¿cuál es el tratamiento más eficaz para enlentecer la progresión de la nefropatía diabética tipo 2 de la paciente?', '[{"position": 1, "text": "Inhibidor de la enzima convertidora de la angiotensina."}, {"position": 2, "text": "Bloqueador del receptor de la angiotensina."}, {"position": 3, "text": "Antagonista del calcio."}, {"position": 4, "text": "Alfa-bloqueante."}, {"position": 5, "text": "Beta-bloqueante."}]'::jsonb, 5, 2, 'definitiva', 'Esta pregunta es típica y bastante fácil. Los fármacos antihipertensivos que han demostrado enlentecer la progresión de la nefropatía diabética son los IECAS y los ARAII. En concreto, los bloqueadores del receptor de la angiotensina II han demostrado su eficacia en este campo para la DM tipo 2, lo que unido a los efectos secundarios que le producen los IECAS a la paciente hace que un ARAII sea el fármaco de elección. No me parece una pregunta impugnable (Esto sin entrar en asuntos farmacoeconómicos, claro…).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-751dd33da435', 'eb80bd72948136893c710c7242d00b2a12b166b3', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 19 años, peso 60 kg, con deshidratación aguda por larga exposición al sol. Presión arterial tumbada 100/60 mmHg. De pie, 70/50 mmHg con sensación de mareo. Niveles de sodio sérico 155 mmol/L.', '¿Cuál es el tratamiento más correcto, en las primeras 24 horas, teniendo en cuenta los datos de los que disponemos?', '[{"position": 1, "text": "Suero salino hipertónico (3%), 500 ml + 500 ml de glucosado de 5%."}, {"position": 2, "text": "Suero hiposalino (0.45%), 3000 ml."}, {"position": 3, "text": "Suero glucosado 5% 1000 ml."}, {"position": 4, "text": "Hidratación oral con 1 litro de agua."}, {"position": 5, "text": "Suero salino isotónico (0.9%), 2000 ml."}]'::jsonb, 5, 2, 'definitiva', 'Esta pregunta no es fácil. La literatura disponible es algo controvertida (unas guías aconsejan usar suero glucosado, otras lo proscriben absolutamente…) por lo que he decidido basarme en el tratamiento recomendado por el Harrison, que es el manual en el que suelen basarse los examinadores del MIR. Esta chica presenta una hipernatremia por pérdidas de agua libre extrarrenales. El objetivo es reponer el agua perdida y reducir la natremia a una velocidad no superior a 12 mmol/día. Para calcular la fluidoterapia, hay que calcular primero el déficit de agua. Déf. Agua = (Natremia-140/140)xAgua corporal total. ACT = Peso en kg x 0,4 en mujeres/0,5 en varones. En este caso, el déficit de agua es: ([[tel:155-140/140|155-140/140]])x60x0,4 = 2,57 litros. Sólo hay dos respuestas que se aproximen a esta cifra, pero la 2 parece más correcta, pues es la única que cubre completamente el déficit de agua y utiliza una solución hiposódica.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2472b307ceac', 'aa4d8ca7cbc502c11e820c46f737f674f4719852', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un hombre de 65 años, oficinista jubilado y fu­mador de 1 paquete diario de cigarrillos, acude a consulta por un cuadro de tos persistente, gene­ralmente seca y disnea progresiva de 2 años de evolución que en la actualidad es de grado 2. El paciente niega otros síntomas. La exploración física no muestra datos relevantes.', 'La actitud a seguir sería:', '[{"position": 1, "text": "Iniciar tratamiento con broncodilatadores inhalados."}, {"position": 2, "text": "Realizar RX de Torax y espirometría con prueba broncodilatadora."}, {"position": 3, "text": "Pautar corticoides orales."}, {"position": 4, "text": "Realizar TC torácica."}, {"position": 5, "text": "Realizar gasometría arterial basal."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es la 2 (Realizar RX de Torax y espirometría con prueba broncodilatadora). Probablemente sea un EPOC pero hay que confirmarlo y valorar la gravedad de la obstruccion con la espirometría antes de iniciar tratamiento. Es un paciente de riesgo para cancer de pulmon por lo que es obligado realizar Rx de torax para descartar esta u otras patologias que justificarian los síntomas, aunque lo mas probable es que sean por el debut de su EPOC.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2957406ecfb6', 'd2ce475f53986173e8a158ec3d1f9809e080e38b', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Una mujer de 42 años, casada y con 2 niños en edad escolar, consulta a su médico de familia por un fuerte dolor de cabeza de unos 7 días de evolución. Aunque ya hace más de un año viene teniendo episodios similares, en los 2 últimos meses se han agravado notablemente. El dolor es como un peso que comienza en la zona occipital, se extiende a ambas regiones temporales y apenas se le alivia tomarndo pastillas de 650 mg de paracetamol, por lo que solicita una TC (está convencida de que “algo tiene que tener en la cabeza”).', '¿Cuál de las siguientes es la causa más plausible de su cefalea?', '[{"position": 1, "text": "La migraña."}, {"position": 2, "text": "Los trastornos vasculares."}, {"position": 3, "text": "La arteritis de la arteria temporal."}, {"position": 4, "text": "La tensional."}, {"position": 5, "text": "La oncológica."}]'::jsonb, 5, 4, 'definitiva', 'Así como el año pasado nos quisieron pintar de mala a una enfermera por despertarnos por un paciente con miastenia este año se entretienen presentándonos a una paciente que pide un TC. Interpreto que muestran a una paciente estresada por sus niños con cefaleas recurrentes de localización occipital que antes aliviaba con una dosis baja de paracetamol y ahora no. Tanto la localización inicialmente occipital, el tiempo de evolución de 2 años, como la sensación de peso orientan a la respuesta 4, una cefalea tensional. Rápidamente se descartan la migraña y los trastornos vasculares, acompañados de otros síntomas neurológicos o naúseas, fotofobia, etc; así como la arteritis de la temporal rara antes de los 50 años. La cefalea tumoral suele ser “in crescendo”, no recurrente como hace pensar el caso y acompaña otros síntomas neurológicos o de hipertensión intracraneal.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3a3d08111aec', 'bc3583b4209704d8c538d5372486eb992fe71a69', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un varón de 78 años consulta por un cuadro de deterioro cognitivo progresivo de un año de evolución con fallos de memoria y orientación. Su familia refiere alucinaciones visuales recurrentes, caídas ocasionales y un enlentecimiento motor llamativo.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Demencia vascular multi-infarto."}, {"position": 2, "text": "Demencia tipo Alzheimer."}, {"position": 3, "text": "Demencia con cuerpos de Lewy difusos."}, {"position": 4, "text": "Demencia fronto-temporal."}, {"position": 5, "text": "Hidrocefalia normotensiva."}]'::jsonb, 5, 3, 'definitiva', 'Una demencia que presenta al inicio de la evolución alucinaciones visuales (en los 2 primeros años) es muy sugerente de cuerpos de Lewy, y es el síntoma guía en estas preguntas. Si a ello sumamos las caídas y el enlentecimiento motor sugerente de parkinsonismo, hace más fácil la pregunta. Por lo tanto, correcta la número 3.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-47a5ce2ac6a5', '4bd767a12abe4144ff15b60693220b7267445b7c', NULL, NULL, NULL, false, false, 'Cirugía General', 'Un hombre de 30 años sufre una caída de una altura de 2 metros de pie. A su llegada a urgencias en camilla consciente y orientado, con sondaje vesical con orina clara. Muestra tumefacción de talón izquierdo y hormigueos leves por cara anterior del muslo izquierdo y escroto así como disestesias en ambos pies. El paciente se despide del camillero con un apretón de manos con una palmada simultánea en el hombro. La rotación de los miembros inferiores en la camilla cogidos por los tobillos es indolora y la compresión de la pelvis es asintomática.', 'A continuación:', '[{"position": 1, "text": "Lo sentaremos en la camilla para poder explorar la columna cervical."}, {"position": 2, "text": "Remitirlo a la radiología para realizar estudio de las extremidades inferiores (pies, fémures, pelvis)."}, {"position": 3, "text": "Palparemos el abdomen y rodaremos en bloque para palpar la columna toracolumbar."}, {"position": 4, "text": "Le colocaremos un collarin cervical y remitiremos a radiología para estudio de la imagen de extremidades inferiores y columna cervical."}, {"position": 5, "text": "Solicitaremos una ecografía abdominal."}]'::jsonb, 5, 3, 'definitiva', 'Creo que la respuesta correcta es la 3. El paciente por el mecanismo lesional-caída de pie-, por la fractura de calcáneo y por la sintomatología neurológica sugiere una lesión medular baja por fractura de la columna lumbar. La lesión no es alta porque mueve los brazos. Tampoco parece una lesión de la pelvis por la ausencia de dolor a la movilización o palpación. Si hay una sospecha de lesión de la pelvis en la evaluación primaria de todo politraumatizado (ATLS) se debe realizar una exploración de la columna rotándolo en bloque para evitar producir más lesión. La palpación abdominal también forma parte de la evaluación inicial. La ecografía abdominal puede estar indicada en pacientes inestables hemodinámicamente si se sospechan lesiones abdominales pero en todo caso se hace después de la evaluación inicial.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-cdb3e8f2e75b', '2d7af393cf5e1d251db647068203bef1f1e7a0ca', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un individuo presenta “debilidad muscular” (hemiparesia espástica) de ambas extremidades derechas, con hiperreflexia y signo de Babinski, junto a una “parálisis fláccida facial” de la hemicara izquierda, con incapacidad para cerrar el ojo izquierdo o de retraer el lado izquierdo de la boca, además de otras alteraciones.', 'Por los datos descritos se trata de una alteración que afecta, entre otros elementos, a los fascículos motores: córtico-espinal y córtico-nuclear, pero ¿a qué nivel del neuroeje localizaría la lesión?', '[{"position": 1, "text": "A nivel del área 4 de Brodmann de la corteza cerebral del lado derecho."}, {"position": 2, "text": "En la cápsula interna, brazo posterior del lado derecho."}, {"position": 3, "text": "En el pedúnculo cerebral izquierdo."}, {"position": 4, "text": "En la porción medial de la protuberancia caudal del lado izquierdo."}, {"position": 5, "text": "En el bulbo raquídeo antes de la decusación del fascículo córtico-espinal derecho."}]'::jsonb, 5, 4, 'definitiva', 'Pregunta siempre liante del tronco del encéfalo. Tenemos una hemiparesia derecha y afectación del núcleo del facial izquierdo, ya que tiene afectado el facial superior y el inferior; por lo tanto tenemos una clínica cruzada, teniendo que pensar en afectación del tronco del encéfalo. Si tenemos en un esquema rápido de dónde parten los núcleos de los pares craneales: los 4 primeros por encima de la protuberancia, los 4 siguientes en la protuberancia, y los 4 últimos por debajo de la protuberancia, tenemos que el núcleo facial está en los 4 del medio. O sea núcleo facial izquierdo, protuberancia izquierda, así que respuesta 4.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-516e83e15e3a', 'cf5f35b24ee5e35a4b814ee4e247ba39c6191f46', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 54 años, con antecedentes personales de DM, HTA e insuficiencia renal crónica leve, que presenta somnolencia y hemiparesia derecha. En la analítica: creatinina de 2.3 mg/dl, Hb 10.3 g/dl y plaquetas 20000 mm3, con coagulación normal. En TAC craneal: lesiones isquémicas con necrosis microhemorrágicas. Posteriormente comienza con deterioro progresivo del nivle de conciencia y aumento de Cr, LDH y bilirrubina no conjugada. Se realiza Coombs directo que es negativo. Esquistocitos en frotis.', 'Ante la sospecha diagnóstica la conducta a seguir es:', '[{"position": 1, "text": "Nuevo TAC craneal ante la sospecha de transformación hemorrágica de ictus isquémico."}, {"position": 2, "text": "Iniciar plasmaféresis urgente."}, {"position": 3, "text": "Inicio de tratamiento con glucocorticoides a dosis de 1 mg/kg/día."}, {"position": 4, "text": "Buscar causa desencadente de cuadro de CID."}, {"position": 5, "text": "Sospecha de Mieloma Múltiple: aspirado de médula ósea."}]'::jsonb, 5, 2, 'definitiva', 'Veamos: un paciente con ciertos antecedentes que tiene: – Esquistocitos en frotis: indica anemia microangiopática, ruptura de hematíes de causa mecánica, cosa que se puede ver fundamentalmente en PTT, anemia hemolítica autoinmune y CID. – Bicitopenia: ahí las causas pueden ser muuuuuy variadas. – Elevación de LDH y Bilirrubina, lo cual indica ruptura de hematíes a cascoporro. – Coombs directo negativo: dato esencial, indica que no hay ningún anticuerpo que se pegue al hematíe. Con estos mimbres vamos a tejer el cesto: Respuesta 1: no puede ser porque una transformación hemorrágica no da una elevación de LDH y Cr tan brutal, además de no explicar la esquistocitosis. Respuesta 2: plasmaféresis urgente…en caso de púrpura trombótica trombocitopénica sí; esta respuesta me gusta porque justifica la bicitopenia, ya que se produce anemia hemolítica microangiopática por ruptura de los hematíes al ser fragmentados por los multímeros de factor de von Willebrand ultralargos en caso de deficiencia de la enzima ADAMST13, con lo que se producen agregados plaquetarios brutales y el citómetro de flujo no cuenta 400 plaquetas, sino un molondrón de plaquetas que forman una masa, de ahí la trombocitopenia. También explica el Coombs directo negativo, la elevación de LDH y Cr. Respuesta 3: una situación tan crítica como la de ese paciente indica que algo gordo está pasando y yo no me sentaría a esperar a que los glucocorticoides hicieran efecto…y no caigo ahora mismo qué patología da esa sintomatología y tenga ese tratamiento como estándar. Respuesta 4: buscar desencadenante de cuadro de CID…tendría sentido de no ser porque en el CID es MUY característico el consumo de factores de coagulación, lo cual no se da en este caso. Respuesta 5:un mieloma no da esquistocitosis ni tiene esa sintomatología, tendrían que dar otros datos que apoyara esa patología, como el dolor óseo y la hipercalcemia…', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-80cedb64d912', 'e92bcf8bdfcc428e1a9f8c6f5618595cafdf80ec', NULL, NULL, NULL, false, false, 'Oftalmología', 'Hombre de 35 años que acude al servicio de urgencias por dolor en su ojo derecho de 3 días de evolución. La exploración biomicroscópica del segmento anterior muestra, tras tinción con fluoresceína, una úlcera corneal central en forma de dendrita.', '¿Cuál es su diagnóstico?', '[{"position": 1, "text": "Queratitis herpética."}, {"position": 2, "text": "Abrasión corneal."}, {"position": 3, "text": "Queratitis fúngica."}, {"position": 4, "text": "Queratitis bacteriana."}, {"position": 5, "text": "Crisis glaucomatociclítica."}]'::jsonb, 5, 1, 'definitiva', 'La úlcera corneal dendrítica es típica de la queratitis por herpes simplex. Cursa con dolor, no demasiado llamativo, y ojo rojo escaso o ausente. Existen úlceras que recuerdan a dendritas que pueden confundirnos en el diagnóstico. Estas pseudodendritas nos las encontramos en el herpes Zoster y en las abrasiones corneales en resolución. Si bien en la práctica tendríamos que fijarnos bien en la forma de la dendrita (la dendrita auténtica es más profunda y tiene bulbos terminales al final de cada ramificación), y fijarnos en la evolución del dolor (en la pseudodendrita tras abrasión el dolor debe ir mejorando), a la hora de contestar una pregunta MIR es más sencillo: si es una dendrita, lo primero que tenemos que pensar es herpes. Las queratitis fúngicas y bacterianas tienen infiltrados corneales. Y la crisis glaucomatociclítica (síndrome de Posner Schlossman) es un tipo de uveítis anterior hipertensiva idiopática, que no cursa con úlcera.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e42265b33324', 'f28dadc3ff468d8b276db7295179db309fbb285c', NULL, NULL, NULL, false, false, 'Oncología', 'Hombre de 64 años con cirrosis hepática Child A sin antecedentes de descompensación. Tras detección de una lesión focal hepática en ecografía de cribado se completa el estudio con una TC toracoabdominal. En esta exploración se objetiva la presencia de 4 lesiones hepáticas (una de ellas de hasta 6 cm) con patrón de captación típico de hepatocarcinoma, invasión vascular tumoral y una metástasis en la glándula suprarrenal derecha. No se observa ascitis. El paciente refiere únicamente astenia, pero no presenta síndrome general.', 'El tratamiento de este paciente sería:', '[{"position": 1, "text": "Tratamiento sintomático y de soporte, ya que presenta un hepatocarcinoma avanzado con invasión vascular y metástasis."}, {"position": 2, "text": "Quimioembolización transarterial (TACE), ya que el tratamiento aumenta la supervivencia de los pacientes con hepatocarcinoma avanzado."}, {"position": 3, "text": "Quimioterapia sistémica con doxorrubicina iv ya que presenta enfermedad diseminada pero presenta buen estado general."}, {"position": 4, "text": "Tratamiento con sorafenib oral, ya que se trata de un enfermo con buen estado general, Child A y hepatocarcinoma en estadio avanzado BCLC-C."}, {"position": 5, "text": "El tratamiento adecuado es el trasplante hepático ya que es el único procedimiento que elimina completamente el tumor primario y evita las complicaiones futuras de la cirrosis."}]'::jsonb, 5, 4, 'definitiva', 'Comentario:El paciente presenta un buen estado general con un hepatocarcinoma recién diagnosticado, no darle ningún tipo de tratamiento más que el sintomático y de soporte a estas alturas no sería lo correcto. La TACE no estaría indicada por tener afectación extrahepática. El trasplante teniendo enfermedad extrahepática tampoco se lo harían. Nos quedan las respuestas 3 y 4, las dos con tratamiento sistémico (indicado por ser metastásico) y la correcta es la 4, por todas las razones que da en la misma.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0345c6427c06', 'fe9aa781f8dc1d9405e0f2a0b0ece8294460c786', NULL, NULL, NULL, false, false, 'Oncología', 'Hombre de 60 años acude a urgencias por crisis comicial. Ex-fumador desde hace 3 años, sin otros antecedentes de interés. Una TAC evidencia metástasis múltiples.', '¿Cuál es el origen más probable?', '[{"position": 1, "text": "Cáncer de cabeza y cuello."}, {"position": 2, "text": "Cáncer de pulmón."}, {"position": 3, "text": "Cáncer de vejiga urinaria."}, {"position": 4, "text": "Cáncer de colon."}, {"position": 5, "text": "Cáncer de páncreas."}]'::jsonb, 5, 2, 'definitiva', 'Muy fácil, ¿no? El cáncer de pulmón es la causa más frecuente de las metástasis cerebrales y en un 20-30% de los casos es a raíz de ellas que se diagnostica el tumor primario (como aquí).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fe6285dd0a83', '281493e3aedd7fe5a3bc110b7b70362c0ef5f06e', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', 'Niño que acude a consulta de ambulatorio porque se lleva la mano al oído, sin fiebre ni signos inflamatorios agudos y que en la exploración se observa un tímpano sonrosado/ambarino. Como antecedentes refiere que hace un mes presentó un episodio de otalgia, fiebre acompañada de irritabilidad y que fue tratado con amoxicilina 40 mg/kg/día.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Otitis media aguda recidivante."}, {"position": 2, "text": "Otitis media serosa."}, {"position": 3, "text": "Otitis media crónica simple."}, {"position": 4, "text": "Otitis media crónica colesteatomatosa."}, {"position": 5, "text": "Mastoiditis."}]'::jsonb, 5, 2, 'definitiva', 'Leyendo el caso, vamos descartando opciones: niño con otalgia, pero sin fiebre ni signos inflamatorios agudos: ya no es ni la 1 (otitis media aguda recidivante) ni la 5 (mastoiditis). En la otoscopia, se observa un tímpano sonrosado y ambarino: no se observan escamas, luego no es la 4 (otitis media crónica colesteatomatosa); ni tampoco perforaciones ni adhesiones, luego tampoco es la 3 (otitis media crónica simple). La otoscopia es característica de una otitis media serosa (respuesta 2 correcta). Es conocido por ORL, pediatras y médicos de familia que en el mes siguiente a una otitis media aguda, el oído medio queda ocupado por un contenido mucoseroso cuya evolución conviene vigilar. Tampoco creo que sea impugnable.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5ec5403d3daf', '4fe1bb19e37d63a92309e67e08f3ba1aff3c3b14', NULL, NULL, NULL, false, false, 'Otorrinolaringología y Cirugía Maxilofacial', 'Paciente de 64 años fumador y bebedor importante sin otros antecedentes de interés. El cuadro que explica es de odinodisfagia de 3 meses de evolución y otalgia izquierda. Aporta informe del odontólogo que descarta causa de origen dental. También refiere haber sido visitado por diferentes especialistas aportando un TAC de cabeza y cuello (sin contraste yodado) que es informado como normal. A la exploración destaca una disminución en la capacidad de propulsión de la lengua; la palpación de la base de lengua izquierda objetiva una induración de consistencia pétrea de aprox. 3cm y con laringoscopia indirecta no se oberva ninguna ulceración de la mucosa. La palpación cervical es negativa para adenopatías.', '¿Cuál es su diagnótico de presunción y conducta?', '[{"position": 1, "text": "Causa dental / revaloración por el odontólogo."}, {"position": 2, "text": "Absceso de la base de lengua / desbridamiento."}, {"position": 3, "text": "Anquiloglosia / liberación quirúrgica de la misma."}, {"position": 4, "text": "Proceso maligno de orofaringe / repetir TC y biopsia."}, {"position": 5, "text": "Inflamación inespecífica / tratamiento corticoideo."}]'::jsonb, 5, 4, 'definitiva', 'Nos presentan un paciente con factores de riesgo para cáncer de orofaringe, pero en el que la exploración y las pruebas son normales. ¿Qué pasa aquí? Esta pregunta es de psicología inversa: ¿qué quería que yo supiera el que puso la pregunta? Esta pregunta la ha hecho un otorrinolaringólogo. Ya te dice que el odontólogo «no le ha visto nada», así que descarta la 1. Tampoco es un absceso de base de lengua, porque en tres meses le habría matado: la 2 tampoco. Así que nos quedan anquiloglosia, cáncer de base de lengua e inflamación inespecífica. Cuando hay duda de que pueda ser un cáncer, no hay que andarse con tonterías y pedir un nuevo TAC y una biopsia. Los cánceres de base de lengua son muy traicioneros y es uno de los miedos de cualquier otorrinolaringólogo cuando sospecha una neoplasia. No es raro que debuten sin masas exofíticas ni ulceraciones de la mucosa lingual y en la TAC son difíciles de detectar cuando no se usa contraste. La respuesta correcta es la 4 y no creo que pueda ser impugnada.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-43812b7960fa', 'fea1ef9d369d60e0877eb4599c7c8fbc2e9d45ea', NULL, NULL, NULL, false, false, 'Pediatría', 'Un recién nacido de 37 semanas de edad gestacional, sin hallazgos patológicos en la ecografía prenatal, presenta en la exploración realizada en el paritorio un “stop” al paso de la sonda nasogástrica. La radiografía de tórax y abdomen muestra un bolsón esofágico atrésico, con una neumatización gastrointestinal normal. Tras evaluación diagnóstica que descarta otras anomalías y encontrándose en situación respiratoria estable, se decide intervención quirúrgica.', '¿En qué se basa la prioridad de intervenir este paciente?', '[{"position": 1, "text": "Por la imposibilidad de deglutir saliva."}, {"position": 2, "text": "Por las malformaciones cardiacas frecuentemente asociadas."}, {"position": 3, "text": "Por el riesgo de neumonitis por aspiración."}, {"position": 4, "text": "Por la imposibilidad de alimentación enteral."}, {"position": 5, "text": "Por la traqueomalacia asociada."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es la 3. El hecho de que haya aireación intestinal orienta a la existencia de una fístula del segmento inferior esofágico con la tráquea o con un bronquio. En este caso las complicaciones pulmonares son frecuentes por el paso del contenido gástrico a la vía respiratoria.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c0c76c63e3a0', '18fc9fc96848c870259923d637d3d474633edc59', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 2 años, en sus antecedentes personales destacan: 3 episodios de otitis media aguda, 1 meningitis meningocócica y 2 neumonías (una de lóbulo medio y otra de lóbulo superior izquierdo). Ha ingresado en 3 ocasiones por púrpura trombopénica (en tres ocasiones los anticuerpos antiplaquetas fueron negativos y en la médula ósea se observaban megacariocitos normales). Varios varones de la familia materna habían fallecido en la infancia por presentar procesos infecciosos. En la exploración presenta lesiones típicas de dermatitis atópica. En el estudio inmunológico destaca una leve disminución de subpoblaciones de linfocitos T; elevación de IgA e IgE; disminución de IgM e IgG en el límite inferior de la normalidad.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Síndrome de Wiskott-Aldrich."}, {"position": 2, "text": "Síndrome de hiperIgE."}, {"position": 3, "text": "Hipogammaglobulinemia transitoria de la infancia."}, {"position": 4, "text": "Inmunodeficiencia combinada severa asociada al X."}, {"position": 5, "text": "Inmunodeficiencia variable común."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta correcta es la 1. El síndrome de Wiskott-Aldrich asocia inmunodeficiencia, trombopenia y dermatitis atópica con el estudio inmunológico descrito en el enunciado.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4d820e59f4ce', '77598a774962c120a56987c985cda0f893766999', NULL, NULL, NULL, false, false, 'Pediatría', 'Niña de 12 años, hija única de padres sanos no consanguíneos. No refieren antecedentes personales ni familiares de interés. En el examen clínico para iniciar una actividad deportiva, usted encuentra una discreta hepatomegalia de consistencia normal, por lo que solicita una analítica, en la que destaca una ASAT de 80U/l, ALAT 105 U/l, proteinograma electroforético con todas las fracciones proteicas en rango normal y negatividad de la serología de virus hepatotropos.', '¿Qué debería descartar y qué prueba indicaría para ello?', '[{"position": 1, "text": "Déficit de alfa 1 antitripsina. TAC torácico para confirmar enfisema."}, {"position": 2, "text": "Mucoviscidosis. Determinación de cloro en sudor."}, {"position": 3, "text": "Hepatitis autoinmune. Biopsia hepática."}, {"position": 4, "text": "Glucogenosis tipo VI (déficit de fosforilasa). Biopsia muscular."}, {"position": 5, "text": "Enfermedad de Wilson. Determinar ceruloplasmina y cobre en sangre y orina."}]'::jsonb, 5, 5, 'definitiva', 'En realidad yo a esta paciente no le haría ninguna prueba en este momento, y comprobaría si la cifra de transaminasas se ha normalizado en un tiempo posterior, ya que la causa más frecuente, por lo menos en los niños, es una elevación transitoria en contexto de enfermedades víricas (las más frecuentes citomegalovirus y virus de Epstein-Barr). La elevación mínima de las enzimas hepáticas y el hecho de que tenga un perfil proteico normal va en contra de cronicidad… Si tuviera que elegir me quedaría con la respuesta 5, que me parece la menos agresiva, y puestos a hace analítica le añadiría la determinación de alfa-1-antitripsina (sin TC) y marcadores de celiaquía, pues la celiaquía también puede asociar cierta hipertransaminemia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-28ef2094821f', '6ffa66a40cc5f3c4ef2f34d1efe07edfe4163526', NULL, NULL, NULL, false, false, 'Pediatría', NULL, 'Ante un niño de 7 meses con fiebre e irritabilidad, fontanela abombada y un estudio de líquido cefalorraquídeo con 110 células/mm3 (75% linfocitos), proteínas 120 mg/dl y glucosa 28 mg/dl (glucemia sérica 89 mg/dl), ¿cuál es la sospecha diagnóstica más razonable?', '[{"position": 1, "text": "Meningitis vírica."}, {"position": 2, "text": "Meningitis bacteriana."}, {"position": 3, "text": "Meningitis tuberculosa."}, {"position": 4, "text": "Síndrome mononucleósico."}, {"position": 5, "text": "Síndrome de Guillain-Barré."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es la 3. Define un líquido cefalorraquídeo típico de tuberculosis. En la práctica clínica las cosas quizá no serían tan sencillas…..', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-da9531dba897', '133b1f22b69ff35af875d6c8e2d3165e3e4b80dc', NULL, NULL, NULL, false, false, 'Pediatría', 'Una niña de 13 años de edad, nos consulta por presentar pérdida de peso, astenia, amenorrea secundaria y estreñimiento. En la exploración destaca una temperatura de 35ºC, un peso inferior al percentil 3, bradicardia e hipotensión ortostática. En la analítica se comprueba anemia con leucopenia leve, colesterol de 230 mg/dl y en el electrocardiograma una onda T aplanada con descenso del ST y QTc prolongado.', '¿Qué proceso sospecharía y qué haría a continuación?', '[{"position": 1, "text": "Sospecharía una anorexia nerviosa e indagaría acerca de su ingesta, imagen corporal, etc."}, {"position": 2, "text": "Sospecharía un hipotiroidismo y solicitaría TSH y hormonas tiroideas."}, {"position": 3, "text": "Sospecharía una miocardiopatía y solicitaría una ecocardiografía."}, {"position": 4, "text": "Sospecharía una enfermedad celíaca y solicitaría anticuerpos anti transglutaminasa IgA."}, {"position": 5, "text": "Sospecharía un panhipopituitarismo y solicitaría una TC craneal."}]'::jsonb, 5, 1, 'definitiva', 'La respuesta correcta es la 1. Los síntomas y signos descritos son los hallazgos biológicos asociados a la anorexia nerviosa. Los trastornos en el ECG están derivados de las alteraciones electrolíticas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-283a6c513024', '4e485da64717f259bf5e63c86dbe79c9265ff12d', NULL, NULL, NULL, false, false, 'Pediatría', NULL, 'Niño de 1 mes, alimentado con lactancia materna exclusiva, consulta porque realiza una deposición cada 5 ó 6 días con esfuerzo pero de consistencia blanda, ¿cuál sería nuestra actitud?', '[{"position": 1, "text": "Iniciar tratamiento laxante."}, {"position": 2, "text": "Suplementar la lactancia materna con fórmula antiestreñimiento."}, {"position": 3, "text": "Iniciar estimulación rectal diaria."}, {"position": 4, "text": "Se considera ritmo intestinal normal."}, {"position": 5, "text": "Se deriva a Digestivo Infantil para descartar megacolon agangliónico."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es la 4. La normalidad en la emisión de deposiciones en los lactantes pequeños es muy amplia. Para sospechar un megacolon agangliónico suele haber un retraso en la evacuación del meconio y con frecuencia otros síntomas asociados como distensión abdominal, dificultad para ganar peso, etc.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7a9fc5d9e41f', 'edaaab1ed5cae0ba7e7bff73d6ec81573da7472b', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Una mujer de 23 años acude a urgencias por encontrarse muy nerviosa tras una discusión con su parea. En su historia clínica se reflejan varias demandas semejantes en el año anterior, en dos de ellas tras un gesto autolítico. Se constatan también conflictos frecuentes en las relaciones de pareja, cambios laborales y discusiones familiares. Dice sentirse incomprendida por todos incluidos los psiquiatras que la atienden.', 'El diagnóstico es:', '[{"position": 1, "text": "Trastorno de la personalidad límite."}, {"position": 2, "text": "Trastorno de la personalidad histriónico."}, {"position": 3, "text": "Distimia."}, {"position": 4, "text": "Trastorno disociativo."}, {"position": 5, "text": "Trastorno de despersonalización."}]'::jsonb, 5, 1, 'definitiva', 'La mujer tiene 23 años y está cabreada. Le hace falta apoyo y bastante educación afectiva para frenar su impulsividad… se siente incomprendida… a lo mejor tiene razón… El tema esta en que no soporta el rechazo y tiene gestos autolíticos. El diagnóstico es el 1. El 3,4 y 5 ni por asomo, no hay clínica descrita en la pregunta. Luego en la vida real explorando bien casi seguro que habría síntomas disociativos y de despersonalización, así como síntomas depresivos… pero síntoma no es trastorno. ¿Por que no el 2? Podría ser también puntualizando mucho e hilando muy fino… aquí la discusión está servida. Os pongo los criterios de cada uno y lo hablamos,… pero la intención del examinador era la 1 y la veo bien defendida. No se puede impugnar. • El límite: Un patrón general de inestabilidad en las relaciones interpersonales, la autoimagen y la efectividad, y una notable impulsividad, que comienzan al principio de la edad adulta y se dan en diversos contextos, como lo indican cinco (o más) de los siguientes ítems: 1. Esfuerzos frenéticos para evitar un abandono real o imaginado. Nota: No incluir los comportamientos suicidas o de automutilación que se recogen en el Criterio 5. 2. Un patrón de relaciones interpersonales inestables e intensas caracterizado por la alternancia entre los extremos de idealización y devaluación. 3. Alteración de la identidad: autoimagen o sentido de sí mismo acusada y persistentemente inestable. Impulsividad en al menos dos áreas, que es potencialmente dañina para sí mismo (p. ej., gastos, sexo, abuso de sustancias, conducción temeraria, atracones de comida). Nota: No incluir los comportamientos suicidas o de automutilación que se recogen en el Criterio 5. 5. Comportamientos, intentos o amenazas suicidas recurrentes, o comportamiento de automutilación. Inestabilidad afectiva debida a una notable reactividad del estado de ánimo (p. ej., episodios de intensa disforia, irritabilidad o ansiedad, que suelen durar unas horas y rara vez unos días). 7. Sentimientos crónicos de vacío. 8. Ira inapropiada e intensa o dificultades para controlar la ira (p. ej., muestras frecuentes de mal genio, enfado constante, peleas físicas recurrentes). 9. Ideación paranoide transitoria relacionada con el estrés o síntomas disociativos graves. • El histriónico: Un patrón general de excesiva emotividad y una búsqueda de atención, que empiezan al principio de la edad adulta y que se dan en diversos contextos, como lo indican cinco (o más) de los siguientes ítems: 1. No se siente cómodo en las situaciones en las que no es el centro de la atención. 2. La interacción con los demás suele estar caracterizada por un comportamiento sexualmente seductor o provocador. 3. Muestra una expresión emocional superficial y rápidamente cambiante. 4. Utiliza permanentemente el aspecto físico para llamar la atención sobre sí mismo. 5. Tiene una forma de hablar excesivamente subjetiva y carente de matices. 6. Muestra autodramatización, teatralidad y exagerada expresión emocional. 7. Es sugestionable, por ejemplo, fácilmente influenciable por los demás o por las circunstancias. 8. considera sus relaciones más íntimas de lo que son en realidad.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-dff0631d5e67', 'fde30b076590a20330991737a22bd7660ccf7cf4', NULL, NULL, NULL, false, false, 'Psiquiatría', 'Mujer de 52 años que acude a urgencias con una parálisis bilateral de las extremidades superiores que se había instaurado de manera brusca dos horas antes. En la entrevista se muestra risueña y verbaliza no entender por qué sus familiares están tan preocupados. La familia refiere que el día anterior su hijo había sido detenido por la policía por tráfico de drogas y todavía no había podido contactar con él.', '¿Cuál de los siguientes es el diagnóstico más probable?', '[{"position": 1, "text": "Trastorno facticio."}, {"position": 2, "text": "Trastorno delirante."}, {"position": 3, "text": "Hipocondriasis."}, {"position": 4, "text": "Trastorno depresivo mayor."}, {"position": 5, "text": "Trastorno conversivo."}]'::jsonb, 5, 5, 'definitiva', 'La palabra bonita para describir esto es: «Belle indeference», esta mujer se muestra con una elegante indiferencia hacia una parálisis. El diagnóstico… se pueden excluir 2,3,4 porque la clínica no coincide: no hay delirio, no hay preocupación, no hay tristeza. La 1 sería si sacase algo de provecho, si estuviese simulando a sabiendas y para sacar un beneficio finigiese su enfermedad. No es el caso. Conversivo sería si el síntoma nos quisiese transmitir algo, es decir, fuese una metáfora de su mundo interno… Lo más exacto en este caso: El 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f223375f6883', 'd464e162b745ae0ed6257228812d47b12c0cb935', NULL, NULL, NULL, false, false, 'Cirugía General', 'Un hombre de 41 años acude a consulta por un nódulo en el tiroides derecho se realiza una punción aspiración con aguja fina.', 'El análisis citológico nos permitirá:', '[{"position": 1, "text": "Distingue entre adenoma folicular o carcinoma folicular mínimamente invasivo."}, {"position": 2, "text": "Identificar las zonas de invasión capsular o vascular del carcinoma folicular."}, {"position": 3, "text": "Reconocer la hiperplasia de células G asociadas a cáncer medular familiar."}, {"position": 4, "text": "Distinguir entre un tumor de células de Hurthle y un adenoma folicular oxifilia."}, {"position": 5, "text": "Identificar las características citológicas típicas del carcinoma papilar."}]'::jsonb, 5, 5, 'definitiva', 'Creo que la respuesta correcta es la 5; la PAAF no permite hacer un estudio histológico si no citológico por lo tanto se eliminan las preguntas 1, 2. La 3 parece que se ha puesto de relleno porque no viene al caso. La 4 podría hacer dudar si no eres patólogo perola respuesta más lógica es la 5 ya que el carcinoma papilar es el más frecuente.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e9f6bfbe3947', '0f53c5a055ec04e56696a81288d924a9d74fc608', NULL, NULL, NULL, false, false, 'Reumatología', 'Hombre de 62 años con antecedentes de hipertensión arterial en tratamiento con captoprilo, úlcera duodenal y urolitiasis por ácido úrico. Consulta por crisis de podagra típica similar a otras presentadas en los últimos dos años. En la exploración se observan tofos en ambos pabellones auriculares. Los análisis muestran ácido úrico 10,1 mg/dl, creatina 1,5 mg/dl.', 'Indique cúal de las siguinetes respuestas es FALSA en relación con su posible tratamiento con alopurinol.', '[{"position": 1, "text": "Su empleo es de segunda elección, cuando han fracasado los uricosúricos."}, {"position": 2, "text": "Su empleo por tiempo prolongado es prácticamente obligado porque existen tofos."}, {"position": 3, "text": "Su introducción debe demorarse hasta que se haya resulto el ataque actual con antiinflamatorios o con colchina."}, {"position": 4, "text": "Su introducción debe ser gradual hasta una dosis que consiga una uricemia inferior a 6 mg/dL."}, {"position": 5, "text": "En los primeros meses de tratamiento se aconsejar asociar dosis bajas de colchicina para prevenir nuevos ataques."}]'::jsonb, 5, 1, 'definitiva', 'El alopurinol es siempre el tratamiento de elección y, sobre todo, si se trata de una gota tofácea. Además, en este caso, los uricosúricos podrían empeorar la urolitiasis al aumentar la uricosuria (perdón por la redundancia…).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-caf2cd95d381', '764b6d45356901ac3a7df56d809c1ebd913b5926', NULL, NULL, NULL, false, false, 'Reumatología', 'Paciente de 40 años, que acude a urgencias por estomatitits aftosa, conjuntivitis, uretritis, balanitis y dolor articular.', '¿Cúal de los siguientes diagnósticos es el más probable?', '[{"position": 1, "text": "Behçet."}, {"position": 2, "text": "Síndrome de artritis reactiva."}, {"position": 3, "text": "Síndrome de Sweet."}, {"position": 4, "text": "Déficit de vitamina A."}, {"position": 5, "text": "Infección por Gonococo."}]'::jsonb, 5, 2, 'definitiva', 'Ante este cuadro clínico y sin tener pruebas complementarias disponibles, el diagnóstico más probable es el de artritis reactiva. El único problema es que en el enunciado se habla de dolor articular y no de artritis… El síndrome de Reiter (tríada de conjuntivitis, uretritis y artritis) es una de las formas en las que se puede presentar una artritis reactiva. En la enfermedad de Behçet pueden aparecer aftas orales y genitales pero la uretritis no es una característica. Y la afección ocular propia es la uveítis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2173fe23429a', 'c443c2f1522c9e6a86993535d7e04561e0626dbf', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Paciente de 75 años de edad, con importante gonartrosis con «Genu Varo» que le condiciona marcada impotencia funcional, limitación de la movilidad y dolor contínuo que le exige estar con medicación antirreumática, antiinflamatoria y analgésicos de forma continuada.', '¿Qué tratamiento debe indicarse en este caso?', '[{"position": 1, "text": "Lavado artroscópico de la rodilla."}, {"position": 2, "text": "Rehabilitación de la rodilla afectada."}, {"position": 3, "text": "Artroplastia de la rodilla afectada."}, {"position": 4, "text": "Osteotomía tibial supratuberositaria de abducción."}, {"position": 5, "text": "Sinovectomía de rodilla."}]'::jsonb, 5, 3, 'definitiva', 'Estamos ante un paciente que ha agotado la vía farmacológica dado que toma de todo y tiene dos problemas importantes: el genu varo y una importante gonartrosis. Esto significa que no podemos hacer nada con una artroscopia ni mucho menos con una sinovectomía (1 y 5 falsas). El genu varo podría falsamente hacernos pensar en una osteotomía, no obstante aunque la hiciéramos y corrigiéramos el varo ahora el daño ya está hecho ya la artrosis es severa. Quizás hace años antes de que tuviera lugar la artrosis hubiera sido resolutivo pero no ahora (4 falsa). Además, para plantearnos una osteotomía deberían darnos más datos para saber sobre qué hueso aplicar la osteotomía si sobre tibia o sobre fémur. Por último quizás pensemos que lo mejor es intentar primero la rehabilitación antes de pensar en la cirugía pero desecho esta opción porque la pregunta hace hincapié en que hemos agotado las medidas farmacológicas (aunque podría considerarse porque no nos han especificado si se ha intentado o no). En cualquier caso con la prótesis de rodilla corregimos el problema del dolor de la artrosis y podemos corregir también el varo de rodilla.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-21d0cab8345a', 'f23f88b216d2a37c77b12df0277cf386eb213aad', NULL, NULL, NULL, false, false, 'Traumatología y Cirugía Ortopédica', 'Chico de 12 años obeso (87 kg). Refiere desde hace 4 meses dolor mecánico en muslo y rodilla derecha. A la exploración clínica se evidencia una discrepancia de la longitud de las extremidades inferiores de 1 cm y actitud de la extremidad inferior derecha en rotación externa con pérdida de la rotación interna.', 'Debemos sospechar que presenta:', '[{"position": 1, "text": "Artritis crónica juvenil."}, {"position": 2, "text": "Epifisiolisis capitis femoris."}, {"position": 3, "text": "Fractura del cuello femoral por sobrecarga."}, {"position": 4, "text": "Enfermedad de Perthes."}, {"position": 5, "text": "Secuelas de displasia del desarrollo de la cadera."}]'::jsonb, 5, 2, 'definitiva', 'Nos presentan un paciente adolescente con sobrepeso y dolor en muslo y rodilla, discrepancia de longitud de 1 cm y el miembro en rotación externa. Este cuadro nos debe hacer marcar automáticamente la epifisiolisis capitis femoris (epifisiolisis femoral proximal, el hecho de leerlo en nómina latina es un poco a mala leche pero no debería despistarnos). Debemos pensar en esta porque es la más frecuente y posible (respuesta 2 correcta). Las otras opciones no son imposibles pero si menos frecuentes y no nos lo plantearían así si quisieran que nos decantáramos por otra opción. Si fueran secuelas de displasia de cadera no tendría este inicio de 4 meses de evolución y la edad de aparición sería más temprana. Las complicaciones de la displasia son luxaciones y subluxaciones que pueden requerir cirugía y la necrosis avascular de cabeza (respuesta 5 falsa). La enfermedad de Perthes se da en niños más pequeños (4-9 años) con episodios de cojera y dolor en cadera y rodilla (respuesta 4 falsa). En un niño lo más típico sería una fractura a nivel de la fisis no a nivel del cuello femoral por lo que descartamos la 3. Para que nos planteáramos esta opción tendrían que habernos planteado un quiste óseo, algo que justificara una debilidad en la zona del cuello femoral. En cuanto a la artritis crónica juvenil es una opción de reuma rodeada de opciones de trauma. No nos hablan de factores reumatológicos en una analítica, ni de un cuadro poliarticular. Quizás podríamos pensar en esta porque se habla de dolor en rodilla derecha, pero este cuadro que nos presentan se limita al miembro inferior derecho no nos hablan ni de otras articulaciones ni de fiebre ni de otros síntomas acompañantes sistémicos por lo que no resulta una opción a valorar máxime con las otras opciones que nos presentan que serían más probables ante el cuadro que nos presentan (opción 1 falsa). Además, el dolor de rodilla de este caso se refiere a un dolor referido de la cadera, sin afectación de la rodilla.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6b8c4652b141', '043d10ce0b0cc39b5c521c926a587a16f3fb57e5', NULL, NULL, NULL, false, false, 'Cuidados Paliativos', 'Por tercera vez en los últimos 6 meses un hombre de 84 años de edad con demencia avanzada ingresa en un hospital por neumonía aspirativa. Ha perdido 9.5 kg en los últimos 10 meses. Tiene una úlcera por presión en el sacro. No se comunica verbalmente, no deambula y es dependiente para todas las actividades de la vida diaria. Su mujer cuida de él en casa y no quiere ingresar en una residencia. Un estudio de la deglución indica que se atraganta con todo tipo de consistencias de los alimentos. El médico del hospital sugiere alimentación por sonda. La "Voluntad Vital Anticipada" del paciente establece que su mujer es la representante que debe tomar las decisiones respecto a su atención médica y que él no quiere medidas extraordinarias para prolongar su vida incluyendo la nutrición artificial.', '¿Cuál de las siguientes es la recomendación más apropiada para este paciente?:', '[{"position": 1, "text": "Colocar una SNG permanente y dar el alta a una residencia con cuidados especializados."}, {"position": 2, "text": "Colocar una SNG a medio plazo y dar el alta a una residencia con cuidados especializados hasta que se curen las escaras."}, {"position": 3, "text": "Dar el alta a una residencia con cuidados especializados hasta que se curen las úlceras por presión."}, {"position": 4, "text": "Poner una sonda por gastrostomía y dar el alta a domicilio."}, {"position": 5, "text": "Dar el alta a domicilio con cuidados paliativos del área sanitaria."}]'::jsonb, 5, 5, 'definitiva', 'Quizás sea esta la menos científica de las preguntas MIR de este año, por cuanto su respuesta se basa en la interpretación de una ley, que además tiene carácter autonómico. Probablemente en el espíritu del examinador se quiera reflejar esta ley, en un caso repito extremo. Veamos, partiendo del artículo 11 de la Ley 41 /2002, de 14 de noviembre (1), básica reguladora de la autonomía del paciente y de derechos y obligaciones en materia de información y documentación clínica (B.O.E. Nº 274, de 15 de noviembre) de carácter nacional, en Castilla-La Mancha se legisla la Ley 6/2005, de 7 de julio (2), de Castilla-La Mancha, sobre la Declaración de Voluntades Anticipadas en materia de la propia salud. (D.O.C.M. Nº 141, de 15 de julio) y el Decreto 15/2006, de 21 de febrero (3), del Registro de Voluntades Anticipadas de Castilla-La Mancha (D.O.C.M. Nº 42, de 24 de febrero). En el resumen que publica la JCCM (4) dice textualmente: "La declaración de voluntades anticipadas (también conocida como documento de instrucciones previas o testamento vital) es la manifestación escrita de una persona capaz que, actuando libremente, expresa las instrucciones que deben tenerse en cuenta acerca de la asistencia sanitaria que desea recibir en situacio­nes que le impidan comunicar personalmente su voluntad, o sobre el destino de su cuerpo o sus órganos una vez producido el fallecimiento. En nuestra declaración de voluntades anticipadas podemos hacer referencia a: 1. La expresión de los valores personales, a fin de ayudar en su día a la interpretación del propio documento y orientar a los médicos en el momento de tomar decisiones clínicas. 2. Las instrucciones sobre los cuidados y tratamientos relacionados con nuestra salud que deseemos o no recibir. 3. Podemos nombrar un representante que actuará como interlocutor ante el médico responsable o el equipo sanitario para que se cumplan las instrucciones contenidas en la declaración. 4. También podemos incluir nuestra decisión respecto a la donación de órganos. En estos casos no se requerirá la autorización de la familia para la extracción o utilización de los órganos donados". Parece pues claro que la respuesta que se pretende es la 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-96d13e8b0730', '18726d60a16bace03a4c4877ed1ee21d687341a7', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 35 años que presenta hematuria tras infecciones respiratorias desde hace varios años, en la analítica de sangre presenta creatinina 1 mg/dl sin otras alteraciones y en la orina aparecen hematíes 50/campo siendo el 80% dismórficos, con proteinuria de 0,8 gramos en 24 horas.', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Nefropatía de cambios mínimos."}, {"position": 2, "text": "Glomerulonefritis membranosa."}, {"position": 3, "text": "Nefropatía IgA."}, {"position": 4, "text": "Glomerulonefritis proliferativa y difusa."}, {"position": 5, "text": "Glomeruloesclerosis focal y segmentaria primaria."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es: 3. Nefropatía IgA. Dado que la presentación clínica de esta nefropatía aparece de forma muy inespecífica, para identificar la enfermedad responsable debemos basarnos en su epidemiología. Al ser un varón joven, con historia de infecciones respiratorias previas, se establece una relación entre esas infecciones y la patología renal. Basándonos en ello pensamos en la Nefropatía IgA, que además de ser la glomerulonefritis más frecuente se presenta en la mayoría de los casos de la forma que se describe.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-deb32213795c', '129f0f01beaa207986468e14dbf02ec38d903469', NULL, NULL, NULL, false, false, 'Nefrología', 'Una enferma de 60 años diagnosticada de broncopatía crónica, diabetes mellitus, hipertensión arterial y tratada desde hace 4 meses con Omeprazol, Metformina, Salbutamol, Bromuro de Ipratropio y Enalapril 20 mg + Hidroclorotiazida 25 mg acude a su consulta por cansancio, disminución del apetito, con ligera disnea y tos ocasional, deposiciones variables, a veces blandas y sin síntomas urinarios. Unos análisis muestran leucocitos 10.000/mm³, Hto 35%, VCM 80, Glucosa 150 mg/dl, Urea 80 mg/dl, Creatinina 1,6 mg/dl, Sodio 133 mEq/l y Potasio 2,9 mEq/l.', '¿Cuál es la causa más probable de la hipopotasemia?', '[{"position": 1, "text": "Insuficiencia renal."}, {"position": 2, "text": "Hiponatremia."}, {"position": 3, "text": "Déficit de aporte de potasio."}, {"position": 4, "text": "Antihipertensivo."}, {"position": 5, "text": "Metformina."}]'::jsonb, 5, 4, 'definitiva', 'La respuesta correcta es: 4. Antihipertensivo. En particular la hidroclorotiazida, como tiazida, es el principal responsable de la hipopotasemia de este paciente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3f75f68bf1cf', '08ee841257fa2adf9b04d73199e2db4358c7b1f3', NULL, NULL, NULL, false, false, 'Nefrología', 'Un paciente de 52 años con enfermedad renal crónica estadio V, secundaria a Poliquistosis autosómica dominante, recibe un injerto renal de donante cadáver. Un hermano suyo de 34 años acude a visitarlo y refiere desconocer si padece la enfermedad por no haber acudido nunca a un médico desde la adolescencia.', '¿Qué actitud o prueba le parece más adecuada para recomendarle en ese momento?', '[{"position": 1, "text": "Estudio genético mutacional y de ligamiento."}, {"position": 2, "text": "Ecografía abdomino-pélvica."}, {"position": 3, "text": "Tomografía axial computerizada helicoidal con contraste iodado."}, {"position": 4, "text": "Resonancia nuclear magnética abdominal y cerebral."}, {"position": 5, "text": "Controles clínicos periódicos."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es: 2. Ecografía abdomino-pélvica. La ecografía abdomino-pélvica es sin duda la prueba más específica y sensible para el diagnóstico de poliquistosis renal y, sobre todo, la más barata para demostrar si el hermano del paciente ha heredado o no la poliquistosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6f1f070a6e89', 'f339864b020e12926b7c48f225a4ee91864670ea', NULL, NULL, NULL, false, false, 'Nefrología', 'Hombre de 66 años con antecedente de espondilitis anquilosante de larga evolución. Presenta proteinuria de 6 gramos al día con hipoalbuminemia y edemas. En el sedimento urinario no se detecta hematuria. Su creatinina plasmática es de 1,6 mg/dL y su filtrado glomerular de 45 mL/min. Glucemia 110 mg/dl. Su severa deformidad de columna vertebral dificulta realizar biopsia renal percutánea.', '¿Qué actitud inicial es la correcta?', '[{"position": 1, "text": "Iniciar corticoides por sospecha de enfermedad glomerular a cambios mínimos."}, {"position": 2, "text": "Tratarle con ciclofosfamida por sospechar glomerulopatía membranosa."}, {"position": 3, "text": "Biopsia de grasa subcutánea."}, {"position": 4, "text": "Iniciar diálisis."}, {"position": 5, "text": "Realizar una prueba de sobrecarga con glucosa para descartar nefropatía diabética."}]'::jsonb, 5, 3, 'definitiva', 'La respuesta correcta es: 3. Biopsia de grasa subcutánea. El lupus eritematoso, algunas vasculitis, la enfermedad de Goodpasture y otras enfermedades sistémicas (la espondilitis anquilosante es una de ellas) afectan al riñón y condicionan su pronóstico. La aparición de anomalías urinarias o deterioro renal de causa parenquimatosa son indicación de biopsia renal, incluso con rangos de proteinuria inferiores a los aceptados en las nefropatías primarias. La determinación de anticuerpos anti-MBG y ANCAS ayudan para el diagnóstico, pero no sustituyen a la biopsia renal, ya que carecen de valor pronóstico y no ayudan a planificar el tratamiento. En este caso, en el que nos dirigen a pensar que la biopsia renal no es posible, debemos relacionar EA con la insuficiencia renal. En la mayoría de los casos, la relación se establece por una Nefropatía IgA, que cursa con hematuria, síntoma que dice no existir en este caso. Una nada despreciable cantidad de pacientes con EA evolucionada es la amiloidosis, que cuadra también con la sintomatología del paciente. Por tanto, y dado que la amiloidosis se puede diagnosticar con una biopsia de grasa subcutánea, es la respuesta 3 la que debemos dar por válida.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-eed566df4108', '95f0e09975d2e20c34f4311f85caffb163c7bc72', NULL, NULL, NULL, false, false, 'Nefrología', 'Mujer de 58 años, peso 130 Kg, talla 155 cm, índice de masa corporal > 30 con hipertensión arterial leve, glucemia 108 mg/dL y ausencia de edemas en miembros inferiores. En analítica de sangre presenta Cr 2.0 mg/dl, Urea 86 mg/dl, Alb 3.8 g/1, Na 142 mEq/L, K 4 mEq/L. En analítica de orina: sedimento sin alteraciones y en orina de 24 h proteinuria de 6.3 gr/ 24 h.', '¿Cual de las siguientes entidades presentará con mayor probabilidad?', '[{"position": 1, "text": "Glomerulonefritis membranosa secundaria."}, {"position": 2, "text": "Glomerulonefritis focal y segmentaria."}, {"position": 3, "text": "Nefropatía IgA."}, {"position": 4, "text": "Glomerulonefritis rápidamente progresiva."}, {"position": 5, "text": "Nefropatía de cambios mínimos."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es: 2. Glomerulonefritis focal y segmentaria. Estamos ante una paciente con insuficiencia renal cuya manifestación es una proteinuria. Eso nos coloca en el cuadro de GN no proliferativas (membranosa, focal y segmentaria y cambios mínimos, descartando las otras dos). Si además tenemos en cuenta que nos está diciendo que la paciente era obesa, ligeramente hipertensa, lo más probable es que se trate de una Glomerulonefritis focal y segmentaria.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fb9f4e1b5292', 'b933554a15818c25c792c76a4f87cd872db22c54', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Mujer de 45 años que presenta hipertensión arterial (190/120 mmHg) acompañada de K 2,5 mEq/l. Se realiza ecografía abdominal que muestra estenosis de ambas arterias renales.', 'Indique que tratamiento está contraindicado:', '[{"position": 1, "text": "Enalapril."}, {"position": 2, "text": "Propanolol."}, {"position": 3, "text": "Amiloride."}, {"position": 4, "text": "Prazosin."}, {"position": 5, "text": "Amlodipino."}]'::jsonb, 5, 1, 'definitiva', 'Si las arterias renales están estenosadas, la sangre tiene dificultades para llegar a los riñones. Es decir, ambos están poco perfundidos y sólo pueden crear el gradiente de presión necesario para filtrar mediante la contracción de la arteriola eferente. Si administramos un IECA, provocaremos la relajación de esta arteriola y la caída de la tasa de filtrado glomerular. Y si ninguno de los dos riñones filtra, porque ambos tienen una estenosis arterial, tenemos un problema…', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-efaed3015875', 'f28dbc2b1f991307169ca5e74b21925b3902303c', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, '¿Qué exploración aconsejaría en primer lugar a un paciente de 82 años que refiere angina de esfuerzo y que a la auscultación presenta un soplo sistólico eyectivo de intensidad 3/6?', '[{"position": 1, "text": "Una prueba de esfuerzo."}, {"position": 2, "text": "Una coronariografia."}, {"position": 3, "text": "Un ecocardiograma de ejercicio."}, {"position": 4, "text": "Un TAC coronario."}, {"position": 5, "text": "Un ecocardiograma-Doppler."}]'::jsonb, 5, 5, 'definitiva', 'Soplo eyectivo, nuestra primera sospecha es una estenosis aórtica. La angina puede ser debida a la propia estenosis o a coronariopatía subyacente (probable, dada la edad). Y con ese dato, no podemos saber si la estenosis es severa. Por lo tanto, lo primero que tendremos que hacer será estudiar la valvulopatía: no queremos poner al paciente a correr o sobrecargarlo con dobuta y que tenga un síncope, ni hacerle un cate alegremente sin haber realizado antes otra prueba no invasiva. Y el cardioTC, en alguien de 80 años, nos va a decir lo que ya sabemos: que tiene calcio hasta en las cejas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-763c52254d15', '6f56175bc8ef0dab75c33227f0fc3ec61027f64f', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Mujer de 70 años, hipertensa y diabética que ha trabajado de dependienta toda su vida. Consulta por una lesión maleolar interna en la pierna derecha con intenso dolor durante todo el día que empeora durante la noche. A la exploración destacan cordones varicosos no complicados en ambas extremidades y pulsos femorales y poplíteos normales con ausencia de distales.', '¿Qué exploración deberíamos realizar en primer lugar?:', '[{"position": 1, "text": "Eco-doppler venoso de miembros inferiores."}, {"position": 2, "text": "Angiorresonancia de miembros inferiores."}, {"position": 3, "text": "Arteriografía."}, {"position": 4, "text": "Indice tobillo-brazo."}, {"position": 5, "text": "AngioTC."}]'::jsonb, 5, 4, 'definitiva', 'Al menos yo como medico de familia que soy, suelo empezar por las pruebas menos cruentas y con mayor coste-beneficio, y en el caso que nos describen, un Problema Isquemico en Miembros Inferiores es el Indice tobillo-brazo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c36669f78561', 'd36599e700cd7eee17a1f97cd310ea330ea1737a', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un paciente de 62 años de edad, portador de una bioprótesis de pericardio en posición mitral desde hace dos años. Ingresa de urgencia por presentar un síndrome coronario agudo. Dos días después y tras una evolución favorable, presenta de forma súbita un cuadro de insuficiencia cardiaca con edema agudo de pulmón.', 'Señale cuál es la opción diagnóstica en este caso entre las siguientes posibilidades:', '[{"position": 1, "text": "Insuficiencia mitral aguda posinfarto."}, {"position": 2, "text": "Aneurisma ventricular izquierdo."}, {"position": 3, "text": "Comunicación interventricular aguda."}, {"position": 4, "text": "Comunicación interauricular posinfarto."}, {"position": 5, "text": "Disfunción de la bioprótesis por probable endocarditis aguda."}]'::jsonb, 5, 3, 'definitiva', 'La válvula es biológica y, por lo general, no se cosen los velos a los músculos papilares, así que nos da igual lo que les pase. Un aneurisma ventricular deprime la FEVI, pero no te mete de repente en EAP. Por el contrario, una CIV aumenta bruscamente el flujo al lecho pulmonar, provocando edema de pulmón, y además es una de las complicaciones más frecuentes del IAM. La CIA isquémica… no niego que exista, pero ni siquiera aparece en las guías. Y para una endocarditis no harían falta tantas alforjas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-da28b4518d68', '6992bc5c7cbfbae71449a0419ad1628d5ed0d437', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un paciente con EPOC grave acude agudizado a Urgencias y presenta una gasometría arterial extraída con Fi02 del 31% a nivel del mar con una Pa02 de 86 mm Hg, PaC02 65 mm Hg, pH 7.13 y Bicarbonato 27 mmol/litro.', '¿Cuál de las siguientes afirmaciones es FALSA?', '[{"position": 1, "text": "El paciente está hiperventilando."}, {"position": 2, "text": "El gradiente alveolo arterial de oxígeno está elevado."}, {"position": 3, "text": "El paciente está en acidosis respiratoria."}, {"position": 4, "text": "El nivel de bicarbonato es normal."}, {"position": 5, "text": "Se debería considerar iniciar ventilación mecánica."}]'::jsonb, 5, 1, 'definitiva', 'La gasometría demuestra una acidosis respiratoria aguda, por incremento en la PCO2 de poco tiempo de evolución dado que el riñón aun no ha tenido tiempo de retener bicarbonatos (cifra de bicarbonato en limite alto de la normalidad). El paciente no esta hiperventilando sino hipoventilando dado que la PCO2 esta elevada. El gradiente alvéolo arterial de oxigeno esta alterado dado que el paciente presenta una PaO2 normal, pero porque esta con una FiO2 alta. Si estuviera sin oxigeno, estaría hipoxémico. La acidosis respiratoria por debajo de 7.20 es un motivo para considerar la ventilación mecánica no invasiva de forma aguda y en principio temporal en un paciente con EPOC grave.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-54286795be6d', 'e01624f5b78a0222719a80c44d2c0c1490bbcddd', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Acude a revisión a la consulta de alergia una mujer de 53 años de edad con asma bronquial. Refiere repetidas agudizaciones con clínica nocturna, utilización frecuente de medicación de rescate y disnea de esfuerzo al caminar en llano. Tiene una espirometría que muestra un cociente prebroncodilatador del FEV1/FVC del 60% y un FEV1 del 55%. Las pruebas cutáneas son positivas para ácaros y la IgE total de 150 UI/ml. La paciente está siendo tratada con una combinación de salmeterol/budesonida a dosis altas (50/500 mg: 2 inhalaciones dos veces al día), prednisona oral de mantenimiento (10 mgldía) y teofilina.', 'De las siguientes opciones, ¿cuál es la actitud terapéutica más aconsejable?', '[{"position": 1, "text": "Añadir sulfato de magnesio."}, {"position": 2, "text": "Aumentar la dosis de prednisona a 30 mg/día."}, {"position": 3, "text": "Añadir omalizumab."}, {"position": 4, "text": "Pautar tratamiento nebulizado en el domicilio."}, {"position": 5, "text": "Cambiar a una combinación con dosis altas de budesonida y formoterol."}]'::jsonb, 5, 3, 'definitiva', 'La indicación de omalizumab en una paciente como la referida, es una indicación correcta, aunque dentro del asma grave de dificil control, hay otras medidas previas que no se contemplan y que hay que tener siempre presentes antes de recurrir a este tratamiento. Es preceptivo asegurar en primer lugar que es verdaderamente un asma y no otra enfermedad que simule asma, segundo que no tenga complicaciones que empeoren la evolución como podría ser la presencia de reflujo gastroesofágico, bronquiectasias, presencia de gérmenes oportunistas dado el tratamiento crónico con esteroides, etc; y en tercer lugar hay que confirmar que la paciente cumple los tratamientos de forma correcta, sobre todo el tratamiento inhalado, etc. Una vez chequeado todo lo anterior, sería el momento de iniciar un tratamiento de prueba con omalizumab.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-834ba0369b23', 'a96d8e9acc6d7facae95c7f33344b8fca70acedf', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Un hombre de 67 años consulta por disnea de moderados esfuerzos de aparición progresiva en los últimos años. Tiene expectoración blanquecina diaria y a veces ruidos respiratorios, especialmente en invierno con las infecciones respiratorias. Ha sido fumador de unos 20 cigarrillos diarios durante los últimos 45 años. En la exploración se encuentra eupneico, normocoloreado, con una saturación de oxígeno del 94%, y presenta disminución generalizada del murmullo vesicular en la auscultación torácica como únicos hallazgos de interés. La radiografía de tórax muestra una silueta cardiaca alargada, con signos de hiperinsuflación o atrapamiento aéreo pulmonar, sin otras alteraciones. Se realiza una espirometría el siguiente resultado: FVC 84%, FEV1 58%, FEV1/FVC 61%, sin cambios tras broncodilatador.', 'Entre los señalados, indique el tratamiento más adecuado para este paciente:', '[{"position": 1, "text": "Corticoide inhalado diario."}, {"position": 2, "text": "Oxigenoterapia domiciliaria con fuente portátil de oxigeno para deambulación."}, {"position": 3, "text": "Antagonista de leucotrienos por vía oral."}, {"position": 4, "text": "Corticoide oral durante tres meses."}, {"position": 5, "text": "Tiotropio inhalado."}]'::jsonb, 5, 5, 'definitiva', 'En un paciente con una EPOC poco sintomático que se podría clasificar probablemente como GOLD 2, el tratamiento de inicio puede ser tanto con tiotropio inhalado como con un beta dos de larga duración. Por lo tanto no hay duda en la respuesta correcta.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d2934b8c630b', 'b76417894e129db0c607cccea7dbddd5c6aec515', NULL, NULL, NULL, false, false, 'Hematología', 'A una mujer de 30 años, asintomática, en un examen rutinario se le detecta anemia. En la exploración física se aprecia ictericia conjuntival y esplenomegalia. La paciente refiere historia familiar de litiasis biliar en edades tempranas.', 'Todo ello sugiere el diagnóstico más probable de:', '[{"position": 1, "text": "Déficit de glucosa 6-fosfato deshidrogenasa."}, {"position": 2, "text": "Talasemia minor."}, {"position": 3, "text": "Deficiencia de vitamina Bl2 y/o ácido fólico."}, {"position": 4, "text": "Déficit familiar de piruvatokinasa."}, {"position": 5, "text": "Esferocitosis hereditaria."}]'::jsonb, 5, 5, 'definitiva', 'Seguramente se os haya ido la vista a la respuesta 5, esferocitosis hereditaria, asociada a litiasis biliar a temprana edad. Exacto, ésa es la correcta. En el enunciado no han parado de dar pistas: ictericia conjuntival, esplenomegalia e historia familiar de litiasis biliar a temperana edad. Ha llegado a los 30 años sin sufrir una crisis hemolítica, sin sufrir ningún síntoma. No han hablado de microcitosis o macrocitosis para orientar a una talasemia minor o un déficit de B12 y/o fólico. Ni de crisis hemolítica asociada al consumo de fármacos, infecciones o ingesta de habas o guisantes. No han dado pistas para pararse a pensar en otras posibilidades.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5d46c5cf2418', '92f4c6798fc45bea31d3cc428873431efc63158e', NULL, NULL, NULL, false, false, 'Hematología', 'Niño de 18 meses de edad, con calendario vacu­nal completo hasta la fecha, que consulta en el Servicio de urgencias por tumefacción de la rodilla derecha tras jugar en el parque, sin traumatismo evidente. En la anamnesis dirigida, la madre refiere que un tío de ella tenía proble­ mas similares. La exploración ecográfica es compatible con hemartros y en la analítica que se realiza sólo destaca un alargamiento del APTT de 52″ (normal 25-35″).', '¿Cuál es la hipótesis diagnóstica más probable?', '[{"position": 1, "text": "Síndrome de Marfan."}, {"position": 2, "text": "Enfermedad de Von Willebrand."}, {"position": 3, "text": "Enfermedad de Ehlers-Danlos."}, {"position": 4, "text": "Hemofilia A."}, {"position": 5, "text": "Enfermedad de Bemard-Soulier."}]'::jsonb, 5, 4, 'definitiva', 'En esta pregunta tampoco paran de soltar pistas para lanzarnos de cabeza al diagnóstico correcto. Repasemos: niño pequeño que sin traumatismo claro sufre un hemartros. Un tío suyo tenía problemas similares, por lo que sospechamos enfermedad hereditaria. El TTPA, que evalúa la vía intrínseca de la coagulación (en la que participan los factores V, VIII, IX, X, XI y XII) está alargado. Problema hereditario de coagulación. Descartamos así la respuestas 1, 2 y 5. Nos quedan la enfermedad de von Willebrand y la hemofilia A. Considero que la correcta es la 4, hemofilia A, ya que el patrón de herencia es ligado a X y su manifestación clínica principal son los hematomas de tejidos blandos y los hemartros espontáneos, sin traumatismo aparente, mientras que la enfermedad de von Willebrand se caracteriza por hemorragia tras cirugía o traumatismo y es característico un tiempo de sangría prolongado con una cifra de plaquetas normales (datos que no nombra el enunciado).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-14617732a8c7', '8264582fae15c1da0efcf64e43b0d6e84f148e66', NULL, NULL, NULL, false, false, 'Endocrinología', 'Diabético tipo 1 que acude a Urgencias por disnea y malestar general. En la analítica presenta glucemia 450 mg/dl, Na 142 mEq/l, K 4 mEq/l, pH 7.15, bicarbonato 12 mmol/l.', '¿Qué tratamiento NO estaría indicado?', '[{"position": 1, "text": "Suero fisiológico iv rápido."}, {"position": 2, "text": "Suero glucosado 5% iv cuando la glucemia sea menor de 250 mg/dl."}, {"position": 3, "text": "Insulina rápida humana iv."}, {"position": 4, "text": "Cloruro potásico 100 mEq / día diluido en los sueros."}, {"position": 5, "text": "Bicarbonato sódico 1M 100 cc iv en 30 minutos."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta fácil ya que el tratamiento de la cetoacidosis diabética es un tema muy repetido en el MIR. El bicarbonato está indicado con pH < 7.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9a35f6ff4ef7', '6097e9962670e6dd9ef9cee5a64be375caf4f584', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una mujer de 76 años nos consulta porque está preocupada por su riesgo de sufrir un accidente cerebrovascular ya que su madre falleció por esta causa hace un año. Está diagnosticada de hipertensión arterial y diabetes mellitus tipo 2 por lo que sigue tratamiento con glipizida, aspirina, enalapril y atorvastatina. Fuma 20 cigarrillos al día y lleva una vida sedentaria. A la exploración se detecta una presión arterial de 150/80 mm de Hg. En la analítica destaca una hemoglobina A1C de 8% y un LDL colesterol de 110 mg/dl.', '¿Cuál de las siguientes acciones se asocia con una mayor reducción del riesgo de sufrir un accidente cerebrovascular?', '[{"position": 1, "text": "Conseguir un óptimo control de la presión arterial."}, {"position": 2, "text": "Conseguir unos niveles óptimos de hemoglobina A1C."}, {"position": 3, "text": "Añadir al tratamiento un antioxidante."}, {"position": 4, "text": "Abandonar el tabaco."}, {"position": 5, "text": "Conseguir unos niveles de LDL inferiores a 100 mg/dl."}]'::jsonb, 5, 1, 'definitiva', 'El factor cardiovascular más influyente para el ictus en las mujeres mayores de 70 años es la tensión arterial.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-da4f45d642fc', '4a1121c9005eede4b73a16191f2c3979f258291a', NULL, NULL, NULL, false, false, 'Endocrinología', 'Remiten a su consulta a un paciente con obesidad (índice de masa corporal 38). En la historia clínica el paciente refiere que presenta obesidad desde los 17 años (en la actualidad tienen 36 años), habiendo realizado múltiples dietas con pérdidas ponderales que oscilan entre 5 y 10 kg pero que posteriormente ha recuperado el peso. En la actualidad el paciente realiza una dieta de 1500 Kcal (auto administrada y no restringida en grasas) con un buen seguimiento de dicha dieta, realizando una hora de ejercicio aeróbico durante 4 días a la semana. Ha perdido 3 kg pero precisa una pérdida añadida de 7 kg más.', 'Ante la posibilidad de añadir un fármaco frente a la obesidad, ¿cuál utilizaría para disminuir la absorción de grasas?:', '[{"position": 1, "text": "Orlistat."}, {"position": 2, "text": "Topiramato."}, {"position": 3, "text": "Sibutramina."}, {"position": 4, "text": "Liraglutida."}, {"position": 5, "text": "Metformina."}]'::jsonb, 5, 1, 'definitiva', 'El Orlistat actúa disminuyendo la absorción de grasas; actualmente es el único fármaco aprobado para el uso de la obesidad.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-02159497bae5', 'e2796efeb31a6c3646744fa90ddce0870ad2279c', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un paciente de 57 años tuvo un infarto agudo de miocardio y presenta en la analítica colesterol de 312 mg/dl, LDL 241 mg/dl, HDL 29 y TG normales. Fumador 30 cig/día, no obesidad, presión arterial de 145/90 mm Hg y no tenía diabetes. Interrogado sobre antecedentes familiares refirió que un tío por línea materna falleció de forma brusca a los 53 años.', '¿Con qué respuesta está más de acuerdo?', '[{"position": 1, "text": "Tratar con estatinas hasta que se normalice el colesterol y recomendar hábito de vida saludable (dieta, ejercicio y no fumar)."}, {"position": 2, "text": "Descartar hipotiroidismo u otra enfermedad sistémica, recomendar hábito de vida saludable y tratar con fibratos para normalizar el colesterol."}, {"position": 3, "text": "No precisa descartar dislipemia secundaria por ser infrecuente. Se debe realizar perfil lipídico familiar."}, {"position": 4, "text": "Descartar dislipemia secundaria, tratar con resinas (resincolestiramina) y fibratos y re-comendar hábito de vida saludable. Prohibir alcohol."}, {"position": 5, "text": "Descartar dislipemia secundaria, solicitar estudio familiar y tratar con estatinas para mantener un buen perfil lipídico. Control de otros factores de riesgo."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta de un tema de moda en los últimos años: las dislipemia; yo la contestaría por descarte. El tratamiento de la hipercolesterolemia son las estatinas por lo que descartamos la respuesta 2 y 4. La estatina en un paciente con enfermedad cardiovascular (como es un IAM) es un tratamiento de por vida (descartamos la 1) ya que no se toma hasta que se normalice los niveles de LDL. Entre la 3 y la 5, la 5 es más completa ya que incluye el tratamiento y el control de otros factores de riesgo. Descartar una dislipemia secundaria es fácil con la historia clínica del paciente y una analítica con función tiroidea.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b09b8dad7e55', 'c03e53060be50513264e5f7cdb78dba527c48086', NULL, NULL, NULL, false, false, 'Dermatología', NULL, 'Si un paciente refiere tener desde hace meses aumento del tamaño de la lengua, sin otras alteraciones de la misma provocando que se muerda constantemente, en qué enfermedad pensaría de las siguientes:', '[{"position": 1, "text": "Parálisis del hipogloso."}, {"position": 2, "text": "Hipertiroidismo."}, {"position": 3, "text": "Mastocitosis."}, {"position": 4, "text": "Amiloidosis."}, {"position": 5, "text": "Granuloma facial."}]'::jsonb, 5, 4, 'definitiva', 'Pregunta compartida con ORL. La Amiloidosis es un depósito localizado o sistémico de proteínas fibrilares. Puede ser primaria o secundaria. Los órganos más frecuentemente afectados, son los riñones y el corazón. En ocasiones aparecen depósitos de amiloide en la lengua que pueden producir macroglosia.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b384f6eb7250', '61b372698e65b821e1cb16e923f4f62b528af13b', NULL, NULL, NULL, false, false, 'Pediatría', 'Los padres de un lactante de 5 meses acuden porque su hijo, que asiste a guardería, presenta desde hace 3 días, coincidiendo con una infección respiratoria de vías altas, heces líquidas en número de 4 al día, algún vómito alimentario ocasional y temperatura axilar de 38,3ºC. Es alimentado con lactancia mixta. A la exploración el lactante tiene buen estado general, está bien nutrido e hidratado y su respiración es eupneica; su peso es de 4.730g y ha descendido 70 g respecto al de la semana anterior. El abdomen están blando y depresible, sin masas ni megalias, y la fontanela, normotensa. Salvo la presencia de rinorrea acuosa, el resto de exploración por órganos y aparatos es normal.', 'De las siguientes afirmaciones, señale la respuesta que considera CORRECTA:', '[{"position": 1, "text": "Se debe realizar estimación de las pérdidas, recomendar un ayuno de 4 horas y rehidratar durante este tiempo con solución rehidratante oral."}, {"position": 2, "text": "Es aconsejable la introducción de cereales de arroz por su efecto astringente."}, {"position": 3, "text": "Se debe realizar coprocultivo tan pronto como sea posible para excluir un origen bacteriano."}, {"position": 4, "text": "Se debe recomendar el empleo de fórmula sin lactosa."}, {"position": 5, "text": "Se ha de aconsejar reponer las pérdidas tras cada deposición, con solución rehidratante oral, y continuar con su alimentación habitual."}]'::jsonb, 5, 5, 'definitiva', 'El bebé no está deshidratado y tiene un buen estado general. Se trata de evitar la deshidratación reponiendo lo que se va perdiendo, evitando en lo posible cambios drásticos en sus hábitos alimentarios. El resto de respuestas toca muchos de los “mitos” y costumbres entorno a la gastroenteritis. Tampoco hay datos de intolerancia a lactosa (irritación perianal, heces espumosas y ácidas, etc) que aconsejen una leche sin lactosa.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-4fbe4573f358', '4c2851c4932ecf51fa03ffb883076ece467e71ba', NULL, NULL, NULL, false, false, 'Pediatría', NULL, 'En un lactante de 3 meses todas las manifestaciones clínicas reseñadas a continuación obligarían a descartar una fibrosis quística, EXCEPTO:', '[{"position": 1, "text": "Retraso en la evacuación de meconio."}, {"position": 2, "text": "Sabor salado de la piel."}, {"position": 3, "text": "Aislamiento de secreciones de Pseudomonas aeruginosa."}, {"position": 4, "text": "Deterioro/detención de la curva ponderal."}, {"position": 5, "text": "Deshidratación hipernatrémica."}]'::jsonb, 5, 5, 'definitiva', 'La deshidratación puede deberse a diarreas de otras etiologías. Me ha generado dudas la respuesta 3 ya que no especifica de qué secreciones de trata. Tenemos que sobreentender que el crecimiento por Pseudomona aeruginosa es en el cultivo de secreciones bronquiales. Porque claramente la indicación para realizar un cloro en sudor (para descartar FQP) son las deshidrataciones HIPOnatrémicas y no las hipernatrémicas como dice la respuesta.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-04dc1cb8ba2a', '3b07d082ceb89a4edc89fc68862416c1d25b0576', NULL, NULL, NULL, false, false, 'Pediatría', 'Niña de 3 años, procedente de Bangladesh, que consulta por episodios febriles intermitentes de 3 semanas de evolución, asociados a debilidad y pérdida de apetito. A la exploración física llama la atención esplenomegalia marcada y palidez mucocutánea. En las pruebas complementarias destaca: hemoglobina 8,5 mg/dl, hematocrito 26%, VCM 86 fL, HCM 29 pg, leucocitos 2800/mL con 300 neutrófilos /ml, plaquetas 54000/ml, GOT 85 U/l, GPT92 U/l e hipergammaglobulinemia policlonal en proteinograma de suero.', 'Señale el diagnóstico más probable con los datos disponibles hasta este momento:', '[{"position": 1, "text": "Leucemia linfoblástica aguda."}, {"position": 2, "text": "Linfoma de Burkitt."}, {"position": 3, "text": "Leishmaniasis visceral."}, {"position": 4, "text": "Tuberculosis miliar."}, {"position": 5, "text": "Malaria crónica."}]'::jsonb, 5, 3, 'definitiva', 'Los datos como la pancitopenia y la hipergammaglobulinemia son muy característicos del kala-azar. También orienta a este diagnóstico la procedencia de la niña, aunque es una enfermedad que se presenta también en el área mediterránea. Ante este cuadro es importante tener presente en el diagnóstico diferencial también la posibilidad de leucosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6a9feb110579', '9f23392bdb163ff8cc5888f120b0dbf8613dc691', NULL, NULL, NULL, false, false, 'Pediatría', 'Acude de urgencia al centro de salud, un niño de 15 meses de edad, que durante la cena, tras ingerir un bocado de tortilla, presenta de forma súbita: enrojecimiento facial de predominio perioral, lesiones habonosas en tronco y extremidades y tos. A su llegada al centro se encuentra consciente y se objetiva, además de lo descrito: tiraje supraesternal, rinorrea acuosa abundante, hipoventilación bilateral sin sibilancias y relleno capilar inferior a 2 segundos.', 'De las siguientes afirmaciones, señale la respuesta CORRECTA:', '[{"position": 1, "text": "Lo prioritario es canalizar una vía venosa."}, {"position": 2, "text": "La metilprednisolona por vía intramuscular es el tratamiento de elección."}, {"position": 3, "text": "Se trata de un cuadro de urticaria asociado a asma, y debe ser tratado con antihistamínicos y broncodilatadores inhalados."}, {"position": 4, "text": "Se debe recomendar a los padres su traslado a un Servicio de Urgencias hospitalario."}, {"position": 5, "text": "Se debe administrar sin más dilación, adrenalina por vía intramuscular."}]'::jsonb, 5, 5, 'definitiva', 'Está describiendo una anafilaxia por huevo, cuadro potencialmente mortal. El tratamiento de elección es la adrenalina intramuscular, y efectivamente, sin perder demasiado tiempo. Lo primero es la adrenalina INTRAMUSCULAR ¡YA! La vía venosa, corticoides, antihistamínicos, etc vendrán después.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5e168f363445', '32d5b71f0beb73797744c692cdae4a26acb6576d', NULL, NULL, NULL, false, false, 'Pediatría', 'Niño de 4 años de edad que consulta por aparición a lo largo de los últimos tres días, de lesiones cutáneas en piernas y glúteos. Sus padres referían que su pediatra le había diagnosticado una infección de vías respiratorias superiores 10 días antes. En las últimas 12 horas presenta dolor abdominal intenso tipo cólico, y ha realizado dos deposiciones diarreicas. Afebril. No pérdida de peso. A la exploración presenta numerosas petequias y lesiones purpúricas palpables de predominio en glúteos y extremidades inferiores. Buen estado general aunque tiene dolor abdominal intenso, La palpación abdominal es difícil de valorar por dolor difuso. No visceromegalias. No otros hallazgos de interés a la exploración.', '¿Cuál de los siguientes datos NO apoya su sospecha diagnóstica?', '[{"position": 1, "text": "Artritis de rodillas y tobillos."}, {"position": 2, "text": "Hematuria."}, {"position": 3, "text": "Plaquetopenia."}, {"position": 4, "text": "Sangre oculta en heces."}, {"position": 5, "text": "Edema escrotal."}]'::jsonb, 5, 3, 'definitiva', 'Está describiendo una púrpura de Schönlein-Henoch que es un fenómeno vasculítico, de forma que las lesiones no son debidas a plaquetopenia. El edema escrotal (A veces incluso torsión de cápside de Morgani del testículo) no es excepcional en varones con S Schönlein-Henoch.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b7213c8a5a83', 'a4ac8a6780bfa56fb14c9c28920a396013f7a14e', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Niño de 10 años con episodios breves de distracciones (< 1 minuto) en los que no responde a llamadas y parpadea. Un EEG muestra descargas de punta-onda a 3 ciclos por segundo.', 'El tratamiento electivo de primera línea lo haría con:', '[{"position": 1, "text": "Valproato."}, {"position": 2, "text": "Carbamacepina."}, {"position": 3, "text": "Fenitoína."}, {"position": 4, "text": "Gabapentina."}, {"position": 5, "text": "Clonazepam."}]'::jsonb, 5, 1, 'definitiva', 'Las ausencias se comportan como breves episodios de pérdida brusca del nivel de conciencia sin alteración del control postural; característicamente duran segundos y pueden repetirse muchas veces al día, suelen acompañarse de pequeños signos motores bilaterales (parpadeo, masticación) y se recupera la conciencia de forma igualmente brusca, sin confusión posterior ni memoria del episodio (MIR 03-04, 248; MIR 97-98, 51). La edad de comienzo suele estar entre los 4 años y el inicio de la adolescencia, siendo la causa más frecuente de crisis en este rango de edad. Los hallazgos en el EEG son típicamente descargas generalizadas y simétricas de punta-onda a 3 Hz (MIR 99-00F, 67) coincidiendo con las crisis, aunque en el EEG interictal existen más períodos de actividad anormal que los visibles clínicamente. Los fármacos más adecuados para el tratamiento de las ausencias son el Valproato y la Etosuximida (Manual CTO).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f4503ad7c400', 'dd33129137b4fbfa34e1dd419b8b746ff8e715ea', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un hombre de 77 años con antecedentes de Diabetes Mellitus tipo 2, fue diagnosticado hace 2 años de deterioro cognitivo leve. En aquel momento se practicó un Minimental (Folstein) 28/30, Test de Yesavage abreviado 14/15, una analítica con TSH y factores de maduración normales junto con serologías de LUES y VIH negativas y una resonancia magnética (RM) que mostraba atrofia cortical difusa predominante en zona posterior. El paciente acude acompañado de su esposa que refiere evolución progresiva y lenta del deterioro de la memoria (p.e. en ocasiones se ha confundido con las dosis de insulina). No existen alucinaciones ni trastorno conductual. El Minimental actual es de 24/30 y el Test de Yesavage 14/15, no existe focalidad neurológica, temblor ni trastornos del tono o de la marcha a la exploración física. Hace 2 meses acudió a Urgencias tras un traumatismo craneo­encefálico leve por caida accidental (la única en 2 años) y se realizó una tomografía que no aportaba nueva información respecto a la RM previa.', '¿Cuál es el diagnóstico más probable en este paciente?', '[{"position": 1, "text": "Demencia frontotemporal."}, {"position": 2, "text": "Enfermedad de Alzheimer."}, {"position": 3, "text": "Demencia vascular."}, {"position": 4, "text": "Enfermedad por cuerpos de Lewy."}, {"position": 5, "text": "Enfermedad de Creutzfeldt-Jakob."}]'::jsonb, 5, 2, 'definitiva', 'Este caso describe una Enfermedad de Alzheimer con comienzo insidioso de problemas de memoria a corto plazo. Clínicamente se puede distinguir de otras opciones por ausencia de problemas conductuales (típicos de la Demencia frontotemporal) y alucinaciones (precoces en la Enfermedad por cuerpos de Lewy). La demencia vascular se diagnostica por criterios que incluyen déficit de memoria y en otras dos áreas cognitivas con deterioro funcional consiguiente, pero enfermedad vascular cerebral según datos de la historia, de la exploración y/o de las pruebas de neuroimagen, las cuales no se indican en el caso. La enfermedad de Creutzfeldt-Jacob es sobretodo de rápida evolución y suele presentarse con otra clínica, exploración neurológica anormal y alteraciones en la RM.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c7a7350f1184', '1ebca9b04cb28850051aa3781c4199d21f11d4e1', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'En un paciente que se presenta en la segunda década de su vida con un cuadro progresivo de parkinsonismo, temblor, distonía y alteración de conducta, usted debe siempre realizar un estudio para descartar la presencia de una enfermedad cuyo tratamiento adecuado puede mejorar los síntomas neurológicos y detener el curso clínico.', '¿De qué enfermedad se trata?', '[{"position": 1, "text": "Enfermedad de Huntington."}, {"position": 2, "text": "Enfermedad de Wilson."}, {"position": 3, "text": "Síndrome de Tourette."}, {"position": 4, "text": "Corea de Sydenham."}, {"position": 5, "text": "Enfermedad de Parkinson de inicio juvenil."}]'::jsonb, 5, 2, 'definitiva', 'La clave en la pregunta es la de «detener el curso clínico», ya que la enfermedad de Hungtinton, el Tourette y la enfermedad de Parkinson no disponen de tratamientos que puedan detener el curso clínico. La Corea de Sydenham es típica de niños más pequeños con el antecedente de infección estreptocócica y la resolución suele ser espontánea. Por otra parte, en los casos clínicos se recomienda descartar la enfermedad de Wilson en pacientes jóvenes con trastornos del movimiento y neuropsiquiátricos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9987aee778b2', 'b1d518b35e9e9170491f9c318016f385904e0bbb', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Una mujer de 32 años ha viajado a Cuba de donde ha llegado hace tres días. Al día siguiente de su regreso acude a su médico de cabecera por fiebre elevada, artromialgias intensas y cefalea que le había comenzado antes de iniciar el viaje de regreso y le prescribe paracetamol. Tres días más tarde y sin haber experimentado mejoría presenta por la mañana un exantema maculo-papuloso pruriginoso generalizado que es más intenso en miembros inferiores en donde evoluciona a la formación de petequias por lo que acude a Urgencias. En las EC no se aprecian datos relevantes excepto las plaquetas 75000/mm3 (htco 36%, leucocitos 4100 79% neutrófilos).', '¿Cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Mononuclesis infecciosa."}, {"position": 2, "text": "Exantema alérgico."}, {"position": 3, "text": "Malaria por P. falciparum."}, {"position": 4, "text": "Fiebre tifoidea."}, {"position": 5, "text": "Dengue."}]'::jsonb, 5, 5, 'definitiva', 'En este caso creo que la respuesta correcta es la 5. La 1 no debe ser ya que aunque la clínica es sugestiva, no presenta linfocitosis. Tampoco parece un exantema alérgico por la clínica. Y desde luego no reúne síntomas ni signos clínicos compatibles con malaria o fiebre tifoidea. Lo que orienta al dengue, además de la clínica es la plaquetopenia.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-65bf7957b0fb', 'b4341c3fb440a98c4f55378ce01db7c009110238', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Hombre de 43 años sin enfermedades de interés que acude a Urgencias por 4 deposiciones melénicas en las últimas 12 horas. Refiere toma de AINEs en días previos. En la exploración física, estaca palidez de piel y mucosas. TA 95/65 y FC 110 lpm. El abdomen no es doloroso y en el tacto rectal se demuestran deposiciones melénicas. En la analítica se encuentra una cifra de Hb de 8,1 gr/dl. Tras infusión de salino y comenzar la transfusión de concentrado de hematíes la TA es 120/85 y la FC 90 lpm. Se realiza endoscopia en la que se encuentran coágulos en el estómago y una úlcera de 2 cm en el antro gástrico con fondo de fibrina y una pequeña protuberancia blanco grisácea de 3 mm en el centro de la úlcera (trombo plaquetario vaso visible).', '¿qué actitud le parece la más correcta?', '[{"position": 1, "text": "Dado que el paciente es joven, sin enfermedades asociadas y la úlcera ha dejado de sangrar, puede ser dado de alta precozmente con tratamiento con un IBP y erradicación de H. Pylori."}, {"position": 2, "text": "Retirar el endoscopio, colocar sonda nasogástrica para aspiración continua e iniciar tratamiento con un IBP y somatostatina."}, {"position": 3, "text": "Tomar biopsia para la detección de H. Pylori, retirar el endoscopio procurando no desprender el trombo plaquetario y continuar tratamiento farmacológico con IBP i.v."}, {"position": 4, "text": "Consulta al servicio de Cirugía para considerar tratamiento quirúrgico urgente."}, {"position": 5, "text": "Tratamiento endoscópico mediante inyección de adrenalina en la úlcera y colocación de clips (grapas metálicas) seguido de la administración i.v. de IBP."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta sobre HDA no varicosa. Paciente joven, sin antecedentes que tras toma de AINEs presenta sangrado con inestabilidad hemodinámica que precisa transfusión. La 1 respuesta no está acorde con lo dicho, es un paciente inestable que ha sangrado bastante, que presenta una úlcera Forrest IIa que presenta un riesgo de resangrado alto. La 2 habla de somatostatina, que se utiliza para el sangrado por hipertensión portal. La 4 sólo se planteará si no se controla el sangrado endoscópicamente. Entre la 3 y la 5, al tener un alto riesgo de sangrado se recomienda realizar terapéutica endoscópica a poder ser con 2 técnicas por lo que la correcta sería la 5.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
INSERT INTO public.mir_questions (source_id, fingerprint, exam_year, exam_version, question_number, is_reserve, is_annulled, specialty, clinical_case, question, options, n_options, correct_option, answer_key_version, explanation, has_image, image_path, needs_review, review_reason, provenance, source_url)
VALUES
('casimedicos-1233751e9dd2', '70f156d295c9e6ec8d85e823ff7ae402bb28b353', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Ante un paciente que presenta problemas para la comprensión del lenguaje tanto hablado como escrito, incapacidad para denominar objetos y repetir palabras que se le dicen, habla fluída incomprensible con parafasias semánticas y fonémicas.', 'Se trata de una:', '[{"position": 1, "text": "Afasia global."}, {"position": 2, "text": "Afasia de Wernicke."}, {"position": 3, "text": "Afasia de Broca."}, {"position": 4, "text": "Afasia transcortical sensitiva."}, {"position": 5, "text": "Afasia transcortical motora."}]'::jsonb, 5, 2, 'definitiva', 'Las transcorticales tienen la repetición conservada. La de Broca tiene la comprensión conservada y ausencia de habla fluída. La afasia de Wernicke se caracteriza por una habla fluida (incluso en exceso) con parafasias y problemas para la comprensión, nominación y repetición.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c1efebce6d6d', '8f755d411e03224feb9e2e8a5ccc71ddbb168679', NULL, NULL, NULL, false, false, 'Cirugía General', 'Paciente con pancreatitis aguda. En Tomografía Axial Computerizada (TAC) realizada a las 72 horas de ingreso se aprecia una necrosis del 50% del páncreas. A la 3ª semana de ingreso el paciente comienza con fiebre elevada y leucocitosis. Se solicita radiografía de tórax urgente y sedimento urinario, siendo ambos normales.', 'Señale el siguiente paso a seguir:', '[{"position": 1, "text": "Punción aspiración con aguja fina de necrosis pancreática guiada por ecografía o TAC."}, {"position": 2, "text": "Aspirado broncoalveolar, cultivo de orina y hemocultivos."}, {"position": 3, "text": "Resonancia Magnética Nuclear abdominal."}, {"position": 4, "text": "Colecistectomía urgente."}, {"position": 5, "text": "Ecoendoscopia con punción de la necrosis."}]'::jsonb, 5, 1, 'definitiva', 'aunque las últimas recomendaciones sobre el manejo de la pancreatitis aguda grave desaconsejan la PAAF por el riesgo de infección del necrosis estéril. El manejo actual se rige por el tratamiento escalonado. En la situación descrita en la pregunta el tratamiento actual es comenzar con antibióticos y valorar respuesta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-ca7514c169e7', '3fa20e24f7e06bb1663ea63cc51dbc5d6534612d', NULL, NULL, NULL, false, false, 'Cirugía General', 'Mujer de 55 años, intervenida de apendicitis hace 24 años, que acude porque estando previamente bien, ha comenzado con vómitos de repetición tras desayunar, hace unas 12 horas, asociado a distensión abdominal. Ha presentado una deposición diarreica a las pocas horas de comenzar el cuadro. A la exploración se evidencia distensión abdominal, timpanismo y aumento de ruidos intestinales, pero no irritación peritoneal. La analítica no presenta alteraciones. En la radiografía de abdomen aparece dilatación de asas de intestino delgado, sin poder objetivarse gas en la ampolla rectal.', 'Respecto a este caso es cierto que:', '[{"position": 1, "text": "Se trata de un cuadro de obstrucción intestinal por bridas que requiere laparotomía de urgencia."}, {"position": 2, "text": "Lo más probable es que nos encontremos ante un caso de obstrucción a nivel de intestino grueso."}, {"position": 3, "text": "El hecho de que la paciente haya presentado una deposición diarreica nos permite excluir el diagnóstico de obstrucción intestinal. Son necesarios más estudios de imagen para asegurar un diagnóstico."}, {"position": 4, "text": "Deberíamos indicar la práctica de una colonoscopia descompresiva."}, {"position": 5, "text": "El manejo inicial debe ser conservador, con sueroterapia, aspiración nasogástrica y vigilancia clínica, analítica y radiográfica periódica."}]'::jsonb, 5, 5, 'definitiva', 'Es la descripción típica de un cuadro de obstrucción intestinal por bridas o adherencias debidas a cirugía previa. La respuesta correcta es la 5 y no la 1 porque la mayoría de estas situaciones se resuelve espontáneamente con tratamiento conservador.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1c1628816f14', '2d547b71a4552253fe163976ca2fac4185ef64e0', NULL, NULL, NULL, false, false, 'Genética e Inmunología', 'Un hombre de 43 años consulta por síndrome diarreico, y refiere entre sus antecedentes 3 neumonías en la edad adulta.', '¿Cuál de los siguientes estudios inmunológicos debemos solicitar?:', '[{"position": 1, "text": "Recuento de inmunoglobulinas séricas y test de capacidad de producción de anticuerpos."}, {"position": 2, "text": "Test de fagocitosis y metabolismo oxidativo de los neutrófilos."}, {"position": 3, "text": "Test de apoptosis (muerte celular programada) en los linfocitos circulantes del paciente."}, {"position": 4, "text": "Estudio del repertorio y clonalidad de los linfocitos T (alfa/beta)."}, {"position": 5, "text": "En este paciente no procedería solicitar estudio inmunológico alguno."}]'::jsonb, 5, 1, 'definitiva', 'Más de 2 neumonías lobares hacen necesario descartar un déficit inmunológico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-fceb8224c2a0', '3e485f86d597f7f615c5be70da764e8db372868a', NULL, NULL, NULL, false, false, 'Dermatología', 'Joven de 24 años que a los 3 días de un contacto sexual de riesgo presenta numerosas lesiones pustulosas, pequeñas, muy pruriginosas y que evolucionan a diminutas erosiones afectando todo el glande y la cara interna del prepucio.', 'Señale cuál es, entre las siguientes, la orientación diagnóstica más probable:', '[{"position": 1, "text": "Candidiasis genital."}, {"position": 2, "text": "Chancroide."}, {"position": 3, "text": "Sífilis secundaria."}, {"position": 4, "text": "Balanitis por Tricomonas."}, {"position": 5, "text": "Infección fúngica por dermatofitos."}]'::jsonb, 5, 1, 'definitiva', 'El chancroide es una lesión solitaria. La sífilis secundaria suele darse como un exantema generalizado o como lesiones carácteristicas en palmas y plantas (clavos sifilíticos) con un periodo de latencia más largo. La balanitis por tricomonas asocia siempre uretrtitis, que no se refiere en la pregunta. Por tanto, la respuesta es la 1. Sin embargo, la clínica sugiere más un herpes simple que una candidiasis y la 5 habla también de hongos (aunque los dermatofitos no dan balanitis)…. desde nuestro punto de vista, aún dando por correcta la 1, la pregunta induce a confusión, podría ser impugnable. Además, la candidiasis genital no es necesariamente de transmisión sexual.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9f848690b70d', '144b2c14f2985bf4ba6ece1f469a40ef87fbbd3f', NULL, NULL, NULL, false, false, 'Urología', NULL, 'Ante un hombre de 49 años, asintomático, con el antecedente familiar de padre fallecido por cáncer de próstata, que en un control rutinario de empresa se identifica un PSA (Antígeno Prostático Específico) de 5,9 ng/ml, con un cociente de PSA libre/PSA total del 11% y que en un tacto rectal se aprecia aumento de consistencia en el lóbulo derecho prostático, ¿cuál es la siguiente indicación clínica?', '[{"position": 1, "text": "Plantear al paciente la realización de una ecografía transrectal y biopsia prostática."}, {"position": 2, "text": "Realizar un TAC abdominopélvico."}, {"position": 3, "text": "Iniciar tratamiento con Inhibidores de la 5 alfa Reductasa para reducir a la mitad los niveles del PSA."}, {"position": 4, "text": "Iniciar tratamiento combinado de análogos de la LHRH y antiandrógenos."}, {"position": 5, "text": "Realizar una gammagrafía ósea."}]'::jsonb, 5, 1, 'definitiva', 'El paciente tiene PSA >4 y tacto con aumento de consistencia, lo que implica la necesidad de una biopsia guiada por ecografía transrectal, para diagnosticar si se trata de una Hiperplasia Benigna de Próstata o Cáncer de próstata.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c33a11cb3ee7', '24416c815d22928f23d3f58ad2f729e27df43904', NULL, NULL, NULL, false, false, 'Ginecología y Obstetricia', 'Mujer de 43 años, remitida a la Consulta de Patología del Tracto Genital Inferior del Hospital por presentar una citología cérvico-vaginal informada como «L-SIL» (Lesión Intraepitelial de Bajo Grado). Refiere infecciones vaginales de repetición (Trichomoniasis,…) y haber tenido más de 5 parejas sexuales en su vida.', 'La mejor estrategia de atención a esta mujer es:', '[{"position": 1, "text": "Conización con asa de diatermia."}, {"position": 2, "text": "Legrado endocervical con legra de Kevorkian."}, {"position": 3, "text": "Biopsia de endometrio con cánula de Cornier."}, {"position": 4, "text": "Histerectomía sin anexectomía."}, {"position": 5, "text": "Aconsejarle que deje el tabaco y los anticonceptivos y hacerle un control en 6 meses."}]'::jsonb, 5, 5, 'definitiva', 'La mejor respuesta a esta pregunta es la número 5. La mayoría de laslesiones identificadas como L-SIL se asocian a infección por VPH: por ello, se aconseja dejar el tabaco, ya que éste es un factor de progresión de la dicha infección. Por otro lado y según los últimos estudios, el 70% de las citologías informadas como LSIL remitirán, un 15% persistirá y otro 15% mostrará una citología más grave, sin poder diferenciarse si se trata de una progresión biológica o de una lesión oculta en la citología inicial. Debido a ello, lo más adecuado es volver a hacerle un control a los 6 meses. Dado los antecedentes personales de la mujer (más de 5 parejas sexuales e infecciones de repetición) y su edad, lo ideal sería remitirla para realizar una colposcopia. No obstante, la respuesta 5 dice que control en 6 meses, pero no especifia qué control (podría ser una colposcopia o una citología).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3b5833304035', '87eb28e9e037552d1cacb6f886ac368bff98ed59', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Paciente de 40 años de edad, fumador desde los 18 años y sin antecedentes de interés. Consulta por cuadro de 24 horas de evolución de escalofríos, fiebre termometrada de 39ºC y tos con expectoración. La Rx de tórax pone de manifiesto un aumento de densidad con patrón alveolar en el LSD y el paciente es diagnosticado de NAC.', '¿Cuál es el agente etiológico más frecuente y por tanto de obligada cobertura al elegir el tratamiento atb empírico?', '[{"position": 1, "text": "Mycoplasma pneumoniae."}, {"position": 2, "text": "Chlamydia pneumoniae."}, {"position": 3, "text": "Streptococcus pneumoniae."}, {"position": 4, "text": "Legionella pneumophila serogrupo 1."}, {"position": 5, "text": "Haemophilus influenzae."}]'::jsonb, 5, 3, 'definitiva', 'Esta es una pregunta de epidemiología bastante fácil, en adultos sin otros datos, Neumococo es el 1º.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-b64ae8c895d1', '4276d8e252a0db282d7893c8605d1b484cdac671', NULL, NULL, NULL, false, false, 'Cirugía General', 'Una mujer de 78 años acude a Urgencias por dolor en fosa ilíaca izquierda de 24 horas de evolución asociado a fiebre y algún vómito ocasional. A la exploración destaca dolor a la palpación de forma selectiva en la fosa ilíaca izquierda con sensación de ocupación, defensa y descompresión positiva.', 'Ante la sospecha de diverticulitis aguda, ¿cuál de las siguientes afirmaciones es correcta?', '[{"position": 1, "text": "La exploración complementaria más segura y de mejor rendimiento es el enema con contraste baritado."}, {"position": 2, "text": "En caso de absceso pélvico contenido, está indicada la colocación de un drenaje percutáneo guiado con TAC o ecografía."}, {"position": 3, "text": "En caso de precisar intervención quirúrgica tras solucionarse el episodio agudo, el abordaje laparoscópico está contraindicado."}, {"position": 4, "text": "En caso de diverticulitis aguda no complicada, está indicada la sigmoidectomía electiva tras la curación del primer episodio agudo."}, {"position": 5, "text": "Si se produjera una peritonitis generalizada, la técnica quirúrgica más adecuada es la práctica de una colostomía derivativa sin resección del segmento sigmoideo afectado."}]'::jsonb, 5, 2, 'definitiva', 'La 1 es incorrecta porque las pruebas de imagen de elección serían ecografía o TC; la 3 es incorrecta porque el abordaje laparoscópico está indicado de entrada; la 4 es incorrecta porque la indicación en el primer episodio es para menores de 50 años, en el resto se indica después del segundo episodio o en casos de clínica persistente o en sospecha de neoplasia; y la 5 es incorrecta porque la cirugía en casos de perforación con peritonitis siempre debe resecar el segmento de colon afecto para controlar el foco de la infección.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-a020ba255b98', 'c5e8f88b4c7540b167afbb234c1ac43ff7c5bce6', NULL, NULL, NULL, false, false, 'Reumatología', 'Mujer de 75 años, con menopausia a los 52 años, sin antecedentes familiares ni personales de fractura, diagnosticada de arteritis de la temporal, que va a iniciar tratamiento con prednisona a dosis altas y con expectativa de tratamiento durante al menos un año. La demora de densitometría (DXA) en su centro es de 4-5 meses. Se plantea tratamiento preventivo de osteoporosis.', 'Entre las siguientes ¿cuál es la actitud más adecuada?:', '[{"position": 1, "text": "Solicitar DXA y esperar al resultado."}, {"position": 2, "text": "Valorar riesgo absoluto de fractura mediante el cuestionario FRAX sin DMO y tratar sólo si es alto."}, {"position": 3, "text": "Iniciar tratamiento con Bisfosfonatos y vitamina D (800 UI/día)."}, {"position": 4, "text": "Administrar suplemento de calcio (1g) y vitamina D (800 UI/día)."}, {"position": 5, "text": "Valorar si tiene osteopenia en las radiografías y tratar si está presente."}]'::jsonb, 5, 4, 'definitiva', 'En los datos que nos proporcionan no hay factores de riesgo clínico de osteoporosis previos a la enfermedad actual. Como se instaurará una pauta prolongada y a dosis altas con prednisona es recomendable, además de las medidas preventivas no farmacológicas, iniciar en cualquier caso un tratamiento para minimizar la pérdida de masa ósea secundaria que se produce con la administración de glucocorticoides (y, sobre todo, en los primeros meses). Por tanto, y sólo por este motivo, quedarían descartadas las opciones 1, 2 y 5 (las tres anteponen otro condicionante). En este contexto, y al tratarse de una persona de más de 65 años, una actitud adecuada sería administrar suplementos de calcio (los corticoides son osteopenizantes por producir, entre otros mecanismos, un balance negativo de este elemento) y vitamina D. La opción de asociar un bifosfonato también se podría contemplar, pero en la propuesta 3 falta el suplemento de calcio.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-03b5aa01bd4c', 'd11672f8fc26c16faf230186dde111b932f5ab88', NULL, NULL, NULL, false, false, 'Reumatología', 'Hombre de 19 años de edad que consulta por un cuadro de 24 horas de evolución de dolor, tumefacción e impotencia funcional de la rodilla derecha acompañado de fiebre de 38°C. La exploración física pone de manifiesto signos inflamatorios y derrame articular en la rodilla derecha. Los datos analíticos muestran una leucocitosis con neutrofilia y una elevación de la proteina C reactiva. Se hace el diagnóstico sindrómico de monoartritis aguda.', '¿Cuál es el diagnóstico etiológico más probable?', '[{"position": 1, "text": "Artritis por microcristales."}, {"position": 2, "text": "Artritis reactiva."}, {"position": 3, "text": "Artritis infecciosa bacteriana."}, {"position": 4, "text": "Artritis infecciosa por mycobacterias."}, {"position": 5, "text": "Artritis reumatoide."}]'::jsonb, 5, 3, 'definitiva', 'Una monoartritis aguda asociada a fiebre, leucocitosis con neutrofilia y aumento de reactantes de fase aguda no siempre tiene un origen séptico. En ausencia de más información (anamnesis más completa sobre la enfermedad actual, factores de riesgo, antecedentes personales y familiares, síntomas o signos extraarticulares, etc.) cabe decir que también la 1 y 2 (y muy excepcionalmente la 5) podrían debutar con un cuadro clínico y biológico similar. Con los datos que nos proporcionan y teniendo en cuenta que se trata de un varón joven, la opción más probable sería la de una artritis infecciosa bacteriana (la causada por mycobacterias suelen tener un curso crónico). Y sobre todo, por sus implicaciones, la primera que siempre hay que descartar.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e5df2ad66c12', '253ce27e4a57953887ea8e595c95800c63e1389e', NULL, NULL, NULL, false, false, 'Nefrología', 'Un hombre de 54 años de edad es diagnosticado de tumor renal izquierdo sugestivo de carcinoma de células renales. En su estudio analítico preoperatorio se detectan niveles elevados de GPT, fosfatasa alcalina y alfa-2-globulina y tiempo de protrombina alargado. El hígado está aumentado de tamaño de forma difusa, pero sin defectos de infiltración hepática.', 'La justificación más probable de estos hallazgos se debe a:', '[{"position": 1, "text": "Metástasis hepáticas."}, {"position": 2, "text": "Trombosis tumoral intrahepática."}, {"position": 3, "text": "Hepatitis aguda."}, {"position": 4, "text": "Presencia de sustancias hepatotóxicas producidas por el tumor."}, {"position": 5, "text": "Hemocromatosis."}]'::jsonb, 5, 4, 'definitiva', 'Pregunta muy fácil en la que nos están presentando a un paciente con síndrome de Stauffer, un síndrome paraneoplásico que consiste en una disfunción hepática secundaria a productos tóxicos segregados por una serie de tumores (el más frecuente, el carcinoma de células renales, como el que nos cuenta el caso). Se produce, como en este caso, una colestasis (elevación de fosfatasa alcalina), movilización de enzimas hepáticsa y alargamiento del tiempo de protrombina que indican disfunción hepática. Se descartan las metástasis (no hay defectos de infiltración hepática), la trombosis tumoral intrahepática (daría otra sintomatología y esta sería más aguda), y la hepatitis aguda y hemocromatosis (no están en contexto ni es lo que el autor de la pregunta quiere que pensemos).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-8f651b5265ea', '81531dc0b21cb43a60c699e5e868d25d48fbd86a', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un hombre de 32 años, ADVP y que ha salido recientemente de la cárcel, tiene una prueba cutánea con derivado proteico (PPD) con 10 mm de induración. Hace un año, el PPD era negativo, actualmente está asintomático, la serología para VIH es negativa y su Rx Tórax es normal.', '¿Qué actitud entre las siguientes le parece más adecuada?', '[{"position": 1, "text": "No realizar tto y control anual de Rx."}, {"position": 2, "text": "Cultivo de esputo para micobacterias y tratar sólo si son positivos."}, {"position": 3, "text": "Isoniazida durante 9 meses."}, {"position": 4, "text": "Tratamiento con 4 drogas 4 meses."}, {"position": 5, "text": "Tratamiento con RIF y PRZ durante 2 meses."}]'::jsonb, 5, 3, 'definitiva', 'Ante una conversión en el PPD en un periodo de 2 años, y descartando la enfermedad tuberculosa actual, está indicada la quimioprofilaxis con INH, aunque yo creía que se hacía durante 6 meses y no 9. El resto no es cuestionable.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9b5263b440ce', 'a8e24f869242c14e786e1740182a58164776e4fb', NULL, NULL, NULL, false, false, 'Anatomía Patológica', 'Un joven de 20 años con clínica de ataxia, cefaleas y masa sólido-quística en hemisferio cerebeloso derecho es intervenido quirúrgicamente, resecándose una lesión que histológicamente muestra células con procesos citoplasmáticos largos y finos, patrón fascicular y microquístico, numerosos vasos y fibras de Rosenthal.', 'El diagnóstico anatomopatológico más probable es:', '[{"position": 1, "text": "Astrocitoma pilocítico."}, {"position": 2, "text": "Xantoastrocitoma pleomórfico."}, {"position": 3, "text": "Neurocitoma central."}, {"position": 4, "text": "Liponeurocitoma."}, {"position": 5, "text": "Enfermedad por priones."}]'::jsonb, 5, 1, 'definitiva', 'Una pregunta que no parece revestir segunda intención, al no haber elementos confusos. El enunciado resume de manera concisa la descripción del astrocitoma pilocítico. Las fibras de Rosenthal pueden confundirnos ya que son poco específicas, y hacernos pensar,por ejemplo, en el xantoastrocitoma pleomórfico en el que también pueden encontrarse, pero la morfología celular descrita (procesos citoplasmáticos largos y finos, que son los que dan el nombre de «pilocítico») nos mantiene la primera opción como la correcta. Podemos encontrar una buena descripción de la entidad, explicándonos lo que la distingue de otros tumores gliales en Practical Surgical Neuropathology. A Diagnostic Approach. A. Perry, D.J. Brat. p82-88. Churchill Livingstone Elsevier. 2010. (Philadephia).', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9b2aa23daa2c', '4d3497cffba8598c7d80a59939a93bf52297f91a', NULL, NULL, NULL, false, false, 'Medicina Preventiva y Epidemiología', 'Varón homosexual de 30 años de edad VIH (+) que participa como voluntario en un centro de ayuda a pacientes con SIDA. Según su historia clínica recibió toxoide diftérico (Td) hace 6 años, la vacuna triple vírica en la infancia y en la adolescencia, y la hepatitis B hace 3 años. Actualmente se encuentra asintomático con un recuento de CD4 superior a 200 cls/microlitro.', '¿Qué vacunas deberíamos recomendarle?', '[{"position": 1, "text": "Gripe estacional, neumocócica, meningitis tetravalente y hepatitis A."}, {"position": 2, "text": "Gripe estacional, Td, neumocócia y meningitis tetravalente."}, {"position": 3, "text": "Meningitis tetravalente, neumocócia y gripe estacional."}, {"position": 4, "text": "Td, meningitis tetravalente, neumocócica."}, {"position": 5, "text": "Triple vírica, gripe estacional, neumocócica."}]'::jsonb, 5, 1, 'definitiva', 'las recomendaciones de vacunación para los adultos HIV+ incluyen vacuna de la hepatitis B, gripe, triple vírica, antineumocócica, Td y Tdap, y para algunos adultos, hepatits A, o A y B combinada, meningitis bacteriana, VPH y antimeningocócica (Fuente [1]). Teniendo en cuenta que el individuo ha recibido algunas vacunas, que tiene un recuento CD4 >100 (si fuera menor habría alguna contraindicación) y trabaja en un centro de ayuda a pacientes con SIDA (se le equipara a “personal de salud”) las respuestas 2, 4 y 5 son erróneas. Las cuatro vacunas de la opción 1 son administrables. Con algo más de detalle: Vacuna frente al tétanos y la difteria: todas las personas deben estar vacunados frente a estas dos enfermedades. Vacuna frente a la hepatitis B: los virus de la hepatitis B y del VIH comparten las mismas vías de transmisión por lo que es frecuente que el paciente infectado por VIH esté infectado también por el virus de la hepatitis B. Por esto es importante conocer si la persona infectada por VIH presenta marcadores de infección por hepatitis B y proceder a la vacunación en caso de que no los tenga. Vacuna frente a la hepatitis A: la hepatitis A en una persona portadora de hepatitis B, con hepatitis C o con otra enfermedad hepática puede ser muy grave. Dado que estas infecciones son más frecuentes en el paciente infectado por VIH se recomienda su vacunación frente a la hepatitis A. Vacuna frente a la gripe: una gripe en un paciente con falta de respuesta inmune presenta mayor gravedad y riesgo de complicaciones, por lo que está indicada la vacunación anual frente a esta enfermedad. Si la situación inmunitaria del paciente está muy deteriorada, la respuesta a la vacunación está disminuida. En este caso es fundamental la vacunación de todos los convivientes de la persona infectada por VIH para evitar que le transmitan la enfermedad. Vacuna frente al neumococo: las infecciones neumocócicas (en especial las neumonías) son hasta 10 veces mas frecuentes en las personas infectadas por VIH que en los adultos no infectados por el VIH, por lo que se recomienda la vacunación, si bien en pacientes con recuentos inferiores a 200/mm3 la respuesta protectora no suele ser suficiente. Deben recibir una segunda dosis a los 3-5 años. Los niños infectados por VIH deben vacunarse con la vacuna antineumocócica conjugada con el número de dosis que le correspondan según la edad. Vacuna frente al Haemophilus Influenzae tipo b: esta bacteria es causa de neumonías y meningitis, en especial en niños. Aunque en los adultos infectados por VIH representa un número pequeño de las causas de infección, se recomienda la vacunación. Vacuna frente al sarampión, la rubéola y la parotiditis (triple vírica): las tres enfermedades pueden adquirir una mayor gravedad en los pacientes infectados por VIH, en especial el sarampión, por lo que todas ellas deben de estar vacunadas, siempre que la inmunodepresión no sea severa (recuento menor a 200/mm3).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-3b28efd5a278', '22999bd5f1308c5cca85891040a8ca4ae434077c', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'Ante un paciente de 60 años de edad, diabético, con angina estable secundaria a cardiopatía isquémica por obstrucción subtotal en el tercio medio de la arteria coronaria descendente anterior, ¿qué tratamiento propondría?', '[{"position": 1, "text": "Médico con vasodilatadores y betabloqueantes para evitar la angina."}, {"position": 2, "text": "Expectante con reposo riguroso ya que al disminuir la demanda miocárdica de oxígeno deberá disminuir la angina."}, {"position": 3, "text": "Quirúrgico para revascularizar el miocardio isquémico mediante un puente (bypass) de arteria mamaria izquierda distal a la lesión en la arteria coronaria enferma."}, {"position": 4, "text": "Dilatación de la lesión en la arteria coronaria mediante un cateterismo terapéutico."}, {"position": 5, "text": "Cateterismo terapéutico para dilatar la lesión de la arteria enferma e implantación de un “stent” en la zona dilatada."}]'::jsonb, 5, 5, 'definitiva', 'Angina estable en diabético: esta pregunta es un guiño al estudio BARI-2D (NEJM 2009), que demostró que el manejo médico no era inferior a la revascularización (de hecho, las nuevas guías recogen esa tendencia de que no hay que abrir sistemáticamente toda estenosis coronaria). La respuesta 1 va en ese sentido, aunque echo de menos las estatinas, IECA y antiagregantes, y me sobran los vasodilatadores (los nitratos son clase IIb, si no me falla la memoria). La 2 es absurda: ¿que esté sentado para que no tenga angina? Es como talar el bosque para evitar incendios. Las 3 a 5 tratan acerca de revascularizar: dado que se trata de un único vaso y no es una DA proximal, la revascularización habría de ser percutánea, por lo que descartamos la 3. Entre la 4 y la 5, la quinta es más completa: no sólo habría que dilatar, sino también implantar un stent. Así que la duda sería entre la 1 y la 5. Aplicando las reglas generales de respuesta en el MIR, si dos opciones son parecidas salvo en un detalle, la correcta es una de esas, por lo que marcaríamos la 5 (y es lo que se haría en cualquier hospital actualmente: una arteria subocluida se dilata directamente). Por otra parte, y aunque la 1 es incompleta, supongo que el autor ha querido ir de listillo y demostrar que se ha leído los últimos artículos. Conclusión: marcaría la 5… pero no me sorprendería que fuese la 1.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-47d1e96fdf44', 'afff7975bcc0c31638c9d20a8b5e4ed16d8319ef', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Paciente de 52 años de edad que refiere disnea de medianos esfuerzos desde hace 6 meses. No ha presentado angina ni síncopes. La exploración física y las pruebas diagnósticas demuestran la existencia de un gradiente transvalvular aórtico medio de 55 mmHg y un área calculada de 0,7 cm². Fracción de eyección del 65%.', 'El tratamiento que debe indicarse a este paciente es:', '[{"position": 1, "text": "Diuréticos y controles más frecuentes por un especialista."}, {"position": 2, "text": "En caso de aumentar la disnea de esfuerzo, debe practicarse una dilatación percutánea de la válvula aórtica con catéter de balón."}, {"position": 3, "text": "Sustitución de la válvula aórtica por una prótesis/bioprótesis."}, {"position": 4, "text": "Sustitución de la válvula aórtica por un homoinjerto."}, {"position": 5, "text": "Implante de una válvula percutánea."}]'::jsonb, 5, 3, 'definitiva', 'Algo aórtico. Me dan un gradiente, que sin saber los valores parece algo alto (¡55 mmHg!) y el área, que a ojo se ve chiquitín: esto va a ir de estenosis aórtica… Y tiene disnea. Estenosis aórtica sintomática, ¿querrá el examinador que le mande a operar? Con las guías en la mano, así es: se trata de una estenosis severa tanto por el área (<1 cm²) como por el gradiente medio (>40 mmHg), con una fracción de eyección conservada, y sintomática. Indicación quirúrgica. Si hacemos la 1 le quitamos esperanza de vida, porque permitimos que el ventrículo claudique. La 2 está desfasada: ¿valvuloplastia con balón? Sólo si el riesgo quirúrgico es inasumible, y en ese caso haríamos la 5, implante de una TAVI (ver [1]). Pero se trata de un hombre de 52 castañas, que asumimos que tiene buena carrocería porque camina para tener disnea. Así que a quirófano. ¿Un homoinjerto? Eso es la técnica de Ross, le quito la pulmonar y se la pongo donde la aórtica. Pero es raro, complejo y sólo se hace en pediátricos. Lo correcto es la 3, sin duda: sustituir por una prótesis, preferiblemente mecánica a no ser que el paciente tenga contraindicación para la anticoagulación.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c36347b5e678', '3b86832de69745bd939e43d21bfcb55415409593', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Un paciente de 82 años acude a la consulta por presentar mareos repentinos y frecuentes, sin pródromos, de corta duración y que ceden espontáneamente, sin presentar nunca síncope. La exploración física y el electrocardiograma basal son normales. En un registro ambulatorio del electrocardiograma durante 24 horas se detecta en el periodo vigil fases de corta duración de ausencia de ondas P previas al QRS con un ritmo de escape de la unión auriculoventricular con QRS estrecho a 40 lpm y una onda al inicio del segmento ST correspondiente a una P retrógrada. No se detectan periodos de asistolia superiores a 3 segundos.', 'Ante esto usted diría:', '[{"position": 1, "text": "El paciente tiene un BAV de tercer grado y precisa la implantación de un marcapasos."}, {"position": 2, "text": "La ausencia de periodos de asistolia >3 segundos excluye una causa cardiaca de los mareos."}, {"position": 3, "text": "Estaría indicado un tratamiento farmacológico que incrementara la conducción en el nodo AV."}, {"position": 4, "text": "El paciente presenta una disfunción sinusal con bloqueo sinoauricular y requiere, por presentar síntomas, la implantación deun marcapasos."}, {"position": 5, "text": "Las alteraciones detectadas en el electrocardiograma ambulatorio son propias de pacientes de esta edad y no hay indicación de intervención terapéutica."}]'::jsonb, 5, 5, 'definitiva', '¿Qué son esos hallazgos en el Holter? Si el nodo sinusal falla, el nodo AV toma las riendas y estimula el ventrículo. En un 10% de las personas existe conducción retrógrada, por lo que ese latido generado en el NAV estimula tanto ventrículos como aurículas, dando una P retrógrada como la que se informa en el estudio. En este sentido, sin problema. Asimismo, tampoco hay pausas superiores a 3 segundos que puedan provocar un síncope cardiogénico (que, de hecho, nunca ha sufrido). La opción 1 queda descartada: no es un BAV completo. La 2 tampoco se puede contestar: excluir, lo que se dice excluir… Es como el nunca/siempre. La 3 no tiene mucho sentido: sí se podrían suspender aquellos que deterioran la conducción (betabloqueantes, antagonistas del calcio), pero fármacos que faciliten, como no le pongamos una perfusión de atropina para que se la lleve a casa… En la 4, afirmar que presenta un bloqueo sinoauricular es rapear un poco: sin un estudio electrofisiológico no puede afirmarse, no necesariamente tiene un bloqueo SA, y eso tampoco indicaría por sí solo el implante de un marcapasos. Así que, finalmente, yo marcaría la opción 5.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0255f69a4888', '1c2550e230e0051dc881bc2538a8187ef2945f7a', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Mujer de 82 años hipertensa en tratamiento con atenolol, hidroclorotiazida y digoxina. Acude a urgencias por fibrilación auricular y se le administra verapamil IV. Se evidencia en ECG un bloqueo auriculoventriuclar completo.', '¿Cuál es la causa más probable de esta situación clínica?', '[{"position": 1, "text": "Intoxicación digitálica por interacción farmacocinética por verapamilo."}, {"position": 2, "text": "Hipopotasemia por la administración de tiazida y digoxina."}, {"position": 3, "text": "Interacción farmacodinámica del betabloqueante, digoxina y verapamil."}, {"position": 4, "text": "Efecto hipotensor del diurético tiazídico."}, {"position": 5, "text": "Arritmia cardiaca por verapamil."}]'::jsonb, 5, 3, 'definitiva', 'Ya toma dos frenadores del nodo AV y le añades un tercero, ¿y te extrañas de que haga un bloqueo AV completo después de guarrearle con fármacos de distintas familias pero mismo efecto (farmacodinámica)? La tres. Y recuerda que los fármacos son como las copas cuando vas de bares: ¡no mezcles!', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-25a32897cb3e', '3bfdd436104d3743ac3db927a087dd5946cde67e', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', 'Mujer de 45 años con antecedentes de soplo cardiaco detectado en edad pediátrica. Ingresa en el servicio de Urgencias por cuadro de palpitaciones, cansancio fácil y edemas maleolares. La exploración física pone de manifiesto ausencia de cianosis. Saturación de oxígeno por pulsioxímetro 97% TA 120/80 mmHg. Ritmo cardiaco irregular a 100 lpm. Soplo sistólico eyectivo (2/6) en foco pulmonar. 2º ruido desdoblado, amplio y fijo. No estertores. Ligera hepatomeglaia (2-3 cm). Ligeros edemas maleolares. ECG: arritmia completa por fibrilación auricular a 100 lpm. QRS +120º. Trastorno de conducción de la rama derecha del haz de His.', '¿Cuál es su orientación diagnóstica?', '[{"position": 1, "text": "Comunicación interventricular."}, {"position": 2, "text": "Estenosis aórtica."}, {"position": 3, "text": "Estenosis mitral."}, {"position": 4, "text": "Comunicación interauricular."}, {"position": 5, "text": "Conducto arterioso persistente."}]'::jsonb, 5, 4, 'definitiva', 'Si tiene un soplo pediátrico, pienso en una congénita. Hepatomegalia, edemas maleolares y BRD, algo que sobrecargue el corazón derecho. Descartamos pues las estenosis aórtica y mitral. Un ductus persistente daría cianosis: descartado. ¿CIV o CIA? Si me dicen que tiene FA es porque las aurículas son de talla XL, y una CIV no produce dilatación auricular.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-19c96c6dd281', 'b0f59eb4a004c3cfa6aafa46f434404c1b96283e', NULL, NULL, NULL, false, false, 'Cardiología y Cirugía Cardiovascular', NULL, 'En un paciente con clínica de insuficiencia cardiaca que presenta una ascitis desproporcionadamente elevada en relación al edema periférico, la etiología más probable sería:', '[{"position": 1, "text": "Una estenosis aórtica grave."}, {"position": 2, "text": "Una miocardiopatía dilatada con disfunción ventricular izquierda significativa."}, {"position": 3, "text": "Una hipertensión pulmonar primaria."}, {"position": 4, "text": "Una miocardiopatía hipertrófica obstructiva."}, {"position": 5, "text": "Una pericarditis constrictiva."}]'::jsonb, 5, 5, 'definitiva', 'Nos cuentan clínica de fallo derecho, con edemas y ascitis. Por lo tanto, descartamos los fallos del corazón izquierdo: EAo, dilatada con DSVI y una MHO. De los dos que nos quedan, en la pericarditis constrictiva tenemos presiones de llenado aumentadas en cavidades derechas, que provocan aumento de presión retrógrado con congestión hepática, ascitis, edemas, etc. Por el contrario, en la hipertensión pulmonar, la válvula tricúspide se ocupa (a priori) de “contener” esa sobrepresión.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-123429c3d73e', '5dfeca03bde258912ceddf49668b8aea75048224', NULL, NULL, NULL, false, false, 'Pediatría', 'Lactante de 10 meses previamente sano con gastroenteritis aguda de un día de evolución y signos de deshidratación leve, sin sangre ni moco en las heces y sin tolerancia oral.', '¿Cuál es el tratamiento de elección inicial en nuestro medio?', '[{"position": 1, "text": "Rehidratación intravenosa, dieta absoluta 8 horas y comenzar alimentación con dieta astringente."}, {"position": 2, "text": "Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 60-75 mEq/L) y continuar con su alimentación habitual."}, {"position": 3, "text": "Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 60-75 mEq/L) mantener alimentación habitual y amoxicilina oral 10 días."}, {"position": 4, "text": "Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 60-75 mEq/L) y comenzar alimentación con fórmulas sin lactosa."}, {"position": 5, "text": "Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 60-75 mEq/L) mantener alimentación habitual y loperamida 7 días."}]'::jsonb, 5, 2, 'definitiva', 'El lactante presenta una GEA aguda sin signos de alarma ni de deshidratación grave. El primer paso sería intentar tolerancia oral con suero de rehidratación oral y continuar con su alimentación normal si buena tolerancia. La respuesta 1 puede dar lugar a dudas, por el hecho de que en el enunciado comentan que el paciente “no tolera a la vía oral” Podría en ese caso iniciarse rehidratación intravenosa… pero no sería conveniente dejar en dieta absoluta 8 horas ni tampoco una dieta astringente posterior, por lo que yo me decanto por la 2. El resto de tratamientos, no aportan ningún beneficio.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-80fa4db4863e', 'c91a4012234f275af428882d31088a4c51835b5f', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un paciente acude al Servicio de Urgencias con Fiebre sin foco de 24 h de evolución, hipoTA e impresión de gravedad. Sufrió una esplenectomía hace 2 años para estadificación de enfermedad de Hosgkin.', '¿Qué microorganismo se implica con mayor frecuencia?', '[{"position": 1, "text": "Streptococcus pneumoniae."}, {"position": 2, "text": "Pseudomonas aeruginosa."}, {"position": 3, "text": "Salmonella no typhi."}, {"position": 4, "text": "Pneumocystis jirovecii."}, {"position": 5, "text": "Streptococcus viridans."}]'::jsonb, 5, 1, 'definitiva', 'Otra de epidemiología. En pacientes esplenectomizados, el riesgo de adquisión de infecciones graves por gérmenes encapsulados, se encuentra aumentado, siendo nuevamente Neumococo el más frecuente.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1aa87d0fe915', '101551007c44ec4f2d59bcb88daa30522b678869', NULL, NULL, NULL, false, false, 'Pediatría', 'Acude al centro de salud un niños de 4 años que, 5 minutos antes, comienza con cuadro de angioedema en cara, conjuntivitis, congestión nasal y ronquera, coincidiendo con la ingesta de una cucharada de yogur que le dieron por error en el colegio. Entre los antecedentes está diagnosticado de alergia a proteínas de leche de vaca. En la exploración se constata hipotensión leve, frecuencia cardiaca 110 lat/min, Sat O2 93%, está pálido y algo sudoroso, con sibilancias diseminadas.', '¿Cuál es el primer tratamiento de elección?', '[{"position": 1, "text": "Provocar el vómito."}, {"position": 2, "text": "Adrenalina 1/1000 subcutánea."}, {"position": 3, "text": "Adrenalina 1/1000 intramuscular."}, {"position": 4, "text": "Metilprednisolona intramuscular."}, {"position": 5, "text": "Salbutamol nebulizado."}]'::jsonb, 5, 3, 'definitiva', 'Estamos ante un caso de Anafilaxia por lo que la primera medida es administrar Adrenalina 1/1000 intramuscular (0,01mg/kg) Posteriormente, se darán corticoides sistémicos como la metilprednisolona, que tardará unas horas en hacer efecto. Así que primero adrenalina, por ser de acción más rápida, después el resto. (Pregunta muy similar a una del año pasado, en lugar de yogur, fue tortilla).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-502992c8adcc', 'd42e3663ed9783091d49b58f574d4ca128d483a6', NULL, NULL, NULL, false, false, 'Hematología', 'Acude al Servicio de Urgencias un hombre de 72 años con fractura patológica en fémur izquierdo. Tras la intervención quirúrgica, se realiza un estudio diagnóstico para averiguar la patología subyacente con los siguientes hallazgos: hemoglobina 9.5 g/dl, protenias totales 11 g/dl, (VN: 6-8 g/dl), albúmina sérica 2 g/dl, (VN 3.5-5,0 g/dl), beta 2 microglobulina 6 mg/l (VN 1,1-2,4 mg/l), creatinina sérica 1,8 mg/dl (VN: 0,1-1,4 mg/dl).', 'Indique cuáles serían las pruebas diagnósticas necesarias para confirmar el diagnóstico más probable:', '[{"position": 1, "text": "Serie ósea radiológica y aspirado de médula ósea."}, {"position": 2, "text": "Electroforesis sérica y urinaria y pruebas de función renal."}, {"position": 3, "text": "Aspirado de médula ósea y concentracion de calcio sérico."}, {"position": 4, "text": "Aspirado de médula ósea y electroforesis sérica y urinaria."}, {"position": 5, "text": "Biopsia de la fractura patológica y serie ósea radiológica."}]'::jsonb, 5, 4, 'definitiva', 'Va a tener un mieloma. Para diagnóstico, una muestra (médula ósea) y electroforesis para determinar el tipo de pico monoclonal. Luego, para extensión, valor pronóstico y decidir tratamientos, lo demás, pero una vez diagnosticado.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d19ad3254dab', 'f945d15273ea5cb0faea0df697fcb605187c3c5a', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Tras un accidente de tráfico un paciente de 38 años ingresa en UCI en coma. Tras varios días el paciente no mejora neurológicamente y en la TAC se visualizan lesiones puntiformes hemorrágicas en cuerpo calloso y en unión córtico-subcortical.', '¿Cuál es su diagnóstico?', '[{"position": 1, "text": "Hematoma subdural agudo."}, {"position": 2, "text": "Púrpura trobocitopénica."}, {"position": 3, "text": "Contusión hemorrágica cerebral."}, {"position": 4, "text": "Lesión axonal difusa grave."}, {"position": 5, "text": "Encefalopatía hipóxico-isquémica."}]'::jsonb, 5, 4, 'definitiva', 'La lesión axonal difusa produce un deterioro precoz y mantenido del nivel de conciencia (como comenta el enunciado del caso) sin que haya en el TC una lesión que justifique el cuadro. En ocasiones, se evidencia en esta prueba de imagen hemorragias puntiformes a nivel del cuerpo calloso, unión corticosubcortical y porción dorsolateral del tronco encefálico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e703d4ed85de', 'a69854de88c80bcabc5e4d65472069e016f67347', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Un hombre de 80 años es ingresado por un cuadro brusco de afasia y hemiparesia derecha. Como antecedentes destaca, hipertensión, bien controlada con dieta y deterioro cognitivo en el último año en estudio por su neurólogo. La TC craneal de urgencias demuestra un hematoma lobar frontal izquierdo sin captación de contraste.', '¿Cuál es la causa más probable del hematoma?', '[{"position": 1, "text": "Malformación arteriovenosa enmascarada por el hematoma agudo."}, {"position": 2, "text": "Hipertensión arterial crónica."}, {"position": 3, "text": "Vasculitis aislada del sistema nervioso."}, {"position": 4, "text": "Tumor cerebral."}, {"position": 5, "text": "Angiopatía cerebral amiloidea (angiopatía congofílica)."}]'::jsonb, 5, 5, 'definitiva', 'La angiopatía amiloide es la causa más frecuente de hemorragia espontánea no hipertensiva en pacientes ancianos, y suele ser de localización lobar (como en el caso). A menudo aparecen asociados a la enfermedad de Alzheimer (Manual CTO). La respuesta que más dudas puede general es la 2, la hipertensión, pero las localizaciones más frecuentes son: putamen, tálamo, protuberancia y cerebelo. Por lo tanto la mayoría de las veces se trata de hemorragias profundas (Manual CTO). Además, como pista nos dice que el paciente tiene hipertensión bien controlada sin fármacos, aunque este dato no serviría para descartar la respuesta. La respuesta 1, una malformación es típica de pacientes jóvenes, raro en gente mayor. Además disminuye la posibilidad de no hallarse una malformación con la realización del TC con contraste. La respuesta 4, un tumor cerebral, no parece probable ya que no se ve la masa en el TC, y como en el caso anterior, en más dificil no encontrar dicha lesión tras la administración de contraste. La respuesta 3, no parece correcta ya que la vasculitis es una entidad rara y más en gente mayor.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1f76c99568c5', '997fe802db00c9152a1accaeb259518246425637', NULL, NULL, NULL, false, false, 'Neurología y Neurocirugía', 'Hombre de 76 años de edad que consulta por deterioro cognitivo, lentitud y torpeza de movimientos, de ocho meses de evolución. La familia refiere que el paciente presentaba alucinaciones visuales, por lo que su médico de Atención Primaria pautó dosis bajas de risperidona, con un importante empeoramiento del estado motor.', 'A la vista de estos datos, ¿cuál es el diagnóstico más probable?', '[{"position": 1, "text": "Enfermedad de Alzheimer."}, {"position": 2, "text": "Demencia por cuerpos de Lewy."}, {"position": 3, "text": "Demencia frontotemporal."}, {"position": 4, "text": "Demencia vascular."}, {"position": 5, "text": "Enfermedad de Creutzfeldt-Jakob esporádica."}]'::jsonb, 5, 2, 'definitiva', 'La respuesta correcta es la 2 ya que presenta el caso con los síntomas típicos de la demencia por cuerpos de Lewy, siendo el síntoma guía las alucinaciones visuales. También se mencionan deterioro cognitivo progresivo, signos motores parkinsonianos (se deduce de la torpeza de movimientos) y la hipersensibilidad a los neurolépticos incluso en pequeñas dosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d6aaf4b26488', '6d62ce8109d46f91eda79a86b8eb5236d559eac2', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 50 años, bronquítico crónico que ingresa por cuadro neumónico con hemocultivo positivo a Streptococcus pneumoniae, con una CMI a penicilina de 0,0125 mg/l. Se inicia tratamiento con penicilina 2 millones cada 4h. Al quinto día, sigue con fiebre de 38ºC.', '¿Cuál de las siguientes decisiones le parece correcta?', '[{"position": 1, "text": "Cambiaría el tratamiento a ceftriaxona por su mayor eficacia."}, {"position": 2, "text": "Añadiría al tratamiento una quinolona."}, {"position": 3, "text": "Cambiaría a amoxicilina/clavulánico."}, {"position": 4, "text": "Descartaría la presencia de un empiema pleural."}, {"position": 5, "text": "Seguiría con el mismo tratamiento, suponiendo que simplemente es un problema de tiempo."}]'::jsonb, 5, 4, 'definitiva', 'Se trata de un hombre con una neumonía con germen aislado en hemocultivo y antibiograma. Según los datos que nos aportan, se trata de un neumococo sensible a penicilina (CMI< 0,125) por lo que se inicia tratamiento con penicilina a dosis altas cada 4 h, a pesar de lo cual, persiste la fiebre. Si analizamos el caso detenidamente, el tratamiento debería estar siendo efectivo ya que el germen es totalmente sensible al fármaco y la posología es la adecuada (de forma que se deberían estar manteniendo concentraciones elevadas del fármaco en todo momento, recordemos que la eficacia de los betalactámicos es tiempo-dependiente y las concentraciones del antibiótico en sangre deben estar por encima de la CMI de forma permanente para conseguir la efectividad y evitar la producción de resistencias). En tal caso, ¿qué puede estar pasando?, probablemente, a pesar de que el antibiótico sea el adecuado, no está llegando adecuadamente al foco infeccioso porque probablemente se haya producido un empiema. Deberiamos descartar la existencia del mismo y drenarlo a la vez que proseguimos con el tratamiento antibiótico. Si la posología no hubiese sido la adecuada y fuese posible la presencia de resistencias al fármaco, una opción podría haber sido tratar con ceftriaxona a dosis altas ya que recordemos que el estreptococo no produce betalactamasas y la resistencia a betalactamicos se produce por otro mecanismo (poner amoxicilina-clavuláncio no nos aportaría nada). Con la quinolona no aumentamos el espectro y es evidente que la mala evolución del paciente no es solamente un problema de tiempo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9967970f76f4', '08a78ccbf4e305096a5e6ea52b01f637b0986d0b', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Chico de 16 años que consulta por presentar amigdalitis pultácea, fiebre de hasta 38,5ºC, adenopatías cervicales dolorosas, exantema macular no pruriginoso en tórax y hepatoesplenomegalia leves, de 4-5 días de evolución. El test de Paul-Bunnell y la Ig M para el virus de Epstein-Barr son positivos. Durante su ingreso desarrolla fiebre continua de hasta 40ºC, pancitopenia, hepatitis ictérica y coagulopatía de intensidad progresiva. A la semana del ingreso, se traslada a UCI por confusión e insuficiencia respiratoria. Los hemocultivos y un urocultivo son negativos, el LCR es normal y la placa de tórax no muestra infiltrados. La procalcitonina es normal, pero PCR y ferritina están muy elevados.', 'De los enunciados a continuación, ¿cuál sería el planteamiento diagnóstico y terapéutico más correcto?', '[{"position": 1, "text": "Tiene una sepsis bacteriana de origen indeterminado y se debe administrar ceftriaxona y tratamiento de soporte."}, {"position": 2, "text": "Tiene sepsis bacteriana de origen indeterminado y se debe administrar vancomicina, ceftacidima y tratamiento de soporte."}, {"position": 3, "text": "Se trata de una mononucleosis infecciosa de curso grave y se debe administrar glucocorticoides."}, {"position": 4, "text": "Se trata de una mononucleosis infecciosa de curso grave y se debe iniciar tratamiento con Aciclovir."}, {"position": 5, "text": "Realizaría una biopsia/aspirado de médula ósea y, si se confirma hemofagocitosis, iniciaría tratamiento con inmunosupresores."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta difícil en la que la respuesta correcta podría dar lugar a discusión. Se trata de un varón de 16 años que se ingresa por un cuadro de mononucleosis por infección por VEB bastante claro que se complica durante el ingreso. Los datos de los que disponemos son: - Pancitopenia. - Hepatopatía. - Coagulopatia. - Ausencia de foco infeccioso: hemocultivos negativos, urocultivos negativos, Rx normal, LCR normal. - PCR y Ferritina elevadas/ Procalcitonina normal. Las posibles complicaciones que ha podido producirse (y que se barajan en las respuestas) son una sepsis o bien una mala evolución de la mononucleosis. Los datos clínicos podrían cuadrar con un proceso séptico, sin embargo se han descartado de manera razonable los principales focos infecciosos y uno de los marcadores más sensibles y específicos de bacteriemia (la procalcitonina) se encuentra en rango de normalidad, esto debe llamarnos la atención. Por otra parte, cabe valorar una complicación de la mononucleosis por VEB que sufre nuestro paciente, entre las complicaciones posibles están la anemia hemolítica, la meningoecefalitis (LCR normal) o el sd. De Guillain-Barré, que no concuerdan mucho con el cuadro clínico que nos presentan. Otra complicación posible y de excepcional gravedad sería el síndrome hemofagocítico; se trata de una entidad rara que se produce en determinados sujetos predispuestos y se caracteriza por una activación y proliferación incontrolada de histiocitos y linfocitos T, que produce un estado de hipercitocinemia. Los criterios diagnósticos revisados en 2004, incluyen fiebre elevada persistente, hepatoesplenomegalia, citopenias, hipertrigliceridemia, hiperferritinemia e hipofibrinogenemia. La hiperferritinemia >3000 en un contexto clínico sugestivo hace necesario el tratamiento del paciente (principalmente con inmunosupresores y corticoides) puesto que la mortalidad es muy elevada y el tratamiento precoz es esencial. El diagnóstico definitivo se hace mediante el estudio microscópico de una biopsia de MO. Aunque en esta pregunta no nos cuantifican el valor de la ferritinemia, es un dato destacable y dado que la clínica es sugestiva, llegando a cumplirse los criterios diagnósticos, me parece que la respuesta 5 sería la mas acertada.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-00e2e39c07b6', 'bdda10944f76a86faced9b3b26d9630c555b46f6', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un paciente en tratamiento quimioterápico por leucemia ingresa por una neumonía para la que se ha prescrito tratamiento con cefepime. En una Rx/TAC tórax se observa un infiltrado con signo del halo y menisco semilunar. La lesión es periférica y se indica una punción transtorácica para toma de muestras.', 'Hasta tener los resultados histológicos y microbiológicos definitivos, ¿Qué antimicrobiano añadiría al tratamiento?', '[{"position": 1, "text": "Ganciclovir."}, {"position": 2, "text": "Caspofungina."}, {"position": 3, "text": "Fluconazol."}, {"position": 4, "text": "Piperacilina-tazobactam."}, {"position": 5, "text": "Voriconazol."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta de respuesta directa. Se trata de un paciente en tratamiento quimioterapico con un cuadro respiratorio y el “signo del halo” en la Rx, datos muy sugestivos de una aspergilosis pulmonar invasora. El tratamiento se realiza con voriconazol. Aspergillus es resistente a fluconazol, por lo que no sería una opción válida.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-48741380b0af', '4b94a2a2bb0dc0d1ba9c0b3bab6f0b6143787dd8', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un paciente con una historia de consumo excesivo de alcohol ha sido diagnosticado de tuberculosis pulmonar por un cuadro de tos, fiebre, expectoración, aislándose en el cultivo de esputo Mycobacterium tuberculosis. El paciente ha iniciado tratamiento con isoniacida, rifampicina, etambutol y pirazinamida, con adecuada tolerancia. A los 20 días del inicio del tratamiento se recibe un informe de resistencia a rifampicina del M. tuberculosis aislado en el esputo.', '¿Qué régimen seleccionaría en función de este informe?', '[{"position": 1, "text": "Isoniazida, etambutol, pirazinamida durante 12 meses."}, {"position": 2, "text": "Isoniazida, etambutol, pirazinamida durante 12 meses y estreptomicina por dos meses."}, {"position": 3, "text": "Isoniazida, etambutol, pirazinamida durante 12 meses y una quinolona por dos meses."}, {"position": 4, "text": "Isoniazida, etambutol, pirazinamida y una quinolona durante 18 meses."}, {"position": 5, "text": "Isoniazida, etambutol, pirazinamida durante 18 meses y estreptomicina y una quinolona durante 2 meses."}]'::jsonb, 5, 3, 'definitiva', 'Otra pregunta que puede generar discusión. Cuando se realiza un diagnóstico de infección tuberculosa activa, se inicia tratamiento con isoniazida, rifampicina y pirazinamida junto con etambutol en caso de sospecha de cepas resistentes a alguno de los fármacos. Una vez se descarta la existencia de resistencias, se puede prescindir del etambutol. En caso de resistencia a rifampicina, se retira la rifampicina complentando el tratamiento con los 3 fármacos restantes durante 12 meses. La opción de agregar una quinolona durante los dos primeros meses de tratamiento (moxifloxacino o levofloxacino) se contempla en los casos de afectación pulmonar extensa. En este caso, no nos dicen nada de afectación pulmonar extensa pero nos dan un dato “consumo excesivo de alcohol”. Ya sabéis que en el MIR ningún dato es gratuito, y si la persona que puso esta pregunta lo quiso reflejar, probablemente su intención era que reflexionásemos acerca de ello. El alcohol ejerce un efecto inmunosupresor directo, además, el alcoholismo está relacionado con afectación de la inmunidad en las vías respiratorias. El contexto social que normalmente acompaña al paciente alcohólico tampoco ayuda. Todos los factores citados nos hacen decantarnos más hacia la respuesta número 3 aunque es innegable que la numero 1 también podría ser correcta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-2b6a6361910c', 'b1b4f6bd3ea7c9c10344ab770e3167aab99b2ab4', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Acude a nuestra consulta un hombre de 54 años diagnosticado de diabetes mellitus tipo 2. Refiere fiebre de 40ºC con escalofríos y tiritona, artromialgias y cefalea por lo que ha iniciado tratamiento con paracetamol. El cuadro se inició 24 h antes de su regreso a España. A los 3 días presenta un exantema máculo-papuloso generalizado que evoluciona a la formación de petequias más intensas en miembros inferiores. Aporta analítica donde destaca leucopenia con 3.200/mm3 y plaquetas 91.000/mm3 y elevación grave de aminotransferaras. La gota gruesa, extensión de sangre periférica, PCR y antígeno de malaria son negativas', '¿Cuál es el diagnostico de sospecha más probable?', '[{"position": 1, "text": "Infección por coronavirus."}, {"position": 2, "text": "Coriomeningitis linfocitaria."}, {"position": 3, "text": "Dengue."}, {"position": 4, "text": "Infección por virus Chikungunya."}, {"position": 5, "text": "Encefalitis de Saint Louis."}]'::jsonb, 5, 3, 'definitiva', 'Llama la atención es esta pregunta que nos digan que nuestro paciente ha regresado a España, pero no de donde (lo cual nos podría ayudar a hacer divagaciones sobre la posible causa). Sin embargo, la descripción del cuadro es muy exhaustiva asi como típica, por lo que la pregunta es facil. Se trata de una enfermedad que produce fiebre, artralgias y un exantema generalizado con petequias en los miembros inferiores. En la analítica destaca una leucopenia acompañada de plaquetopenia y elevación de transaminasas. Se ha descartado la malaria como causa posible. Todos los datos sin muy sugestivos de Dengue, sobre todo la plaquetopenia y las petequias (sugestivas de fragilidad capilar), respuesta 3 correcta.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-5e1e55dee1fb', '24208e47c48073d3afef9e748be35cd513a4ba79', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Hombre de 34 años que consulta por fiebre y malestar general. En la historia clínica se recogen como antecedentes relaciones homosexuales desde hace 4 meses con una nueva pareja. 2 meses antes de la consulta actual tuvo una lesión ulcerosa en el glande, indolora, con adenopatías inguinales bilaterales, todo ello autolimitado. Se solicitan estudios serológicos con los siguientes resultados: HIV negativo, RPR 1/320, TPHA 1/128.', '¿Qué tratamiento indicaría en este paciente?', '[{"position": 1, "text": "Ninguno."}, {"position": 2, "text": "Penicilina G intravenosa, 24 MU cada día durante 14 días."}, {"position": 3, "text": "Penicilina Benzatina 2,4 MU intramuscular, 3 dosis en tres semanas consecutivas."}, {"position": 4, "text": "Ceftriaxona 2 gramos intramusculares en una única dosis."}, {"position": 5, "text": "Penicilina Benzatina 2,4 MU intramuscular en una única dosis."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta de respuesta directa. Se trata de una sífilis (tanto por el antecendente como por la serología) en fase secundaria por lo que el tratamiento se realiza con Penicilina Benzatina 2,4 MU en una única dosis.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-369ceed64d2a', '032d143c8bb6b7084fce171791ef2c17b6ff3885', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Mujer de 53 años, que consulta por fiebre de 15 días de evolución, sin síntomas de focalidad infecciosa. En la exploración se detecta una hepatomegalia dolorosa a 5 cm del reborde costal y se palpa el bazo a 14 cm del reborde costal izquierdo. En el hemograma se aprecia Hb 8,5 g/dl, leucocitos 630/ml (linfocitos 63%, monocitos 20%, neutrófilos 17%) y plaquetas 35.000/ml. La bioquímica muestra una elevación moderada de la bioquímica hepática, LDH es normal y se observa en el proteinograma una hipergammaglobulinemia policlonal (3,5 g/dL). Tiene antecedentes de infección por VIH conocida desde hace 10 años y adherencia irregular al tratamiento antiretroviral, con determinaciones recientes de linfocitos CD4 350 cel/mL y carga viral de VIH de 154 copias/ml. Durante los últimos 3 meses ha estado tratada por poliartritis simétrica seronegativa con 10-20 mg/día de prednisona.', '¿Cuál de las siguientes afirmaciones es correcta?', '[{"position": 1, "text": "Realizaría una biopsia de médula ósea, ya que el diagnóstico mas probables es una leishmaniasis visceral."}, {"position": 2, "text": "La pancitopenia se justifica por una cirrosis asociada al virus C y no realizaría mas pruebas."}, {"position": 3, "text": "Probablemente se trate de una toxicidad medular por prednisona que trataría con retirada del fármaco y filgastrim."}, {"position": 4, "text": "Solicitaría una determinación de ANAs para descartar lupus sistémico diseminado."}, {"position": 5, "text": "Intensificaría el tratamiento antirretroviral, pues es probable que todas las manifestaciones se deban al VIH."}]'::jsonb, 5, 1, 'definitiva', 'Pregunta fácil y bastante típica. Nos hablan de una paciente VIH con seguimiento irregular del tratamiento antirretroviral, que presenta fiebre, hepatoesplenomegalia, pancitopenia y un una hipergammaglobulinemia policlonal. Todos estos datos son sugestivos de Leishmaniasis visceral, por lo que habría que realizar una biopsia de MO para buscar amastigotes y confirmar el diagnóstico.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-e76ddbfac748', '00bc47af4d47f7e446cfaeda46e748481f8b2deb', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Un hombre de 68 años es evaluado por presentar Fiebr51e, pérdida de peso y disnea de esfuerzo. La EF revela un nuevo soplo diastólico aórtico y estigmas de embolismos periféricos. La ecocardio muestra una vegetación de 1 cm en la válvula aórtica y en dos hemocultivos se aísla Streptococcus bovis sensible a penicilina.', 'Tras iniciar tratamiento de endocarditis, ¿Cuál de las siguientes exploraciones nos podría ayuda en el diagnóstico?', '[{"position": 1, "text": "Prueba de tolerancia a la glucosa."}, {"position": 2, "text": "Rx Tórax."}, {"position": 3, "text": "Endoscopia digestiva alta."}, {"position": 4, "text": "Colonoscopia."}, {"position": 5, "text": "Ecografía abdominal."}]'::jsonb, 5, 4, 'definitiva', 'Otro regalo de pregunta, la asociación de endocarditis por S.bovis y el cáncer de colon. Por cierto, es gracioso que den Rx Tórax como prueba a realizar... ¿me estás diciendo que a un paciente con fiebre y disnea le haces antes una ecocardio que una rx de tórax simple? Y por otro lado... ¿por qué los que escriben el MIR no hacen las preguntas más cortas sin tanta vuelta? Si lo que quieren es preguntar la prueba a realizar a un paciente con endocarditis por S.bovis, pues podrían lanzar la pregunta directamente sin contarnos hasta los lunares del paciente...', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-cb654dbf20d2', '69939fa3132e407389ccc8d1d270c59ca989a2c9', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'A un hombre de 55 años, padre de un hijo celiaco, con anemia ferropénica y aumento reciente del ritmo deposicional, se le ha realizado una determinación de los alelos HLA-DQ2 y HLA-DQ8 que ha resultado negativa.', '¿Qué estudio diagnóstico es el más apropiado en este caso?', '[{"position": 1, "text": "Determinación de anticuerpos antitransglutaminasa IgA."}, {"position": 2, "text": "Endoscopia digestiva alta con toma de biopsias duodenales."}, {"position": 3, "text": "Test de D-xilosa."}, {"position": 4, "text": "Evaluar la respuesta a dieta sin gluten."}, {"position": 5, "text": "Colonoscopia."}]'::jsonb, 5, 5, 'definitiva', 'Varón de edad media con anemia ferropénica y aumento del número de deposiciones, ¡¡hay que hacer una colonoscopia para descartar un cáncer colorrectal!! Si el HLA es negativo es muy poco probable que se trate de una celiaquía (elevado valor predictivo negativo).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-7567bba3b50c', '140376b84f13f0f7982faa508b5bccb45d1562c6', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 50 años que acude al servicio de urgencias por astenia, anorexia, pérdida de peso, ictericia, fiebre y dolor abdominal. No refiere antecedentes recientes de transfusión sanguínea, contactos sexuales de riesgo ni adicción a drogas de uso parenteral. Consumo habitual de 60 gramos diarios de alcohol durante los últimos cinco años, consumo que ha incrementado durante el mes previo por problemas familiares. Temperatura 38,5ºC, tensión arterial 100/60 mmHg. En la exploración física se observa desorientación temporo-espacial, malnutrición, asterixis, ictericia y hepatomegalia dolorosa. No ascitis ni datos de irritación peritoneal. En los exámenes de laboratorio destacan leucocitos 15.000/microlitro con 90% de polimorfonucleares, hematíes 3 millones/mm3, hemoglobina 10g/dl, volumen corpuscular medio 115 fl, bilirrubina 15 mg/dl de predominio directo, AST (GOT) 300 UI/L, ALT (GPT) 120 UI/L, GGT 635 UI/L, prolongación del tiempo de protrombina mayor del 50%.', '¿Cuál es el diagnóstico más probable del cuadro que presenta la paciente?', '[{"position": 1, "text": "Absceso hepático."}, {"position": 2, "text": "Colecistitis aguda."}, {"position": 3, "text": "Colangitis aguda."}, {"position": 4, "text": "Hepatitis alcohólica."}, {"position": 5, "text": "Pancreatitis aguda."}]'::jsonb, 5, 4, 'definitiva', 'Paciente con consumo perjudicial de alcohol (60g y mujer), fiebre alta, encefalopatía hepática (desorientación, asterixis), bilirrubina directa tan alta, ictericia, hepatomegalia dolorosa, coagulopatía (tiempo de protrombina elevado) y una elevación de transaminasas leve (inferior a 5 veces el límite superior de la normalidad) hacen pensar en una hepatitis aguda por alcohol.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-1d356b70362f', 'cdf6714d93b2818e01cab0d58f691afc35027e2c', NULL, NULL, NULL, false, false, 'Aparato Digestivo', NULL, '¿Qué enfermedad sospecharíamos en un paciente joven que refiere historia frecuente de disfagia a sólidos y a líquidos con impactaciones de alimentos repetidas, sin clínica de pirosis y en el que en la endoscopia oral se observan múltiples anillos esofágicos concéntricos con mucosa normal (aspecto traquealizado)?', '[{"position": 1, "text": "Esofagitis herpética."}, {"position": 2, "text": "Esofagitis eosinofílica."}, {"position": 3, "text": "Esofagitis candidiásica."}, {"position": 4, "text": "Esofagitis por citomegalovirus."}, {"position": 5, "text": "Adenocarcinoma de esófago."}]'::jsonb, 5, 2, 'definitiva', 'El aspecto endoscópico de esófago traquealizado es muy típico de la esofagitis eosinofílica, que cursa con clínica de disfagia e impactaciones repetidas de alimentos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-d3331ba7c806', 'e5a376fa061e0c7ff76422d6f855a01eb369b247', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 37 años afecta de una colitis ulcerosa extensa, presenta un brote grave por el que se inicia tratamiento con prednisona en dosis de 1 mg/kg. Tras una semana de tratamiento, la paciente no presenta mejoría.', '¿Cuál es la siguiente medida terapéutica a realizar?', '[{"position": 1, "text": "Colectomía subtotal de urgencia y en un segundo tiempo prostectomía y reservorio ileoanal."}, {"position": 2, "text": "Asociar un inmunosupresor como azatioprina."}, {"position": 3, "text": "Asociar mesalazina en dosis de 4g al día oral y triamcinolona rectal 1 aplicación cada 12 horas."}, {"position": 4, "text": "Ciclosporina endovenosa 2mg/kg."}, {"position": 5, "text": "Debe valorarse el tratamiento con etanercept (un anticuerpo anti-TNFa)."}]'::jsonb, 5, 4, 'definitiva', 'Cuando un brote grave no responde a corticoterapia iv a dosis plenas (1mg/kg de peso) hay que pasar a ciclosporina o infliximab. Etanercept no está aprobado en Europa para la enfermedad inflamatorio intestinal (de momento).', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-c57a932ba097', '6243c401154be92870fe5ed65e3bb8f00a72e623', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 65 años de edad con antecedentes de dolores articulares en tratamiento con antiinflamatorios que es remitida a estudio por presentar anemia. En los estudios complementarios presenta hematíes 3.164.000, Hto. 32%, Hb 11g/dl, VCM 69 fl, Leucocitos 7800, Plaquetas 370.000, PCR 0,29 mg/dl, Fe 20ng/ml, Ferritina 18 ng/ml, Glucosa 105 mg/dl, GOT, GPT, GGT, F.Alcalina, Bilirrubina total, Colesterol, Creatinina, Calcio y Fósforo normales. Ac.antitransglutaminasa y Ac antigliadina negativos. Gastroscopia: hernia de hiato de 3 cm, resto sin alteraciones. Colonoscopia: hasta ciego, aislados divertículos en sigma. Tránsito intestinal sin alteraciones. Ecografía de abdomen sin alteraciones.', '¿Cuál de las exploraciones que se enumeran a continuación le parece más adecuada para completar el estudio?', '[{"position": 1, "text": "Biopsia de yeyuno."}, {"position": 2, "text": "Arteriografía."}, {"position": 3, "text": "Cápsula endoscópica."}, {"position": 4, "text": "Radioisótopos."}, {"position": 5, "text": "RM pélvica."}]'::jsonb, 5, 3, 'definitiva', 'Se trata de un estudio de anemia ferropénica con gastroscopia y colonoscopia normales, habiéndose descartado posible celiaquía. Nos faltan por ver yeyuno e íleon, por lo que habrá que realizar una cápsula endoscópica. En una anemia ferropénica siempre hay que descartar causa digestiva de la misma.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-0952644be4fd', 'c5a93e05e8d710b20e957d6b9336efe75279665b', NULL, NULL, NULL, false, false, 'Aparato Digestivo', 'Mujer de 80 años que consulta por presentar, desde hace 1 mes, aumento progresivo del perímetro abdominal. Durante los 4-5 meses previos nota astenia, anorexia y adelgazamiento no precisado. En la exploración física se aprecia ascitis a tensión y edemas maleolares, sin otros signos relevantes. Una ecografía y TAC de abdomen demuestran la presencia de ascitis, de densidad homogénea, sin apreciarse implantes peritoneales ni masas abdominales o pélvicas. Hígado, páncreas, suprarrenales, bazo y riñones sin hallazgos significativos. Se realiza paracentesis a través de aguja gruesa, obteniéndose con dificultad un líquido algo amarillento, denso y gelatinoso.', '¿Cuál es la etiología más probable?', '[{"position": 1, "text": "Descompensación hidrópica secundaria a cirrosis hepática."}, {"position": 2, "text": "Ascitis quilosa por linfoma no Hodgkin."}, {"position": 3, "text": "Tuberculosis peritoneal."}, {"position": 4, "text": "Metástasis peritoneal de adenocarcinoma."}, {"position": 5, "text": "Ascitis secundaria a pericarditis constrictiva."}]'::jsonb, 5, 2, 'definitiva', 'Las características del líquido que nos describen son lechosas, es decir, líquido ascítico quiloso. Teniendo en cuenta la edad de la paciente y el síndrome constitucional que nos describen, lo más probable es que sea un linfoma no Hodgkin y no una tuberculosis, que también cursa con líquido ascítico quiloso, dado que no mencionan clínica infecciosa. El resto de las entidades que nos ofrecen no cursan con líquido ascítico quiloso.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-9e103afe20bd', 'edca6ea6738ef7b978f3807a776b14c2b9ac1a58', NULL, NULL, NULL, false, false, 'Endocrinología', 'Un hombre de 62 años con una diabetes mellitus tipo 2 de 10 años de evolución realiza tratamiento con metformina y sitagliptina. Hace ejercicio físico escaso y realiza una dieta adecuada. En los últimos 6 meses ha perdido peso y tiene más astenia. Sus controles glucémicos se han deteriorado pasando de glucemias basales de 110-140 mg/dl a glucemias de 170-200 mg/dl, así como su hemoglobina glicosilada que ha pasado de 7,1 a 8,5%.', 'La medida terapéutica más adecuada a realizar es:', '[{"position": 1, "text": "Aumentar la ingesta de proteínas e hidratos de carbono de cadena larga en la dieta para mejorar la astenia y la pérdida de peso."}, {"position": 2, "text": "Asociar al tratamiento una dosis de insulina basal."}, {"position": 3, "text": "Asociar al tratamiento ascarbosa."}, {"position": 4, "text": "Sustituir sitagliptina por pioglitazona."}, {"position": 5, "text": "Sustituir metformina por glimepirida."}]'::jsonb, 5, 2, 'definitiva', 'Asociar al tratamiento una dosis de insulina basal. Pregunta esperable de un tema muy importante: la diabetes y su tratamiento. Paciente mal controlado con metformina y sitagliptina con discreta clínica cardinal (pérdida de peso, astenia). La mejor opción es la insulina para controlar los síntomas cardinales y disminuir la HbA1c a < 7%.', false, NULL, true, 'enunciado sin forma interrogativa: revisar el corte caso/pregunta', 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-061065a658da', '03fd6b03919d5198e0bc039b4f499f4f8e410347', NULL, NULL, NULL, false, false, 'Endocrinología', 'Hombre e 54 años que acude a revisión en su empresa. Se detecta un índice de masa corporal de 32,8 kg/m2 y glucemia en ayunas 138 mg/l. Un mes después, glucemia 13 mg/dl.', '¿Qué recomendación terapéutica efectuaría en primer lugar?', '[{"position": 1, "text": "Administrar metformina."}, {"position": 2, "text": "Prescribir una sulfonilurea."}, {"position": 3, "text": "Cambios conductuales. Dieta y ejercicio físico."}, {"position": 4, "text": "Insulina antes de cada comida."}, {"position": 5, "text": "Tomar acarbosa por la noche, antes de acostarse."}]'::jsonb, 5, 3, 'definitiva', 'Cambios conductuales: dieta y ejercicio físico. Es lo primero que hacemos ante el diagnóstico de una diabetes tipo 2. Pregunta bonita para recordar que antes de cualquier fármaco, hay que insistir en los cambios de hábitos. Seguidamente pautaríamos Metformina.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-018465bf11f0', 'e118951346f98646af2ed190b4373d14adafa51a', NULL, NULL, NULL, false, false, 'Enfermedades Infecciosas', 'Una mujer de 40 años ingresa en el Servicio de Urgencias con fiebre de 38ºC y dolor lumbar derecho. En la analítica destacan 25000 leucocitos/mm3 con desviación izquierda y en la eco abd se evidencia una litiasis coraliforme.', '¿Qué microorganismo esperamos encontrar?', '[{"position": 1, "text": "Escherichia coli."}, {"position": 2, "text": "Enterococcus faecalis."}, {"position": 3, "text": "Salmonella typhi."}, {"position": 4, "text": "Candida albicans."}, {"position": 5, "text": "Proteus mirabilis."}]'::jsonb, 5, 5, 'definitiva', 'Pregunta de epidemiología compartida con URO. Las litiasis coraliformes se asocian a gérmenes desdobladores de la urea: Proteus en 1º lugar, Pseudomonas, Klebsiella y algunos estafilococos.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-93e5c908ff10', '56b86eb06d4fde4a19d6804372fb57943df7224d', NULL, NULL, NULL, false, false, 'Endocrinología', 'Una mujer de 45 años acude a la consulta remitida desde Cirutía con el diagnóstico de un tumor neuroendocrino diagnosticado tras pancreatectomía parcial por un tumor de 2 cms en cola del páncreas. El tumor había sido detectado de forma casual en una TAC abdominal solicitada para completar en estudio de un quiste simple hepático. Interrogando a la paciente destacan como antecedentes reglas irregulares, estando en amenorrea desde hace 6 meses, y cólicos renoureterales de repetición desde los 20 años de edad por los que ha precisado litotricia en varias ocasiones. Además presenta antecedentes familiares de cólicos renoureterales.', '¿Cuál es su sospecha diagnóstica?', '[{"position": 1, "text": "Una neoplasia endocrina múltiple tipo 1 o Síndrome de Wermer."}, {"position": 2, "text": "Una neoplasia endocrina múltiple tipo 2 A o Síndrome de Sipple."}, {"position": 3, "text": "Una neoplasia endocrina múltiple tipo 2B."}, {"position": 4, "text": "Somatostatinoma."}, {"position": 5, "text": "Un tumor neuroendocrino productor de PTH."}]'::jsonb, 5, 1, 'definitiva', 'Pregunta clínica muy bonita de MEN. Tumor neuroendocrino pancreático + adenoma hipofisario (prolactinoma) + hiperparatiroidismo (cólicos renoureterales en gente joven): MEN 1. Dificultad media ya que hay que saber la triada de MEN y reconocer los diferentes tumores.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-f834a0cd5ace', '33bc51d7e648914bb7e9bfb720c578e8b90465af', NULL, NULL, NULL, false, false, 'Farmacología', 'Mujer de 70 años con antecedentes de hipertensión e insuficiencia cardiaca moderada que acude a la consulta por presentar tos persistente y seca que se inicia como una sensación de picor en la garganta.', '¿Cuál es el fármaco sospechoso de causar la clínica y la alteración analítica de la paciente?', '[{"position": 1, "text": "Hidroclorotiazida."}, {"position": 2, "text": "Bisoprolol."}, {"position": 3, "text": "Furosemida."}, {"position": 4, "text": "Enalapril."}, {"position": 5, "text": "Hidralazina."}]'::jsonb, 5, 4, 'definitiva', 'Son efectos adversos típicos de los IECAs, en el caso de la tos suele ser seca e irritativa y aparece hasta en el 3% de pacientes. También puede aparecer hiperpotasemia en el 1%.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-05265c60efe9', '1b7f7407706a8692e2dd3551baeb613d06ab3e25', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'En un paciente con cirrosis hepática y ascitis, que desarrolla un derrame pleural con los siguientes datos en el líquido pleural: LDH 45 U/L (sérica 220 U/L), cociente proteínas pleura/suero 0,3 y cociente LDH pleura/suero 0,2.', '¿Cuál sería la actitud adecuada?', '[{"position": 1, "text": "Debe ampliarse el estudio del líquido con recuento celular, glucosa, pH. ADA, colesterol y cultivo."}, {"position": 2, "text": "Biopsia pleural ciega."}, {"position": 3, "text": "Vidcotoracoscopia diagnóstica."}, {"position": 4, "text": "Antibioterapia empírica por sospecha de derrame paraneumónico."}, {"position": 5, "text": "Continuar el tratamiento de su hepatopatía."}]'::jsonb, 5, 5, 'definitiva', 'Describen parametros de liquido pleural de trasudado, por lo que si el paciente no esta en insuficiencia cardiaca se trata de una descompensacion hidropica. No necesita otros estudios.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-6de55a510da1', 'b4fa72e2f5af41202a59c111c8c6a411d220d043', NULL, NULL, NULL, false, false, 'Neumología y Cirugía Torácica', 'Paciente de 50 años que presenta un derrame pleural con las siguientes características: aspecto pajizo, pH 7.3, cociente de proteínas pleura/suero 0.8, cociente de LDH pleura/suero 0.9, Gram y Ziehl negativos, lípidos totales, colesterol y triglicéridos normales, células mesoteliales <5%, intensa linfocitosis sin atipias, ADA 64 U/l.', '¿Qué diagnóstico le sugiere?', '[{"position": 1, "text": "Empicma pleural."}, {"position": 2, "text": "Derrame pleural por insuficiencia cardiaca (trasudado)."}, {"position": 3, "text": "Mesotelioma pleural."}, {"position": 4, "text": "Derrame pleural tuberculoso."}, {"position": 5, "text": "Derrame secundario a infarto pulmonar."}]'::jsonb, 5, 4, 'definitiva', 'Es un exudado linfocitario cuyos principales diagnosticos son el tumoral y la pleuritis tuberculosa. No dan el valor de la glucosa que deberia de estar descendida, pero si la citologia que muestra ausencia de celulas malignas por lo que nos quedamos con la pleuritis tuberculosa. Otros diagnosticos posible como linfoma, no estan reseñados en las respuestas.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos'),
('casimedicos-19ee00136f6e', '26d58f4683be8ec0f32ed2853668433c4212b20e', NULL, NULL, NULL, false, false, 'Anestesiología y Reanimación', 'Acude a su consulta un hombre de 80 años de edad para valoración de una colecistectomía programada por laparoscopica. Presenta antecedentes de hipertesión arterial en tratamiento desde hace 10 años. Niega enfermedad cardiaca ni pulmonar. No presenta dolor torácico. Tiene una vida activa y diariamente acude al gimnasio en donde alterna natacion y caminar por la cinta durante al menos una hora. Tratamiento habitual: nebivolol 5 mg cada 24 horas e hidroclorotiazida 12,5 mg al dia. Exploración física: peso 73 kgs; talla 179 cm; presión arterial 138/80 mmHg; frecuencia cardiaca 60 latidos/minuto.', 'No se auscultan soplos ¿Cuál de los siguientes es el planteamiento preoperatorio más adecuado?', '[{"position": 1, "text": "Realizar una prueba de esfuerzo."}, {"position": 2, "text": "Realizar una ecocardiografía"}, {"position": 3, "text": "Realizar una gammagrafía con talio y dipiridamol"}, {"position": 4, "text": "Realizar electrocardiograma."}]'::jsonb, 4, 4, 'definitiva', 'Pregunta totalmente regalada, de un señor más sano que yo que se va a operar de una cirugía de bajo riesgo de manera programada. La respuesta es evidentemente la 4. De haber existido una quinta opción habría sido que no hace falta hacer nada, lo cual podría haber generado alguna duda en el estudiante, pero al no existir la pregunta es un caramelito. Aunque existen muchos protocolos sobre los preoperatorios, casi tantos como hospitales, la pregunta lo pone fácil al poner a un paciente muy mayor, de 80 años. El rango de edad a partir del cual se considera obligatorio solicitar un ECG varía entre los 45, 50, 60 o incluso hay quien dice 70 años. Por ej: > 50 años: siempre, excepto si se dispone de ECG previo < 50 años: sólo si hay cardiopatía conocida o sospechada (FRCV), DM severa, hipertiroidismo o EPOC severo.', false, NULL, false, NULL, 'ixa-ehu/antidote-casimedicos (CC0-1.0)', 'https://github.com/ixa-ehu/antidote-casimedicos')
